  ui_story_5053_50530001_8_dialog_content = "Adik dan ibu saya sedang menunggu di taman. Kita harus pergi.",
  ui_story_5053_50530001_9_option_content = "Oke.",
  ui_story_5053_50530001_10_dialog_content = "Lihat, saya tahu Carleen akan berada di sini.",
