  ui_story_5053_50530001_22_dialog_content = "Saya melihat saya tidak bisa membodohi Anda dengan ini.",
  ui_story_5053_50530001_23_dialog_content = "Ini benar-benar kamu! Kamu kembali!",
  ui_story_5053_50530001_24_dialog_content = "Tapi siapa orang mencurigakan di sebelahmu?",
  ui_story_5053_50530001_25_dialog_content = "Ini PlayerName. Kita berdua akan jalan-jalan denganmu mulai sekarang, tidak apa-apa?",
  ui_story_5053_50530001_26_dialog_content = "...",
  ui_story_5053_50530001_27_dialog_content = "Bagaimana kalau menyapa PlayerName, Carleen?",
