  ui_story_5053_50530001_30_dialog_content = "... tetapi begitu Anda menghabiskan waktu bersamanya, Anda akan menemukan bahwa dia sebenarnya adalah anak yang pemalu.",
  ui_story_5053_50530001_31_dialog_content = "Ibu!",
  ui_story_5053_50530001_32_dialog_content = "Baiklah, sudah larut. Saatnya kami berangkat.",
