  ui_story_5053_50530001_59_dialog_content = "Apa yang kita lakukan sekarang, PlayerName?",
  ui_story_5053_50530001_60_dialog_content = "Jangan khawatir, jika Tuan Kota dapat memanfaatkan angin, pertempuran akan segera berakhir.",
  ui_story_5053_50530001_61_dialog_content = "A-aku harus memberitahu Ayah tentang itu!",
