  ui_story_5053_50530001_73_dialog_content = "Hahahahaha, kau Tuan Kota yang hebat. Mengapa Anda masih suka menceritakan lelucon yang buruk?",
  ui_story_5053_50530001_74_dialog_content = "Lihat, Anda bahkan tertegun PlayerName ke dalam keheningan.",
  ui_story_5053_50530001_75_dialog_content = "Sudah berapa lama kamu duduk di sini, PlayerName?",
  ui_story_5053_50530001_76_dialog_content = "Anak-anak tidak boleh menguping pembicaraan orang dewasa.",
  ui_story_5053_50530001_77_dialog_content = "Aku tidak mendengar apa-apa!",
  ui_story_5053_50530001_78_dialog_content = "Hah, kamu yakin?",
  ui_story_5053_50530001_79_dialog_content = "Berhenti menggoda, wajahnya memerah.",
  ui_story_5053_50530001_80_dialog_content = "Apakah Anda tidak memiliki berita penting, Daniel?",
  ui_story_5053_50530001_81_dialog_content = "Benar, berbicara tentang itu...",
  ui_story_5053_50530001_82_dialog_content = "Saya ingin Anda bersiap untuk apa yang akan saya ceritakan kepada Anda, PlayerName.",
  ui_story_5053_50530001_83_dialog_content = "Baiklah…",
  ui_story_5053_50530001_84_dialog_content = "Orang tua dan orang-orang Anda tidak binasa.",
  ui_story_5053_50530001_85_dialog_content = "Mereka bertahan hidup hampir bertahun-tahun yang lalu, dan diam-diam menetap di sebidang tanah terpencil milik Schwartz keluarga.",
  ui_story_5053_50530001_86_dialog_content = "Saya memberi tahu mereka untuk datang menemui Anda. Mereka harus berada di sini kapan saja sekarang.",
