  ui_story_5053_50530001_88_dialog_content = "Apakah Anda mengerti apa yang saya katakan, PlayerName?",
  ui_story_5053_50530001_89_dialog_content = "Apa masalahnya? Kenapa matamu berkaca-kaca?",
  ui_story_5053_50530001_90_dialog_content = "PlayerName? PlayerName!",
