  ui_story_5053_50530001_95_dialog_content = "Orang tua dan saudaraku! Di mana mereka?!",
  ui_story_5053_50530001_96_dialog_content = "Apakah semua itu tidak nyata...?",
  ui_story_5053_50530001_97_dialog_content = "Anda tampak agak sedih, anak muda.",
  ui_story_5053_50530001_98_dialog_content = "Meskipun saya tahu itu tidak nyata, saya masih ingin melihat keluarga saya ...",
  ui_story_5053_50530001_99_dialog_content = "Terperosok ke dalam masa lalu palsu bukanlah hal yang baik. Fokus pada saat ini, PlayerName!",
  ui_story_5053_50530001_100_dialog_content = "Saat ini? Dimana saya...?",
  ui_story_5053_50530001_101_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5053_50530001_102_dialog_content = "Apakah itu lonceng jam...? Aku ingat sekarang!",
  ui_story_5053_50530001_103_dialog_content = "Kami baru saja melawan monster yang muncul entah dari mana sampai hari hampir berakhir...",
  ui_story_5053_50530001_104_dialog_content = "Jam akan berdentang pukul dua belas!",
