  ui_story_5053_50530001_115_dialog_content = "Datanglah padaku, Mia, PlayerName!",
  ui_story_5053_50530001_116_dialog_content = "Oh, tidak, aku tidak bisa menahan Caleb!",
  ui_story_5053_50530001_117_dialog_content = "Maaf, adikku, aku tidak bisa bersamamu lagi...",
  ui_story_5053_50530001_118_dialog_content = "Kita tidak bisa... meninggalkan siapa pun!",
  ui_story_5053_50530001_119_dialog_content = "PlayerName?!",
  ui_story_5053_50530001_120_dialog_content = "Kaleb!",
  ui_story_5053_50530001_121_option_content = "Pegang tanganku!",
  ui_story_5053_50530001_122_dialog_content = "Agh!",
  ui_story_5053_50530001_123_dialog_content = "Berhenti melakukan peregangan, PlayerName. Ayahku kehilangan cengkeramannya padamu!",
  ui_story_5053_50530001_124_option_content = "Saya tidak bisa menyerah!",
  ui_story_5053_50530001_125_dialog_content = "PlayerName!!!",
  ui_story_5053_50530001_126_dialog_content = "Kena kau! Aku punya Kaleb!",
  ui_story_5053_50530001_127_dialog_content = "PlayerName...?",
  ui_story_5053_50530101_1_dialog_content = "<color=#e8d9bb>Kicau, kicau!</color>",
  ui_story_5053_50530101_2_dialog_content = "(Apakah itu burung yang saya dengar?)",
  ui_story_5053_50530101_3_dialog_content = "(Burung-burung di Eraveil selalu membangunkan saya lebih awal. Saya bahkan tidak bisa tidur.)",
  ui_story_5053_50530101_4_dialog_content = "(Tapi…)",
  ui_story_5053_50530101_5_dialog_content = "(Mengapa saya berbaring di rumput ?!)",
  ui_story_5053_50530101_6_dialog_content = "(Bukan, ini bukan Eraveil... Ini Lumopolis?!)",
  ui_story_5053_50530101_7_dialog_content = "(Benar, saya di Lumopolis! Mia dan saya pergi ke Crystal of Eternal Memory, dan kemudian...)",
  ui_story_5053_50530101_8_dialog_content = "(Kami berhasil keluar pada detik terakhir!)",
  ui_story_5053_50530101_9_dialog_content = "...",
  ui_story_5053_50530101_10_dialog_content = "Mia?",
  ui_story_5053_50530101_11_dialog_content = "...",
  ui_story_5053_50530101_12_dialog_content = "...",
  ui_story_5053_50530101_13_dialog_content = "Jakine! Kaleb! Semua orang...",
  ui_story_5053_50530101_14_dialog_content = "<size=30>Pelankan suaramu.</size>",
  ui_story_5053_50530101_15_dialog_content = "<size=30>Penguasa Kota?!</size>",
  ui_story_5053_50530101_16_dialog_content = "<size=30>Kenapa kamu berbisik?</size>",
  ui_story_5053_50530101_17_dialog_content = "<size=30>Lihat ke sana.</size>",
  ui_story_5053_50530101_18_dialog_content = "Semuanya sudah diatur, tuanku. Gerbong menunggu di luar dan siap berangkat kapan saja.",
  ui_story_5053_50530101_19_dialog_content = "Dipahami. Naik gerbong, Carleen.",
  ui_story_5053_50530101_20_dialog_content = "Aku... Aku ingin tinggal bersama Ibu!",
  ui_story_5053_50530101_21_dialog_content = "Semua orang di Lumopolis sedang menunggu kita, Carleen. Anda harus mengetahui tujuan dan kewajiban Anda.",
  ui_story_5053_50530101_22_dialog_content = "... Ya, saya bersedia.",
  ui_story_5053_50530101_23_dialog_content = "Aku akan menunggumu di gerbong, Ayah.",
  ui_story_5053_50530101_24_dialog_content = "Putri Carleen mungkin masih muda, tapi dia memiliki pandangan jauh ke depan dan pengertian. Ini adalah berkah bagi masyarakat Lumopolis.",
  ui_story_5053_50530101_25_dialog_content = "...",
  ui_story_5053_50530101_26_dialog_content = "Apakah Anda khawatir tentang Lady Joshua, Tuanku?",
  ui_story_5053_50530101_27_dialog_content = "Joshua selalu dalam kesehatan yang baik dan dia biasanya tidak mengeluh tentang perasaan di bawah cuaca. Apalagi di hari seperti ini.",
  ui_story_5053_50530101_28_dialog_content = "Dia cukup sibuk akhir-akhir ini, mengadvokasi kebijakan baru kepada istri bangsawan. Saya membayangkan itu mengambil tol pada dirinya.",
  ui_story_5053_50530101_29_dialog_content = "Sudahlah.",
  ui_story_5053_50530101_30_dialog_content = "Anda akan tinggal di belakang dan menjaganya, Ms. Rot. Perbarui saya jika terjadi sesuatu.",
  ui_story_5053_50530101_31_dialog_content = "Baik tuan ku.",
  ui_story_5053_50530101_32_dialog_content = "Apakah itu Tuan Kota muda? Bagaimana ini bisa terjadi? Apa itu berarti...",
  ui_story_5053_50530101_33_dialog_content = "Kami tidak berhasil.",
  ui_story_5053_50530101_34_dialog_content = "Ayah...",
  ui_story_5053_50530101_35_dialog_content = "Ayah? Dan PlayerName...",
  ui_story_5053_50530101_36_dialog_content = "Apakah kita kembali ke kenyataan sekarang?",
  ui_story_5053_50530101_37_dialog_content = "Ini bukan dunia nyata.",
  ui_story_5053_50530101_38_dialog_content = "Apa? Ini bukan kenyataan? Tapi jika kita tidak keluar sebelum hari berakhir...",
  ui_story_5053_50530101_39_dialog_content = "Bukankah kita sekarang terjebak di dalam Crystal of Eternal Memory selamanya?",
  ui_story_5053_50530101_40_dialog_content = "Saya tidak yakin. Kita harus bertanya Jakine.",
  ui_story_5053_50530101_41_dialog_content = "Zzz...",
  ui_story_5053_50530101_42_dialog_content = "Jakine!",
  ui_story_5053_50530101_43_dialog_content = "Berhenti menyenggolku, Whisper. Biarkan aku tidur lagi...",
  ui_story_5053_50530101_44_dialog_content = "Jakine, ini aku, PlayerName! Ini darurat, jadi bangunlah!",
  ui_story_5053_50530101_45_dialog_content = "Huh apa? Oh itu kamu, PlayerName. Menguap...",
  ui_story_5053_50530101_46_dialog_content = "Hei, dimana aku—",
  ui_story_5053_50530101_47_dialog_content = "Ssst!",
  ui_story_5053_50530101_48_dialog_content = "Apakah Anda mendengar itu?",
  ui_story_5053_50530101_49_dialog_content = "Ya, itu mungkin berasal dari semak-semak di sana.",
  ui_story_5053_50530101_50_dialog_content = "Mari kita lihat.",
  ui_story_5053_50530101_51_dialog_content = "Mencicit...",
  ui_story_5053_50530101_52_dialog_content = "Oh, itu hanya kelinci!",
  ui_story_5053_50530101_53_dialog_content = "<size=50>Mencicit... Mencicit!</size>",
  ui_story_5053_50530101_54_dialog_content = "Itu membuatku takut. Saya tidak tahu kelinci membuat suara!",
  ui_story_5053_50530101_55_dialog_content = "Sudahlah, hanya kelinci. Tidak ada ancaman sama sekali. Mari kita berputar-putar di sana.",
  ui_story_5053_50530101_56_dialog_content = "Hampir saja...",
  ui_story_5053_50530101_57_dialog_content = "Untungnya, saya cukup cerdas untuk mengubah Caleb menjadi kelinci dan mengalihkan perhatian mereka!",
  ui_story_5053_50530101_58_dialog_content = "Ciit!",
  ui_story_5053_50530101_59_dialog_content = "Tapi tunggu dulu, kenapa kita bersembunyi?",
  ui_story_5053_50530101_60_dialog_content = "Kami masih berada di Crystal of Eternal Memory, Jakine.",
  ui_story_5053_50530101_61_dialog_content = "Apa? Mustahil! Mantranya tidak mungkin salah, dan aku yakin aku mengucapkannya dengan benar!",
  ui_story_5053_50530101_62_dialog_content = "Biarkan saya mundur di sini ...",
  ui_story_5053_50530101_63_dialog_content = "Kami berada di sana ketika hari berakhir dan jam menunjukkan pukul dua belas.",
  ui_story_5053_50530101_64_dialog_content = "Untuk keluar, mantra untuk <color=#FFB400>memundurkan waktu</color> Dan <color=#FFB400>keluar dari Crystal of Eternal Memory</color> harus dilemparkan secara bersamaan.",
  ui_story_5053_50530101_65_dialog_content = "Kami baru saja melihat Ms. Rot mengirim Young Schwartz Dan Carleen jauh, berarti...",
  ui_story_5053_50530101_66_dialog_content = "Mantra untuk keluar dari Crystal of Eternal Memory <color=#FFB400>gagal</color>, tapi yang memundurkan waktu <color=#FFB400>berhasil</color>?",
  ui_story_5053_50530101_67_dialog_content = "Mungkin monster itu ada hubungannya dengan itu?",
  ui_story_5053_50530101_68_dialog_content = "Oh benar, aku ingat hal itu! Sungguh rasa sakit yang menyeramkan di pantat!",
  ui_story_5053_50530101_69_dialog_content = "Itu terlihat menakutkan dengan banyak sayap padat di kepalanya.",
  ui_story_5053_50530101_70_dialog_content = "Itu seperti...",
  ui_story_5053_50530101_71_dialog_content = "Itu seperti malaikat keputusasaan yang gelap.",
  ui_story_5053_50530101_72_dialog_content = "Itulah apa itu, a <color=#FFB400>malaikat kegelapan</color>!",
  ui_story_5053_50530101_73_dialog_content = "Huh, sudahlah, aku akan merapal mantra keluar sekarang dan mengeluarkan semua orang dari sini!",
  ui_story_5053_50530101_74_dialog_content = "Anu…",
  ui_story_5053_50530101_75_dialog_content = "Ciit!",
  ui_story_5053_50530101_76_dialog_content = "Bagaimana kalau mengganti Paman Caleb dulu?",
  ui_story_5053_50530101_77_dialog_content = "Ups, hampir lupa semua tentang itu!",
  ui_story_5053_50530101_78_dialog_content = "Mutasi! Mutasi! Mutasi!",
  ui_story_5053_50530101_79_dialog_content = "Kembalikan Caleb kembali normal!",
  ui_story_5053_50530101_80_dialog_content = "Omong kosong!",
  ui_story_5053_50530101_81_dialog_content = "<color=#e8d9bb>Puf!</color>",
  ui_story_5053_50530101_82_dialog_content = "...",
  ui_story_5053_50530101_83_dialog_content = "Di dalam celah Crystal adalah tanah raksasa ...",
  ui_story_5053_50530101_84_dialog_content = "Tanah raksasa... kemana perginya?",
  ui_story_5053_50530101_85_dialog_content = "Selamat datang kembali, Kaleb!",
  ui_story_5053_50530101_86_dialog_content = "Kembali...?",
  ui_story_5053_50530101_87_dialog_content = "Saya kembali! Tapi aku masih belum punya ... Tikus kakakku!",
  ui_story_5053_50530101_88_dialog_content = "Eh, apa yang kamu katakan?",
  ui_story_5053_50530101_89_dialog_content = "Kamu sudah sangat aneh sejak awal, Caleb.",
  ui_story_5053_50530101_90_dialog_content = "Satu menit Anda pergi sendiri, selanjutnya Anda mencoba mencuri Crystal... Apa yang sebenarnya Anda lakukan?",
  ui_story_5053_50530101_91_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_5053_50530101_92_dialog_content = "Siapa itu? Apakah para penjaga melihat kita?",
  ui_story_5053_50530101_93_dialog_content = "Ambil senjatamu, Jakine...",
  ui_story_5053_50530101_94_dialog_content = "Kegelapan Angel ada di sini lagi!",
  ui_story_5053_50530101_95_dialog_content = "Disini?",
  ui_story_5053_50530102_1_dialog_content = "Disini?",
  ui_story_5053_50530102_2_dialog_content = "Aktifkan, bola kristal!",
  ui_story_5053_50530102_3_dialog_content = "Bagaimana Dark Angel menemukan kami di sini? Saya pikir kami mengatur ulang semuanya!",
  ui_story_5053_50530102_4_dialog_content = "I-Itu suara kakakku...",
  ui_story_5053_50530102_5_dialog_content = "Disini!",
  ui_story_5053_50530102_6_dialog_content = "Malam putih! Lindungi kami!",
  ui_story_5053_50530102_7_dialog_content = "Jangan kehilangan fokus dalam pertempuran, Caleb!",
  ui_story_5053_50530102_8_dialog_content = "Aku tidak menerima perintah darimu! Apa yang terjadi di sini...",
  ui_story_5053_50530102_9_dialog_content = "Letakkan senjatamu, penyusup!",
  ui_story_5053_50530102_10_dialog_content = "Beraninya kau memulai perkelahian di kediaman Tuan Kota?!",
  ui_story_5053_50530102_11_dialog_content = "Hai-yah!",
  ui_story_5053_50530102_12_dialog_content = "monster AA? Apa-apaan itu?!",
  ui_story_5053_50530102_13_dialog_content = "Bangun kembali!",
  ui_story_5053_50530102_14_dialog_content = "Oke oke...",
  ui_story_5053_50530102_15_dialog_content = "Sch... wartz...!",
  ui_story_5053_50530102_16_dialog_content = "...",
  ui_story_5053_50530102_17_dialog_content = "Mengapa Gelap Angel mengejar ayahku sepanjang waktu?",
  ui_story_5053_50530102_18_dialog_content = "Dan itu terus memanggil nama keluarga Anda. Apakah itu tahu kalian?",
  ui_story_5053_50530102_19_dialog_content = "Tapi aku tidak mengenalinya sama sekali...",
  ui_story_5053_50530102_20_dialog_content = "Aaaah—!",
  ui_story_5053_50530102_21_dialog_content = "Sovereign's Blade!",
  ui_story_5053_50530102_22_dialog_content = "Ugh...",
  ui_story_5053_50530102_23_dialog_content = "Kekuatanmu telah berkurang banyak sejak pertempuran pertama kita.",
  ui_story_5053_50530102_24_dialog_content = "Hai-yah!",
  ui_story_5053_50530102_25_dialog_content = "Namun, masih sangat mengganggu.",
  ui_story_5053_50530102_26_dialog_content = "Tolong biarkan aku mengambil komando! Meski kemampuan psikis saya jauh lebih lemah sekarang, saya masih bisa berkoordinasi!",
  ui_story_5053_50530102_27_dialog_content = "Terima kasih, tetapi saya memiliki prospek lain dalam pikiran.",
  ui_story_5053_50530102_28_dialog_content = "Anda harus tahu bagaimana menangani ini, kan, Mia?",
  ui_story_5053_50530102_29_dialog_content = "Aku? Anda memberi saya perintah ...?",
  ui_story_5053_50530102_30_dialog_content = "Tenang saja. Pikirkan saya sebagai bidak catur di tangan Anda.",
  ui_story_5053_50530102_31_dialog_content = "Katakan padaku, kemana aku harus pergi?",
  ui_story_5053_50530102_32_dialog_content = "Mungkin... kau bisa terus memancing malaikat itu ke depan, lalu aku bisa menyerangnya dari belakang?",
  ui_story_5053_50530102_33_dialog_content = "Tidak memadai!",
  ui_story_5053_50530102_34_dialog_content = "Nah, eh...",
  ui_story_5053_50530102_35_dialog_content = "Anda memiliki lebih dari satu bidak catur di tangan Anda!",
  ui_story_5053_50530102_36_dialog_content = "Maaf, saya tidak bisa...",
  ui_story_5053_50530102_37_dialog_content = "Santai, Mia, kamu bisa!",
  ui_story_5053_50530102_38_dialog_content = "PlayerName…",
  ui_story_5053_50530102_39_dialog_content = "(Ini praktis pelatihan ksatria. Apakah Anda mencoba untuk membimbing saya, Ayah?)",
  ui_story_5053_50530102_40_dialog_content = "(Aku tidak bisa mengecewakannya... Dan aku tidak bisa menghina para ksatria!)",
  ui_story_5053_50530102_41_dialog_content = "Ya, saya pikir saya mengerti ini ...",
  ui_story_5053_50530102_42_dialog_content = "Sementara ayahku mengalihkan perhatian Dark Angel... Jakine akan menyerang dari satu sisi dan, Paman, kamu menyerang dari sisi lain.",
  ui_story_5053_50530102_43_dialog_content = "Ayo luncurkan serangan segitiga untuk mengepung malaikat... Seharusnya berhasil, kan?",
  ui_story_5053_50530102_44_dialog_content = "Kedengarannya bagus! Sangat profesional, saya suka.",
  ui_story_5053_50530102_45_dialog_content = "Bukan rencana yang buruk. Ayo lakukan.",
  ui_story_5053_50530102_46_dialog_content = "Disini...",
  ui_story_5053_50530102_47_dialog_content = "Apa yang kamu? Mengapa Anda mengejar kami?",
  ui_story_5053_50530102_48_dialog_content = "Sch... wartz...!!!",
  ui_story_5053_50530102_49_dialog_content = "(Menahan? Ini jendela terbaik untuk menyerang!)",
  ui_story_5053_50530102_50_dialog_content = "Sekarang, semuanya!",
  ui_story_5053_50530102_51_dialog_content = "Maaf...!",
  ui_story_5053_50530102_52_dialog_content = "Aktifkan, Bola Kristal!",
  ui_story_5053_50530102_53_dialog_content = "Temui kekuatanku!",
  ui_story_5053_50530102_54_dialog_content = "Argh—!",
  ui_story_5053_50530102_55_dialog_content = "Semuanya kena. Kami sangat luar biasa!",
  ui_story_5053_50530102_56_dialog_content = "Sakit... sakit...!",
  ui_story_5053_50530102_57_dialog_content = "Sepertinya dia kesakitan...",
  ui_story_5053_50530102_58_dialog_content = "Jangan terlalu lunak padaku sekarang. Kegelapan Angel telah menyerang kita tanpa alasan!",
  ui_story_5053_50530102_59_dialog_content = "Anda benar, tidak ada belas kasihan dalam pertempuran.",
  ui_story_5053_50530102_60_dialog_content = "Apakah serangan kami berhasil?",
  ui_story_5053_50530102_61_dialog_content = "Agh... Aaaaaaah!",
  ui_story_5053_50530102_62_dialog_content = "Wah, jeritan yang menyeramkan.",
  ui_story_5053_50530102_63_dialog_content = "Oh tidak, ini menyala dan akan padam!",
  ui_story_5053_50530102_64_dialog_content = "A-Apa sekarang...?!",
  ui_story_5053_50530102_65_dialog_content = "Anda melakukannya dengan baik, Mia. Aku akan mengambil alih sekarang.",
  ui_story_5053_50530102_66_dialog_content = "Ayah...?",
  ui_story_5053_50530102_67_dialog_content = "Kalian semua, mundur!",
  ui_story_5053_50530102_68_dialog_content = "Sch...",
  ui_story_5053_50530102_69_dialog_content = "Sch... wartz...!!!",
  ui_story_5053_50530102_70_dialog_content = "Apakah Anda begitu putus asa untuk melawan saya satu lawan satu?",
  ui_story_5053_50530102_71_dialog_content = "Aku akan mengabulkan keinginanmu, kalau begitu.",
  ui_story_5053_50530102_72_dialog_content = "Sekarang, ambil batu nisanmu—!",
  ui_story_5053_50530102_73_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5053_50530102_74_dialog_content = "Aduh... Aduh...",
  ui_story_5053_50530102_75_dialog_content = "Ke mana ia pergi?",
  ui_story_5053_50530102_76_dialog_content = "Mungkin melarikan diri ke jalan di luar.",
  ui_story_5053_50530102_77_dialog_content = "Itu luar biasa, Tuhan Schwartz!",
  ui_story_5053_50530102_78_dialog_content = "Tidak peduli seberapa kuatnya, malaikat itu harus terluka parah. Saya ragu itu bisa sangat jauh.",
  ui_story_5053_50530102_79_dialog_content = "...",
  ui_story_5053_50530102_80_dialog_content = "Apakah Anda masih peduli tentang Dark Angel, Paman?",
  ui_story_5053_50530102_81_dialog_content = "Suaranya... Sudahlah, kakakku tidak akan pernah bisa menjadi monster.",
  ui_story_5053_50530102_82_dialog_content = "Luangkan waktu sekarang untuk mengucapkan mantra Anda, Jakine.",
  ui_story_5053_50530102_83_dialog_content = "Hah... Oh ya! Sekarang malaikat pengganggu akhirnya pergi, saya bisa mengeluarkan semua orang!",
  ui_story_5053_50530102_84_dialog_content = "Praesens iklan! Praesens iklan! Praesens iklan!",
  ui_story_5053_50530102_85_dialog_content = "Mari kita kembali ke kenyataan!",
  ui_story_5053_50530102_86_dialog_content = "Omong kosong!",
  ui_story_5053_50530102_87_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530102_88_dialog_content = "Saya tidak berpikir itu berhasil ...",
  ui_story_5053_50530102_89_dialog_content = "Biarkan saya mencoba lagi!",
  ui_story_5053_50530102_90_dialog_content = "Praesens iklan! Praesens iklan! Praesens iklan!",
  ui_story_5053_50530102_91_dialog_content = "Mari kita kembali ke kenyataan! Omong kosong!",
  ui_story_5053_50530102_92_dialog_content = "Anda yakin kata-katanya benar, Jakine?",
  ui_story_5053_50530102_93_dialog_content = "Tentu saja! Apakah semua orang berpegangan tangan? Biarkan saya memeriksa ... Ya!",
  ui_story_5053_50530102_94_dialog_content = "Saya pikir itu gagal terakhir kali karena sangat kacau sehingga tangan kami tidak bisa saling terhubung.",
  ui_story_5053_50530102_95_dialog_content = "Tapi kenapa kali ini masih tidak berhasil?",
  ui_story_5053_50530102_96_dialog_content = "Anda memegang Crystal untuk dunia ini saat Anda merapal mantra terakhir kali. Apa kau lupa kali ini?",
  ui_story_5053_50530102_97_dialog_content = "TIDAK, <color=#FFB400>Anda hanya membutuhkannya saat memutar ulang waktu</color>... Itu darurat gagal aman yang disiapkan ibuku.",
  ui_story_5053_50530102_98_dialog_content = "Tidak perlu untuk keberangkatan standar seperti ini!",
  ui_story_5053_50530102_99_dialog_content = "Apakah ada kemungkinan lain?",
  ui_story_5053_50530102_100_dialog_content = "Kecuali... <color=#FFB400>Tidak semua dari kita ada di sini</color>.",
  ui_story_5053_50530102_101_dialog_content = "Maksudmu?",
  ui_story_5053_50530102_102_dialog_content = "Karena masalah keamanan, seseorang harus mengaktifkan Kristal untuk memasukinya, dan setiap orang harus hadir agar seluruh rombongan pergi.",
  ui_story_5053_50530102_103_dialog_content = "Meskipun aku tidak sengaja melanggar peraturan itu dengan mantraku saat kita masuk, aku tidak bisa melakukan itu saat kita keluar!",
  ui_story_5053_50530102_104_dialog_content = "Kita semua ada di sini, kan? Saya tidak merindukan siapa pun ...",
  ui_story_5053_50530102_105_dialog_content = "Mungkinkah orang lain tertarik bersama kita?",
  ui_story_5053_50530102_106_dialog_content = "Atau mungkin, sebelum kami masuk, seseorang masuk melalui cara lain.",
  ui_story_5053_50530102_107_dialog_content = "Tapi aktivatornya sudah lama mati, jadi tidak mungkin kan?",
  ui_story_5053_50530102_108_dialog_content = "...",
  ui_story_5053_50530102_109_dialog_content = "Tuanku, k-kau datang sendiri?!",
  ui_story_5053_50530102_110_dialog_content = "Saya minta maaf karena ketidakmampuan kami telah mengganggu kedamaian Anda.",
  ui_story_5053_50530102_111_dialog_content = "Ya, benar. Bisakah Anda memberi tahu saya apa yang terjadi?",
  ui_story_5053_50530102_112_dialog_content = "Tentu saja. Beberapa orang tak dikenal masuk tanpa izin ke taman dan melawan monster.",
  ui_story_5053_50530102_113_dialog_content = "Salah satu penyusup terlihat dan berpakaian sangat mirip Putri Veronica, tapi aku tidak yakin...",
  ui_story_5053_50530102_114_dialog_content = "Veronica? Jadi begitu. Anda melakukan pekerjaan dengan baik.",
  ui_story_5053_50530201_1_dialog_content = "Jadi, kalian tidak ingin mencoba jajanan ini? Saya akan menyelesaikannya jika Anda tidak.",
  ui_story_5053_50530201_2_dialog_content = "Tidak percaya Anda masih dalam mood untuk itu.",
  ui_story_5053_50530201_3_dialog_content = "Kami baru saja bertengkar di taman Lady Joshua. Saya tidak tahu bagaimana cara membocorkannya padanya.",
  ui_story_5053_50530201_4_dialog_content = "Santai, santai! Stres tidak akan membawa kita kemana-mana!",
  ui_story_5053_50530201_5_dialog_content = "Aku iri padamu karena optimismemu.",
  ui_story_5053_50530201_6_dialog_content = "Joshua bukanlah seseorang yang akan menemui hukuman keras.",
  ui_story_5053_50530201_7_dialog_content = "Karena dia memerintahkan kami untuk dibawa ke sini dan bahkan menawarkan makanan penutup, itu jelas menunjukkan dia memperlakukan kami dengan hormat, bukan permusuhan.",
  ui_story_5053_50530201_8_dialog_content = "Kita benar-benar harus bersukacita.",
  ui_story_5053_50530201_9_dialog_content = "Jika <color=#FFB400>orang lain</color> juga hadir, kami mungkin sudah dipenjara sekarang.",
  ui_story_5053_50530201_10_dialog_content = "Orang lain? Siapa yang Anda bicarakan?",
  ui_story_5053_50530201_11_dialog_content = "...",
  ui_story_5053_50530201_12_dialog_content = "Dia berarti saya, saya yang lebih muda.",
  ui_story_5053_50530201_13_dialog_content = "Anda tidak begitu penuh dengan diri Anda sendiri, Tuhan Schwartz.",
  ui_story_5053_50530201_14_dialog_content = "P-Pokoknya, ini Lady Joshua dari dunia ini.",
  ui_story_5053_50530201_15_dialog_content = "Itu setidaknya membuktikan Kegelapan Angel bukan Nona Joshua.",
  ui_story_5053_50530201_16_dialog_content = "Kita seharusnya tidak khawatir tentang itu sekarang. Jakine, apakah Anda tahu cara mengetahui siapa lagi yang telah memasuki Crystal?",
  ui_story_5053_50530201_17_dialog_content = "Selalu ada jalan, tentu saja.",
  ui_story_5053_50530201_18_dialog_content = "Kami hanya membutuhkan Crystal of Eternal Memory untuk dunia ini.",
  ui_story_5053_50530201_19_dialog_content = "Selain menggunakannya untuk memundurkan waktu, kita bisa <color=#FFB400>lihat siapa yang ilusi dan siapa yang nyata dengan Crystal</color>.",
  ui_story_5053_50530201_20_dialog_content = "Meskipun masih tidak dapat menentukan lokasi yang tepat ...",
  ui_story_5053_50530201_21_dialog_content = "Tapi masalah dengan itu adalah memakan waktu. Anda hanya dapat memverifikasi satu orang dalam satu waktu.",
  ui_story_5053_50530201_22_dialog_content = "Ada banyak orang di Lumopolis...",
  ui_story_5053_50530201_23_dialog_content = "Tidak apa-apa! Selama kita memiliki fail-safe di tangan, kita dapat terus memutar ulang untuk mengulur waktu!",
  ui_story_5053_50530201_24_dialog_content = "Meskipun itu akan menghabiskan Lumina untuk memelihara dunia, jadi kita tidak bisa melakukannya tanpa pandang bulu.",
  ui_story_5053_50530201_25_dialog_content = "Maka prioritas utama kami adalah menemukan Crystal of Eternal Memory. Kita harus menempatkan Dark Angel masalah ditahan untuk saat ini.",
  ui_story_5053_50530201_26_dialog_content = "Apakah ini yang Anda cari?",
  ui_story_5053_50530201_27_dialog_content = "Apakah itu Crystal of Eternal Memory di tanganmu, Lady Joshua?",
  ui_story_5053_50530201_28_dialog_content = "Apakah Anda mendengar percakapan kami, Lady Joshua? Bagaimana kau tahu kami sedang mencari Crystal?",
  ui_story_5053_50530201_29_dialog_content = "Heheh, jangan khawatir tentang itu, anakku sayang, dan lihatlah Crystal.",
  ui_story_5053_50530201_30_dialog_content = "Tunggu... Bagaimana ini mungkin?!",
  ui_story_5053_50530201_31_dialog_content = "Wanita Joshua... Kamu adalah <color=#FFB400>Aurorian sejati</color>!",
  ui_story_5053_50530201_32_dialog_content = "!!!",
  ui_story_5053_50530201_33_dialog_content = "Kakak... Tapi... Apakah itu benar-benar kamu?",
  ui_story_5053_50530201_34_dialog_content = "Siapa lagi aku, jenius kecilku tersayang?",
  ui_story_5053_50530201_35_dialog_content = "...",
  ui_story_5053_50530201_36_dialog_content = "Kau yakin, Jakine?",
  ui_story_5053_50530201_37_dialog_content = "Tentu seperti yang pernah saya alami! Kecuali ada masalah dengan mataku!",
  ui_story_5053_50530201_38_dialog_content = "Ibu... apakah ini nyata?",
  ui_story_5053_50530201_39_dialog_content = "Tentu saja.",
  ui_story_5053_50530201_40_dialog_content = "Kamu masih terlihat sama seperti ketika kamu bergabung dengan para ksatria, seperti yang kuingat.",
  ui_story_5053_50530201_41_dialog_content = "*Mengendus* Itu... Itu karena...",
  ui_story_5053_50530201_42_dialog_content = "Itu karena Forsakin memodifikasi tubuh Veronica... Mia dan menjadikannya 13 tahun secara fisik.",
  ui_story_5053_50530201_43_dialog_content = "Tapi tunggu, aku melihat dengan mata kepalaku sendiri bahwa kau...",
  ui_story_5053_50530201_44_dialog_content = "Apa maksudmu?",
  ui_story_5053_50530201_45_dialog_content = "Pada Schwartz Hari Keluarga dua belas tahun yang lalu, Eclipsites menanam Benih Mia... di Veronica, selama misi para ksatria.",
  ui_story_5053_50530201_46_dialog_content = "Kemudian dia dikirim ke lab Illumina untuk apa yang disebut \"perawatan\", yang sebenarnya adalah jebakan yang dibuat oleh Eclipsites dan pengkhianat.",
  ui_story_5053_50530201_47_dialog_content = "Untuk menyelamatkan Veronica, Joshua pergi untuk melawan mereka sendiri.",
  ui_story_5053_50530201_48_dialog_content = "Penyelamatan itu sukses, tetapi entah bagaimana mereka menanam Benih Joshua demikian juga...",
  ui_story_5053_50530201_49_dialog_content = "Kemudian, setelah banyak penderitaan...",
  ui_story_5053_50530201_50_dialog_content = "Dia <color=#FFB400>memilih untuk mengakhiri hidupnya sendiri</color>.",
  ui_story_5053_50530201_51_dialog_content = "Namun, di sini Anda berada di Crystal. Mungkin Anda bisa menjelaskannya.",
  ui_story_5053_50530201_52_dialog_content = "Schwartz, beginikah cara Anda berbicara dengan istri yang belum pernah Anda temui selama dua belas tahun?!",
  ui_story_5053_50530201_53_dialog_content = "Tidak apa-apa, Kaleb. Daniel melakukan hal yang benar untuk melindungi semua orang.",
  ui_story_5053_50530201_54_dialog_content = "Baik, jika Anda berkata begitu.",
  ui_story_5053_50530201_55_dialog_content = "Kemudian saya harus mengambil di mana Daniel tinggalkan.",
  ui_story_5053_50530201_56_dialog_content = "Memang benar aku tersiksa oleh penderitaan...",
  ui_story_5053_50530201_57_dialog_content = "<color=#e8d9bb>Schwartz Manor, Beberapa Tahun Lalu</color>",
  ui_story_5053_50530201_58_dialog_content = "* Batuk * Bunuh saja aku, Daniel.",
  ui_story_5053_50530201_59_dialog_content = "Saya tidak akan mendengar permintaan seperti itu dari Anda, Joshua...",
  ui_story_5053_50530201_60_dialog_content = "Semakin saya menolak Benih itu, semakin keras benih itu menyiksa saya.",
  ui_story_5053_50530201_61_dialog_content = "Saya bisa merasakannya melawan saya untuk mengendalikan tubuh saya.",
  ui_story_5053_50530201_62_dialog_content = "Ada cara untuk membebaskanmu, percayalah!",
  ui_story_5053_50530201_63_dialog_content = "Apakah Anda ingat John sang tabib? Ya, kita bisa meminta bantuannya.",
  ui_story_5053_50530201_64_dialog_content = "Saya akan mengirim orang untuk segera melacaknya!",
  ui_story_5053_50530201_65_dialog_content = "Tenang saja dan tunggu aku.",
  ui_story_5053_50530201_66_dialog_content = "Tidak ada gunanya, Daniel, tidak ada gunanya...",
  ui_story_5053_50530201_67_dialog_content = "Urgh—",
  ui_story_5053_50530201_68_dialog_content = "Berhentilah berjuang dan menyerahlah padaku.",
  ui_story_5053_50530201_69_dialog_content = "Tidak akan pernah!",
  ui_story_5053_50530201_70_dialog_content = "Aku tidak akan pernah menyerahkan tubuhku, bahkan jika aku harus menusuk jantungku sendiri!",
  ui_story_5053_50530201_71_dialog_content = "Tidak, jatuhkan belati itu!",
  ui_story_5053_50530201_72_dialog_content = "Tidak akan pernah!",
  ui_story_5053_50530201_73_dialog_content = "Jatuhkan!!!",
  ui_story_5053_50530201_74_dialog_content = "Argh…",
  ui_story_5053_50530201_75_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5053_50530201_76_dialog_content = "Kristal Memori Abadi...?",
  ui_story_5053_50530201_77_dialog_content = "Apa yang sedang kamu lakukan? TIDAK!!!",
  ui_story_5053_50530201_78_dialog_content = "Mari kita menghidupkan kembali hari-hari emas di masa lalu...",
  ui_story_5053_50530201_79_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5053_50530201_80_dialog_content = "Apakah kamu baik-baik saja, Joshua? Suara keras apa itu?",
  ui_story_5053_50530201_81_dialog_content = "Kenapa kau tidak menjawab? Berhenti membuatku takut. saya masuk.",
  ui_story_5053_50530201_82_dialog_content = "J-Joshua...?",
  ui_story_5053_50530201_83_dialog_content = "<size=50>Saudari!!!</size>",
  ui_story_5053_50530201_84_dialog_content = "Benih itu membelah saya menjadi <color=#FFB400>dua kepribadian yang berbeda</color>.",
  ui_story_5053_50530201_85_dialog_content = "Salah satunya adalah saya yang normal, tetapi yang lainnya adalah monster yang tidak rasional dan gila.",
  ui_story_5053_50530201_86_dialog_content = "Saat tumbuh, ia mulai mencoba mengambil alih saya dan menyakiti orang-orang di sekitar saya.",
  ui_story_5053_50530201_87_dialog_content = "Saya tidak bisa membiarkan itu, jadi saya mulai melawannya.",
  ui_story_5053_50530201_88_dialog_content = "Bentrokan konstan antara kepribadian merobek pikiran saya setiap hari.",
  ui_story_5053_50530201_89_dialog_content = "Itu sama sekali tidak memengaruhi monster itu, jadi perlahan-lahan ia menang ...",
  ui_story_5053_50530201_90_dialog_content = "Saya berada di ambang kehancuran dan tahu saya akan kalah.",
  ui_story_5053_50530201_91_dialog_content = "Jadi aku memikirkan solusi yang tidak akan membuatku menang, tapi akan benar-benar mengalahkan monster itu—",
  ui_story_5053_50530201_92_dialog_content = "<color=#FFB400>Dan itu untuk menjebak kami berdua di Crystal of Eternal Memory</color>.",
  ui_story_5053_50530201_93_dialog_content = "Dengan keinginan mati, aku mengirim diriku dan monster itu ke dunia ini.",
  ui_story_5053_50530201_94_dialog_content = "Kami satu, jadi selama aku tidak pergi, itu harus tetap di sini bersamaku.",
  ui_story_5053_50530201_95_dialog_content = "Kami bertengkar satu sama lain untuk waktu yang sangat lama.",
  ui_story_5053_50530201_96_dialog_content = "Setelah jam berdentang tengah malam, kami menjadi bagian dari dunia ini sejak kami melanggar aturan.",
  ui_story_5053_50530201_97_dialog_content = "Kami kehilangan ingatan kami dan bergabung kembali untuk menjadi milik dunia ini Joshua, dan kami telah menghidupkan kembali hari yang sama ini berulang kali selama ini.",
  ui_story_5053_50530201_98_dialog_content = "Sampai kamu tiba.",
  ui_story_5053_50530201_99_dialog_content = "Kedatanganmu membangkitkan ingatan kami.",
  ui_story_5053_50530201_100_dialog_content = "Monster yang terbangun berjuang dan berpisah dariku.",
  ui_story_5053_50530201_101_dialog_content = "<color=#FFB400>Dia merampas semua kekuatanku</color> dan melarikan diri, mencoba keluar dari Crystal.",
  ui_story_5053_50530201_102_dialog_content = "Situasinya mengerikan, tapi kali ini...",
  ui_story_5053_50530201_103_dialog_content = "Aku tidak kesepian seperti dulu.",
  ui_story_5053_50530201_104_dialog_content = "...",
  ui_story_5053_50530201_105_dialog_content = "A-Sungguh cerita yang luar biasa... Jadi <color=#FFB400>Gelap Angel yang menyerang kami adalah Lady lain Joshua</color>?",
  ui_story_5053_50530201_106_dialog_content = "Gelap Angel? Anda menamakannya...? Bagaimanapun, ya, Anda bisa mengatakan itu.",
  ui_story_5053_50530201_107_dialog_content = "Hanya Joshua dan saya mengetahui rahasia percakapan itu, dan detailnya sama persis.",
  ui_story_5053_50530201_108_dialog_content = "Itu benar-benar kamu, Joshua...",
  ui_story_5053_50530201_109_dialog_content = "Sangat menyenangkan bahwa Anda akhirnya percaya padaku.",
  ui_story_5053_50530201_110_dialog_content = "Oh, Ibu... Kau nyata...",
  ui_story_5053_50530201_111_dialog_content = "Kau menangis lagi, anak kecil.",
  ui_story_5053_50530201_112_dialog_content = "Aku tidak percaya kau ada di sini, Joshua. Aku sudah mencari... dan tidak pernah menemukanmu...",
  ui_story_5053_50530201_113_dialog_content = "Betapa indahnya berbicara dengan Anda lagi setelah dua belas tahun ...",
  ui_story_5053_50530201_114_dialog_content = "(Benih, dua kepribadian... Kedengarannya sangat mirip dengan apa yang terjadi Mia.)",
  ui_story_5053_50530201_115_dialog_content = "(Kepribadian Mia adalah teman dan bergantung satu sama lain, tapi itu kebalikan dari Lady Joshua.)",
  ui_story_5053_50530201_116_dialog_content = "(Benih memiliki efek yang berbeda pada orang yang berbeda.)",
  ui_story_5053_50530201_117_dialog_content = "Omong-omong, Anda menyebutkan sesuatu tentang dua belas tahun yang lalu.",
  ui_story_5053_50530201_118_dialog_content = "Apakah saya sudah di sini selama dua belas tahun?",
  ui_story_5053_50530201_119_dialog_content = "Benar.",
  ui_story_5053_50530201_120_dialog_content = "Pantas kau terlihat sangat berbeda, Daniel.",
  ui_story_5053_50530201_121_dialog_content = "Saya mungkin tidak akan mengenali Anda jika bukan karena orang lain memanggil nama Anda.",
  ui_story_5053_50530201_122_dialog_content = "Tapi apa yang terjadi dengan mata dan wajahmu?",
  ui_story_5053_50530201_123_dialog_content = "Saya telah melalui terlalu banyak perang dan kekacauan untuk mengingat asal-usul bekas luka saya.",
  ui_story_5053_50530201_124_dialog_content = "Tapi aku masih ingat hari kau meninggalkanku, dan betapa dinginnya belati di dadamu saat disentuh...",
  ui_story_5053_50530201_125_dialog_content = "Daniel...",
  ui_story_5053_50530201_126_dialog_content = "Omong-omong, tubuh Lady Joshua dimakamkan, kan?",
  ui_story_5053_50530201_127_dialog_content = "Bisakah dia atau Dark Angel meninggalkan Crystal itu?",
  ui_story_5053_50530201_128_dialog_content = "Ya.",
  ui_story_5053_50530201_129_dialog_content = "Karena tubuhnya <color=#FFB400>tidak pernah terkubur</color>.",
  ui_story_5053_50530201_130_dialog_content = "Apa maksudmu?",
  ui_story_5053_50530201_131_dialog_content = "Hmph, ketika aku menemukannya, dia belum mati.",
  ui_story_5053_50530201_132_dialog_content = "Saya melakukan beberapa hal dan membawanya pulang untuk perawatan.",
  ui_story_5053_50530201_133_dialog_content = "Apa? Tapi kudengar seluruh kota menyaksikan pemakamannya, jadi apa yang kau lakukan...",
  ui_story_5053_50530201_134_dialog_content = "Saya menangani pemakaman Joshua secara pribadi, jadi tidak mungkin ada kesalahan langkah.",
  ui_story_5053_50530201_135_dialog_content = "Kecuali, Anda menggalinya.",
  ui_story_5053_50530201_136_dialog_content = "Astaga... Katakan padaku apa yang kau lakukan, adik kecil!",
  ui_story_5053_50530201_137_dialog_content = "Karena Anda bertanya ... Ya, saya memang menggali Anda.",
  ui_story_5053_50530201_138_dialog_content = "Untuk menghindari deteksi, saya menggali terowongan ke ruang bawah tanah dari kejauhan, jadi tidak ada yang lebih bijak.",
  ui_story_5053_50530201_139_dialog_content = "Anda menggalinya sendiri? Sejujurnya, saya tidak berharap Anda mampu bekerja seperti itu.",
  ui_story_5053_50530201_140_dialog_content = "Aku rela melakukan apapun untuk adikku.",
  ui_story_5053_50530201_141_dialog_content = "Tapi bagaimana Anda membodohi dokter dan petugas koroner? Apakah Anda menyuap mereka...?",
  ui_story_5053_50530201_142_dialog_content = "Tidak, saya hanya menggunakan beberapa ramuan.",
  ui_story_5053_50530201_143_dialog_content = "Saya juga terkejut, bahwa dokter-dokter hebat di Taman Lumopolis tertipu oleh trik-trik kecil saya.",
  ui_story_5053_50530201_144_dialog_content = "Tidak heran mereka tidak bisa menyembuhkan adikku.",
  ui_story_5053_50530201_145_dialog_content = "Anda tidak pernah serendah ini ketika Anda berdebat dengan instruktur di Dawn Akademi, Kaleb.",
  ui_story_5053_50530201_146_dialog_content = "Anda adalah tipe jenius yang ditemui Akademi mungkin sekali dalam seabad. Saya harap Anda menerapkan kecerdasan Anda pada hal yang benar.",
  ui_story_5053_50530201_147_dialog_content = "Kenapa kau harus bertindak atas kemauanmu sendiri, Caleb...",
  ui_story_5053_50530201_148_dialog_content = "Karena kamu tidak pernah ingin pergi Schwartz dan anak-anak, sementara dia membuat hidup Anda semakin sulit.",
  ui_story_5053_50530201_149_dialog_content = "Aku hanya ingin melindungimu.",
  ui_story_5053_50530201_150_dialog_content = "Saya sangat menyesal telah membuat Anda merasa begitu terbebani.",
  ui_story_5053_50530201_151_dialog_content = "Dia begini karena kamu selalu memanjakannya.",
  ui_story_5053_50530201_152_dialog_content = "Kami akan meninjau kembali ini setelah kami keluar dari sini, Caleb.",
  ui_story_5053_50530201_153_dialog_content = "Jadi, kita bisa pergi dari sini dan menghidupkan kembali Ibu jika kita mengalahkan Kegelapan Angel?",
  ui_story_5053_50530201_154_dialog_content = "Dari apa yang kami kumpulkan sejauh ini, itulah masalahnya.",
  ui_story_5053_50530201_155_dialog_content = "Lantas, bagaimana kondisi tubuh Joshua sekarang? Bisakah itu menahan kejutan dari kebangkitan yang tiba-tiba?",
  ui_story_5053_50530201_156_dialog_content = "Itu terpelihara dengan sempurna, tentu saja. Sejak dia mengalami koma, saya telah menghabiskan seluruh waktu dan usaha saya untuknya.",
  ui_story_5053_50530201_157_dialog_content = "Adapun hasilnya, <color=#FFB400>lihat saja aku</color>.",
  ui_story_5053_50530201_158_dialog_content = "Lihat dirimu? Untuk apa?",
  ui_story_5053_50530201_159_dialog_content = "Caleb, bahkan jika itu untuk Joshua, Saya melarang Anda melakukan eksperimen yang tidak etis.",
  ui_story_5053_50530201_160_dialog_content = "Apa itu untukmu?",
  ui_story_5053_50530201_161_dialog_content = "Tunggu, aku tersesat. Apa yang terjadi di sini?",
  ui_story_5053_50530201_162_dialog_content = "Menurutmu berapa umurku, Jakine?",
  ui_story_5053_50530201_163_dialog_content = "Duapuluhan?",
  ui_story_5053_50530201_164_dialog_content = "Lihat apa yang saya maksud?",
  ui_story_5053_50530201_165_dialog_content = "Uh, jika saya ingat dengan benar, Paman harusnya mendekati 40...",
  ui_story_5053_50530201_166_dialog_content = "Hah—?!",
  ui_story_5053_50530201_167_dialog_content = "Apa-?!",
  ui_story_5053_50530201_168_dialog_content = "Di sini saya pikir Paman lahir seperti itu atau hanya pandai merias wajah ... Saya tidak menyangka itu hasil eksperimen ...",
  ui_story_5053_50530201_169_dialog_content = "Saya tidak akan pernah menggunakan ramuan yang belum teruji pada saudara perempuan saya.",
  ui_story_5053_50530201_170_dialog_content = "Saya juga tidak akan menyakiti orang yang tidak bersalah seperti para bangsawan itu, jadi satu-satunya pilihan adalah mengujinya pada diri saya sendiri.",
  ui_story_5053_50530201_171_dialog_content = "Ya ampun, Kaleb...",
  ui_story_5053_50530201_172_dialog_content = "Apakah Anda baik-baik saja, Ibu? Anda tidak terlihat sehat...",
  ui_story_5053_50530201_173_dialog_content = "aku baik-baik saja... aku sudah terbiasa, mungkin...",
  ui_story_5053_50530201_174_dialog_content = "<size=30>Tetapi PlayerName, Caleb bertindak sangat tidak dewasa juga, jadi apakah itu berarti penelitiannya dapat membuat orang awet muda, secara mental?</size>",
  ui_story_5053_50530201_175_dialog_content = "Saya mendengarnya, Jakine!",
  ui_story_5053_50530201_176_dialog_content = "Meskipun tubuhnya baik-baik saja, Lumina dalam dirinya cenderung lepas kendali.",
  ui_story_5053_50530201_177_dialog_content = "Saya masih perlu melakukan penelitian lebih lanjut karena saya belum menemukan solusinya.",
  ui_story_5053_50530201_178_dialog_content = "Lumina? Jadi itulah mengapa Anda bertanya kepada saya di mana Lumina Lady Joshua berada!",
  ui_story_5053_50530201_179_dialog_content = "Jelas sekali. Niat saya adalah menemukan sisa Lumina untuk perawatan eksperimental.",
  ui_story_5053_50530201_180_dialog_content = "Tapi siapa yang bisa menduga dia ada di Crystal selama ini? Dan itulah mengapa Lumina di tubuhnya terus kehilangan kendali.",
  ui_story_5053_50530201_181_dialog_content = "Teori saya benar-benar salah...",
  ui_story_5053_50530201_182_dialog_content = "Anda seharusnya memberi tahu saya tentang hal itu lebih awal, Caleb.",
  ui_story_5053_50530201_183_dialog_content = "Memberitahu Anda? Agar kau bisa terus menyiksanya?",
  ui_story_5053_50530201_184_dialog_content = "Mengapa Anda berdebat lagi? Jangan lakukan ini di depan orang lain.",
  ui_story_5053_50530201_185_dialog_content = "Maaf, Suster.",
  ui_story_5053_50530201_186_dialog_content = "Mengingat tubuhnya masih dalam kondisi baik, kita harus membawanya keluar secepatnya.",
  ui_story_5053_50530201_187_dialog_content = "Mari kembali ke topik dan mencari tahu apa yang harus dilakukan tentang Kegelapan Angel.",
  ui_story_5053_50530201_188_dialog_content = "Ya, ayo lakukan itu.",
  ui_story_5053_50530201_189_dialog_content = "Aku tidak bisa mengalahkannya sendirian.",
  ui_story_5053_50530201_190_dialog_content = "Karena kita berbagi <color=#FFB400>tubuh yang sama dan telah menjalani satu kehidupan</color>, hanya pihak ketiga yang dapat menghancurkannya.",
  ui_story_5053_50530201_191_dialog_content = "Tapi Anda harus berhati-hati karena itu memburu Anda juga.",
  ui_story_5053_50530201_192_dialog_content = "Memburu kami?",
  ui_story_5053_50530201_193_dialog_content = "Ya. Sudah bosan dengan konflik kami dan ingin mandiri, mengambil tubuhku untuk dirinya sendiri.",
  ui_story_5053_50530201_194_dialog_content = "Akan sangat sulit di dunia nyata.",
  ui_story_5053_50530201_195_dialog_content = "Tapi sebagai bagian dari diriku yang mengaktifkan Crystal of Eternal Memory, itu bisa <color=#FFB400>bunuh semua orang hidup lainnya agar Lumina menjadi utuh</color> Di Sini.",
  ui_story_5053_50530201_196_dialog_content = "Benarkah itu, Jakine?",
  ui_story_5053_50530201_197_dialog_content = "Ya. Ini mungkin terdengar seperti omong kosong, tapi itu mungkin terjadi di dalam Crystal.",
  ui_story_5053_50530201_198_dialog_content = "Crystal mungkin tampak seperti perangkat pemutar memori, tetapi prinsip di baliknya jauh lebih dalam dari itu.",
  ui_story_5053_50530201_199_dialog_content = "Itu sebabnya Ibu hanya membuat satu di bawah perintah Ratu, lalu menyembunyikan semua tentangnya setelah...",
  ui_story_5053_50530201_200_dialog_content = "Jadi, pada dasarnya, ada dua kemungkinan hasil.",
  ui_story_5053_50530201_201_dialog_content = "Salah satunya adalah kita menghancurkan Kegelapan Angel dan membawa Lady Joshua dengan kami keluar dari sini.",
  ui_story_5053_50530201_202_dialog_content = "Yang lainnya adalah Kegelapan Angel membunuh kita dan dilepaskan ke dunia nyata?",
  ui_story_5053_50530201_203_dialog_content = "Itu benar. Sungguh anak yang brilian. kamu PlayerName, Kanan?",
  ui_story_5053_50530201_204_dialog_content = "Ya. Omong-omong, Anda tahu nama saya dan Jakine, dan namanya Mia tampaknya tidak mengejutkan Anda.",
  ui_story_5053_50530201_205_dialog_content = "Apakah Anda memiliki kenangan dari sebelum reset juga?",
  ui_story_5053_50530201_206_dialog_content = "Ya, sejak <color=#FFB400>Aku bersamamu</color> ketika itu terjadi.",
  ui_story_5053_50530201_207_dialog_content = "Dan aku tidak ingin jauh dari keluargaku lagi...",
  ui_story_5053_50530201_208_dialog_content = "Aku bersumpah akan menghancurkan Kegelapan Angel dan mengeluarkanmu dari sini, jadi jangan khawatir.",
  ui_story_5053_50530201_209_dialog_content = "Saya juga...! Aku akan membebaskanmu dari tempat ini!",
  ui_story_5053_50530201_210_dialog_content = "Sungguh, aku percaya pada kalian semua.",
  ui_story_5053_50530201_211_dialog_content = "Kegelapan Angel tidak memiliki keterampilan penalaran, namun itu licik.",
  ui_story_5053_50530201_212_dialog_content = "Kami membutuhkan umpan untuk menariknya keluar.",
  ui_story_5053_50530201_213_dialog_content = "Apakah kamu keberatan, Daniel?",
  ui_story_5053_50530201_214_dialog_content = "Tidak masalah. Yang terbaik adalah saya mengambil peran yang begitu vital dan berbahaya.",
  ui_story_5053_50530201_215_dialog_content = "Tapi bagaimana saya memikatnya kepada saya?",
  ui_story_5053_50530201_216_dialog_content = "Anda tidak perlu melakukan apapun, karena monster itu... <color=#FFB400>justru membencimu</color>.",
  ui_story_5053_50530201_217_dialog_content = "Jika Anda tidak cukup kuat untuk mengusirnya, itu akan mencabik-cabik Anda.",
  ui_story_5053_50530201_218_dialog_content = "Itu juga berlaku untuk Anda yang masih muda di dunia ini. Kemungkinan akan menyerangnya di perayaan itu.",
  ui_story_5053_50530201_219_dialog_content = "Meskipun membunuh ilusi tidak akan menghasilkan apa-apa, ia tetap tidak bisa menolak.",
  ui_story_5053_50530201_220_dialog_content = "Jadi begitu. Kalau begitu, aku hanya perlu menemukan diriku yang masih muda dan menunggunya muncul.",
  ui_story_5053_50530201_221_dialog_content = "Tunggu, bukankah itu berbahaya, Ayah? Bagaimana jika Anda terluka?",
  ui_story_5053_50530201_222_dialog_content = "Kau selalu mengkhawatirkan keluarga kita, Vonnie.",
  ui_story_5053_50530201_223_dialog_content = "Tapi, situasi kita saat ini sangat mendesak dan kita harus memfokuskan prioritas kita.",
  ui_story_5053_50530201_224_dialog_content = "Percayai ayahmu, ya?",
  ui_story_5053_50530201_225_dialog_content = "Baiklah...",
  ui_story_5053_50530201_226_dialog_content = "Setelah pawai harus ada upacara pembukaan di alun-alun.",
  ui_story_5053_50530201_227_dialog_content = "Haruskah kita mengintai di sana?",
  ui_story_5053_50530201_228_dialog_content = "Ide bagus, tapi kau harus tetap bersamaku, Jakine.",
  ui_story_5053_50530201_229_dialog_content = "Mengapa? Jangan menghinaku, aku petarung yang jauh lebih baik daripada PlayerName!",
  ui_story_5053_50530201_230_dialog_content = "Ehem...",
  ui_story_5053_50530201_231_dialog_content = "Ya, saya tahu, tapi Anda mengoperasikan Crystal.",
  ui_story_5053_50530201_232_dialog_content = "Jika yang lain terluka, kita selalu bisa memutar balik waktu untuk mengembalikan segalanya.",
  ui_story_5053_50530201_233_dialog_content = "Tetapi jika sesuatu terjadi pada Anda, itu tidak dapat diubah.",
  ui_story_5053_50530201_234_dialog_content = "K-Kau benar...",
  ui_story_5053_50530201_235_dialog_content = "Jadi kami memiliki Penguasa Kota sebagai umpan. Mia, PlayerName dan aku akan menuju alun-alun bersama untuk menghentikan Kegelapan Angel.",
  ui_story_5053_50530201_236_dialog_content = "Jakine dan saudara perempuan saya akan tinggal di sini dan menunggu kabar baik.",
  ui_story_5053_50530201_237_dialog_content = "Pastikan Anda merawatnya dengan baik, Jakine.",
  ui_story_5053_50530201_238_dialog_content = "Saya mendapatkannya! Kenapa semua orang meragukanku...",
  ui_story_5053_50530201_239_dialog_content = "Aku terkejut, Kaleb. Saya pikir Anda akan bersikeras tinggal dengan adikmu.",
  ui_story_5053_50530201_240_dialog_content = "Membunuh Kegelapan Angel dan membawa adikku keluar dari sini adalah hal terpenting saat ini. Apakah Anda pikir saya tidak mengerti?",
  ui_story_5053_50530201_241_dialog_content = "U-Um, kita harus pergi.",
  ui_story_5053_50530201_242_dialog_content = "Ya, ayo pergi!",
  ui_story_5053_50530201_243_dialog_content = "Berhenti mendorongku, kalian berdua.",
  ui_story_5053_50530201_244_dialog_content = "Semoga selamat sampai tujuan!",
  ui_story_5053_50530201_245_dialog_content = "Aku tidak akan kehilanganmu lagi, Joshua, Saya berjanji.",
  ui_story_5053_50530201_246_dialog_content = "Ya saya percaya kamu.",
  ui_story_5053_50530201_247_dialog_content = "Anda tidak akan melakukannya.",
  ui_story_5053_50530301_1_dialog_content = "Pawai telah usai dan perayaan akan segera dimulai.",
  ui_story_5053_50530301_2_dialog_content = "Apakah masih ada tempat bagus yang tersedia untuk menontonnya?",
  ui_story_5053_50530301_3_dialog_content = "Cepat, mari kita periksa!",
  ui_story_5053_50530301_4_dialog_content = "Apa yang bisa dilihat? Itu semua hanya lelucon.",
  ui_story_5053_50530301_5_dialog_content = "Ini ramai di mana-mana. Bagaimana kita akan melihat Dark Angel ketika kita hampir tidak bisa melihat?",
  ui_story_5053_50530301_6_dialog_content = "Dekati stand dan tunggu saja.",
  ui_story_5053_50530301_7_dialog_content = "Karena kalian berdua bisa memancing Dark Angel bagi kami, bukankah kami memiliki kesempatan yang lebih baik jika kalian berdua pergi ke sana?",
  ui_story_5053_50530301_8_dialog_content = "Yah, saya pikir lebih baik saya pergi, karena orang-orang di sini masih mengenali saya.",
  ui_story_5053_50530301_9_dialog_content = "Jika Ayah pergi, itu mungkin menimbulkan terlalu banyak kekacauan ...",
  ui_story_5053_50530301_10_dialog_content = "BENAR. Tapi jika Angel menyerang dudukan, bisakah kamu melawannya sendiri, Mia?",
  ui_story_5053_50530301_11_dialog_content = "Aku... aku tidak sendirian.",
  ui_story_5053_50530301_12_dialog_content = "Ayah di dunia ini akan membantuku juga.",
  ui_story_5053_50530301_13_dialog_content = "Belum lagi, saya akan memiliki pandangan yang lebih baik di sana. Saya dapat menyampaikan posisi Malaikat kepada Anda ketika saya melihatnya ...",
  ui_story_5053_50530301_14_dialog_content = "Hmm... Aku akan pindah ke tempat di mana semua orang bisa melihatku dan mengirim sinyal!",
  ui_story_5053_50530301_15_dialog_content = "Oh, maaf, Ayah... Mungkin ideku terlalu naif?",
  ui_story_5053_50530301_16_dialog_content = "Anda menutupi semuanya. Kami akan melanjutkan seperti yang Anda sarankan.",
  ui_story_5053_50530301_17_dialog_content = "Apa? Betulkah?",
  ui_story_5053_50530301_18_dialog_content = "Terima kasih ayah. Aku akan pergi sekarang, tunggu saja sinyalku!",
  ui_story_5053_50530301_19_dialog_content = "Ini baru sehari dan Mia sudah sangat berani dan mandiri. Senang melihatnya.",
  ui_story_5053_50530301_20_dialog_content = "Sekarang bukan waktunya untuk pujian, PlayerName. Buka matamu untuk iblis yang menghancurkan adikku!",
  ui_story_5053_50530301_21_dialog_content = "Ya, saya akan segera datang!",
  ui_story_5053_50530301_22_dialog_content = "Perayaan akan segera dimulai, Carleen. Kembali ke tempat duduk Anda.",
  ui_story_5053_50530301_23_dialog_content = "Ya, Ayah.",
  ui_story_5053_50530301_24_dialog_content = "Ayah, Carleen.",
  ui_story_5053_50530301_25_dialog_content = "Veronica?! Ayah, Veronica ada di sini!",
  ui_story_5053_50530301_26_dialog_content = "Veronica? Apa yang kamu lakukan di sini?",
  ui_story_5053_50530301_27_dialog_content = "M-Ibu menyuruhku pulang untuk perayaan Hari Keluarga.",
  ui_story_5053_50530301_28_dialog_content = "Anda melihat ibumu?",
  ui_story_5053_50530301_29_dialog_content = "Ya... Dia sedang tidak enak badan tapi mengatakan kita tidak perlu khawatir.",
  ui_story_5053_50530301_30_dialog_content = "Bukan Putri Veronica? Sudah lama. Apa kabarmu?",
  ui_story_5053_50530301_31_dialog_content = "Bukankah Putri Veronica bergabung dengan para ksatria dan mengikuti mereka ke Umbraton?",
  ui_story_5053_50530301_32_dialog_content = "Saya ingin kembali untuk perayaan jadi saya meminta waktu istirahat.",
  ui_story_5053_50530301_33_dialog_content = "Jadi begitu. Dan Anda harus, karena itu Schwartz Hari Keluarga, bagaimanapun juga.",
  ui_story_5053_50530301_34_dialog_content = "Sayang sekali keluarga saya masih ditempatkan di Umbraton dan tidak memiliki keistimewaan.",
  ui_story_5053_50530301_35_dialog_content = "Veronica adalah anggota DPR Schwartz jadi itu haknya untuk kembali pada Hari Keluarga kita!",
  ui_story_5053_50530301_36_dialog_content = "Diam, Carleen, dan hormati Duke Hermes.",
  ui_story_5053_50530301_37_dialog_content = "Jangan salahkan Carleen, Ayah. Aku kembali tanpa pemberitahuan.",
  ui_story_5053_50530301_38_dialog_content = "Dan karena Duke Hermes ada di sini, bagaimana kabar Ny. Hermes akhir-akhir ini?",
  ui_story_5053_50530301_39_dialog_content = "Dia baik-baik saja, seperti biasa.",
  ui_story_5053_50530301_40_dialog_content = "Saya sangat prihatin sejak cucu Anda selalu pergi dan mengatakan Ny. Hermes dalam kondisi buruk.",
  ui_story_5053_50530301_41_dialog_content = "Senang mengetahui dia baik-baik saja.",
  ui_story_5053_50530301_42_dialog_content = "... Ya, terima kasih atas perhatiannya, Yang Mulia.",
  ui_story_5053_50530301_43_dialog_content = "Anda harus meluangkan waktu untuk menghabiskan waktu bersama keluarga Anda sesekali, Duke Hermes.",
  ui_story_5053_50530301_44_dialog_content = "Putri Veronica telah dewasa. Para Ksatria pasti telah melatihnya dengan baik.",
  ui_story_5053_50530301_45_dialog_content = "Mungkin, tapi saya harap itu tidak sampai ke kepalanya.",
  ui_story_5053_50530301_46_dialog_content = "Oh Tuhan Schwartz, Anda tidak harus begitu tangguh hanya untuk Putri Veronica.",
  ui_story_5053_50530301_47_dialog_content = "Terima kasih, Adipati Troy. Ayah benar, aku harus tetap rendah hati dan terus belajar.",
  ui_story_5053_50530301_48_dialog_content = "Begitu, Putri Veronica... Anda memang tumbuh besar bekerja dengan para ksatria.",
  ui_story_5053_50530301_49_dialog_content = "Perayaan dimulai. Silakan duduk, semuanya.",
  ui_story_5053_50530301_50_dialog_content = "Kamu sangat keren, Veronica! Para bangsawan dari Dewan Tetua itu sama sekali tidak membuatmu takut!",
  ui_story_5053_50530301_51_dialog_content = "Kau pikir begitu? Aku gugup, jujur saja...",
  ui_story_5053_50530301_52_dialog_content = "Kamu juga berani, Carleen, ikut pawai bersama Ayah sendirian.",
  ui_story_5053_50530301_53_dialog_content = "Tidak, aku juga tidak ingin berpisah dari Ibu...",
  ui_story_5053_50530301_54_dialog_content = "Ketika saya naik kereta, Ayah berkata Ibu sedang tidak enak badan dan ingin saya pergi ke perayaan sendirian ...",
  ui_story_5053_50530301_55_dialog_content = "(Begitu, Ibu menggunakan penyakit sebagai alasan untuk mendapatkan Carleen dan Ayah pergi agar dia bisa melihat kita.)",
  ui_story_5053_50530301_56_dialog_content = "(Itu pasti menyakiti perasaan Carleen kecil, tapi setidaknya semua ini tidak nyata.)",
  ui_story_5053_50530301_57_dialog_content = "(Prioritas, prioritas... Tidak, saya tidak bisa melakukannya.)",
  ui_story_5053_50530301_58_dialog_content = "Bagaimana kalau kita kembali ke Ibu, Carleen?",
  ui_story_5053_50530301_59_dialog_content = "Bisakah kita? Apakah itu tidak akan mengganggunya?",
  ui_story_5053_50530301_60_dialog_content = "Tentu saja tidak. Ibu mencintaimu dan akan menjadi lebih baik denganmu di sekitar.",
  ui_story_5053_50530301_61_dialog_content = "Aku mencintai Ibu dan kamu juga! Dan Ayah!",
  ui_story_5053_50530301_62_dialog_content = "Aku akan membawakannya buah dan memberitahunya tentang pawai saat kita kembali!",
  ui_story_5053_50530301_63_dialog_content = "Hehe, gadis yang baik.",
  ui_story_5053_50530301_64_dialog_content = "(Ini sangat indah untuk dilihat Carleen ceria lagi)",
  ui_story_5053_50530301_65_dialog_content = "Apa yang kamu lihat?",
  ui_story_5053_50530301_66_dialog_content = "Mia di atas sana, tapi aku tidak bisa melihatnya sekarang... Padahal Muda Schwartz siap berbicara.",
  ui_story_5053_50530301_67_dialog_content = "Tidak ada pandangan tentang Kegelapan Angel belum.",
  ui_story_5053_50530301_68_dialog_content = "Kami hampir tidak bisa melihat dari sini. Kita harus mencoba tempat lain.",
  ui_story_5053_50530301_69_dialog_content = "<color=#e8d9bb>Retakan! Retakan!</color>",
  ui_story_5053_50530301_70_dialog_content = "Itu terdengar seperti...",
  ui_story_5053_50530301_71_dialog_content = "Kurasa kita tidak perlu mencoba tempat lain, Caleb.",
  ui_story_5053_50530301_72_dialog_content = "Bebek, kalian berdua!",
  ui_story_5053_50530301_73_dialog_content = "Disini!",
  ui_story_5053_50530302_1_dialog_content = "Dengan ini saya menyatakan dimulainya Schwartz Perayaan Hari Keluarga!",
  ui_story_5053_50530302_2_dialog_content = "Sekarang, biarkan Upacara Pertarungan dimulai!",
  ui_story_5053_50530302_3_dialog_content = "(Kenapa mereka belum menunjukkan ...)",
  ui_story_5053_50530302_4_dialog_content = "(Mereka seharusnya ada di sana, tapi aku tidak bisa melihat mereka sama sekali...)",
  ui_story_5053_50530302_5_dialog_content = "(Jangan bilang Gelap Angel sudah dilacak PlayerName dan yang lainnya turun?)",
  ui_story_5053_50530302_6_dialog_content = "(Haruskah saya mencari alasan dan pergi?)",
  ui_story_5053_50530302_7_dialog_content = "Apakah Anda mencari sesuatu, Vonnie?",
  ui_story_5053_50530302_8_dialog_content = "T-Tidak, Carleen... Lihat, pertikaian sudah dimulai di sana. Kedengarannya seperti itu akan menyenangkan.",
  ui_story_5053_50530302_9_dialog_content = "Kapan mereka akan mengizinkan saya berpartisipasi... Saya sama baiknya dengan mereka.",
  ui_story_5053_50530302_10_dialog_content = "Aneh, kedua duelist itu berhenti begitu saja...",
  ui_story_5053_50530302_11_dialog_content = "Dan mereka berjalan ke arah kita...",
  ui_story_5053_50530302_12_dialog_content = "Apakah kita mendapatkan pertunjukan bonus atau sesuatu?",
  ui_story_5053_50530302_13_dialog_content = "Apa?",
  ui_story_5053_50530302_14_dialog_content = "(Ayah bingung, seperti dia tidak tahu apa yang terjadi.)",
  ui_story_5053_50530302_15_dialog_content = "(Saya tidak berada di sini saat itu, jadi saya tidak tahu apa yang akan terjadi sekarang, tetapi rasanya tidak benar.)",
  ui_story_5053_50530302_16_dialog_content = "...",
  ui_story_5053_50530302_17_dialog_content = "(Mungkinkah ini...?!)",
  ui_story_5053_50530302_18_dialog_content = "Ayah, pembunuhan itu dimajukan!",
  ui_story_5053_50530302_19_dialog_content = "Bagaimana Anda tahu tentang itu? Dan itu... dipindahkan?",
  ui_story_5053_50530302_20_dialog_content = "Ceritanya panjang...",
  ui_story_5053_50530302_21_dialog_content = "Apa yang kamu lakukan di sini? Ini bukan tempat untukmu!",
  ui_story_5053_50530302_22_dialog_content = "...",
  ui_story_5053_50530302_23_dialog_content = "Betapa kurang ajarnya Anda untuk tidak menanggapi saya!",
  ui_story_5053_50530302_24_dialog_content = "Mereka tidak datang dengan damai... Mundur, Duke Hermes!",
  ui_story_5053_50530302_25_dialog_content = "Menyimpan Carleen aman, Veronica!",
  ui_story_5053_50530302_26_dialog_content = "Hati-hati, Ayah!",
  ui_story_5053_50530302_27_dialog_content = "Hah!",
  ui_story_5053_50530302_28_dialog_content = "Cuma itu kemampuanmu?",
  ui_story_5053_50530302_29_dialog_content = "Tebasan penguasa!",
  ui_story_5053_50530302_30_dialog_content = "Ugh...",
  ui_story_5053_50530302_31_dialog_content = "Apakah Anda ingin mencoba keberuntungan Anda juga?",
  ui_story_5053_50530302_32_dialog_content = "Hah!",
  ui_story_5053_50530302_33_dialog_content = "Rasakan ini!",
  ui_story_5053_50530302_34_dialog_content = "Ugh...",
  ui_story_5053_50530302_35_dialog_content = "Kau selamat dari pedangku? Katakan padaku, siapa yang mengirimmu?",
  ui_story_5053_50530302_36_dialog_content = "Tunggu—",
  ui_story_5053_50530302_37_dialog_content = "Sudah terlambat untuk memohon belas kasihan sekarang!",
  ui_story_5053_50530302_38_dialog_content = "Veronica, mengapa Ayah berbisik kepada orang jahat itu?",
  ui_story_5053_50530302_39_dialog_content = "Tidak, menurutku bukan Ayah yang mengancamnya... dia menangkap Ayah dengan senjatanya.",
  ui_story_5053_50530302_40_dialog_content = "<color=#e8d9bb>Krak!</color>",
  ui_story_5053_50530302_41_dialog_content = "Hah?",
  ui_story_5053_50530302_42_dialog_content = "Ha ha ha! Segera...",
  ui_story_5053_50530302_43_dialog_content = "Mengapa wajahnya menjadi begitu berkerut?",
  ui_story_5053_50530302_44_dialog_content = "Dan mengapa dia tertawa ketika dia terluka? Apa yang sedang terjadi...",
  ui_story_5053_50530302_45_dialog_content = "Bagaimana ini... Kekuatan macam apa ini? <color=#FFB400>Aku tidak bisa melepaskan senjataku</color>!",
  ui_story_5053_50530302_46_dialog_content = "Dalam hal ini, Penguasa...",
  ui_story_5053_50530302_47_dialog_content = "Ini dia...",
  ui_story_5053_50530302_48_dialog_content = "Lihatlah, Ayah! Langit!",
  ui_story_5053_50530302_49_dialog_content = "<size=45><color=#e8d9bb>Mengaum-!</color></size>",
  ui_story_5053_50530302_50_dialog_content = "Apa?",
  ui_story_5053_50530302_51_dialog_content = "I-Anginnya terlalu kencang! Ini akan membuat saya pergi!",
  ui_story_5053_50530302_52_dialog_content = "Aku disini, Carleen!",
  ui_story_5053_50530302_53_dialog_content = "Naga... A <color=#FFB400>naga</color>? Para Kartima... Apakah mereka akan menghancurkan standnya juga?!",
  ui_story_5053_50530302_54_dialog_content = "<size=45><color=#e8d9bb>Mengaum-!</color></size>",
  ui_story_5053_50530302_55_dialog_content = "Carleen, Veronica!",
  ui_story_5053_50530302_56_dialog_content = "Lari cepat!",
  ui_story_5053_50530302_57_dialog_content = "<size=45><color=#e8d9bb>Ledakan-!!!</color></size>",
  ui_story_5053_50530401_1_dialog_content = "Agh!",
  ui_story_5053_50530401_2_dialog_content = "Kau lebih buruk dari yang terlihat!",
  ui_story_5053_50530401_3_dialog_content = "Beraninya seorang Seed menipuku dengan meniru suara kakakku...",
  ui_story_5053_50530401_4_dialog_content = "Aku akan membuatmu membayar penderitaannya dengan darah!",
  ui_story_5053_50530401_5_dialog_content = "Hah!",
  ui_story_5053_50530401_6_dialog_content = "...",
  ui_story_5053_50530401_7_dialog_content = "Jangan gegabah, Caleb!",
  ui_story_5053_50530401_8_dialog_content = "Waktunya tewas!",
  ui_story_5053_50530401_9_dialog_content = "Agh!",
  ui_story_5053_50530401_10_dialog_content = "Apa?!",
  ui_story_5053_50530401_11_dialog_content = "Kaleb!!!",
  ui_story_5053_50530401_12_dialog_content = "Ca...leb...?",
  ui_story_5053_50530401_13_dialog_content = "Jauhkan namaku dari bibirmu...",
  ui_story_5053_50530401_14_dialog_content = "Sekarang!",
  ui_story_5053_50530401_15_dialog_content = "Aku akan mengguncang setiap bintang—!!!",
  ui_story_5053_50530401_16_dialog_content = "Ugh!!!",
  ui_story_5053_50530401_17_dialog_content = "Sch... wartz...",
  ui_story_5053_50530401_18_dialog_content = "Sch...",
  ui_story_5053_50530401_19_dialog_content = "Semuanya tampak kembali normal?",
  ui_story_5053_50530401_20_dialog_content = "Sudah hilang... Apakah itu berarti sudah mati?",
  ui_story_5053_50530401_21_dialog_content = "Tidak, ada yang salah. Lihat ke sana.",
  ui_story_5053_50530401_22_dialog_content = "Argh—!",
  ui_story_5053_50530401_23_dialog_content = "Lari!!!",
  ui_story_5053_50530401_24_dialog_content = "Kerumunan melarikan diri dari alun-alun... Apakah pemberontakan sudah dimulai?",
  ui_story_5053_50530401_25_dialog_content = "Tidak mungkin. Tanpa campur tangan kami, itu akan dimulai setelah pembunuhan...",
  ui_story_5053_50530401_26_dialog_content = "Tidak...",
  ui_story_5053_50530401_27_dialog_content = "Lihatlah ke langit!",
  ui_story_5053_50530401_28_dialog_content = "Mengaum-!",
  ui_story_5053_50530401_29_dialog_content = "Naga Kartima?!",
  ui_story_5053_50530401_30_dialog_content = "Apa yang dilakukannya di kota?",
  ui_story_5053_50530401_31_dialog_content = "Astaga, apa yang dilakukan di Lumopolis...?",
  ui_story_5053_50530401_32_dialog_content = "Bukankah seharusnya kalian melindungi kami di saat-saat seperti ini? Apa yang kamu tunggu?",
  ui_story_5053_50530401_33_dialog_content = "...",
  ui_story_5053_50530401_34_dialog_content = "H-Hei, apa yang kamu lakukan?",
  ui_story_5053_50530401_35_dialog_content = "Bunuh... Bunuh... Bunuh...",
  ui_story_5053_50530401_36_dialog_content = "Aaah—!",
  ui_story_5053_50530401_37_dialog_content = "Sovereign's Blade!",
  ui_story_5053_50530401_38_dialog_content = "Ksatria macam apa kamu menyakiti orang yang tidak berdaya? Inikah level Kartima yang telah bungkuk?",
  ui_story_5053_50530401_39_dialog_content = "Oh...",
  ui_story_5053_50530401_40_dialog_content = "I-Yang ini masih hidup!",
  ui_story_5053_50530401_41_dialog_content = "Bunuh…",
  ui_story_5053_50530401_42_dialog_content = "Membunuh? Apa yang kamu katakan?",
  ui_story_5053_50530401_43_dialog_content = "Sch... wartz...",
  ui_story_5053_50530401_44_dialog_content = "Bunuh... Bunuh... Bunuh para penyusup!",
  ui_story_5053_50530401_45_dialog_content = "Keluar dari jalan, PlayerName!",
  ui_story_5053_50530401_46_dialog_content = "Kenapa, ada apa dengannya...?",
  ui_story_5053_50530401_47_dialog_content = "<color=#e8d9bb><size=45>Duar!</size></color>",
  ui_story_5053_50530401_48_dialog_content = "Gelombang kejut yang begitu kuat. Apa sekarang?",
  ui_story_5053_50530401_49_dialog_content = "Ledakan datang dari tribun!",
  ui_story_5053_50530401_50_dialog_content = "Tuan Kota telah diserang!",
  ui_story_5053_50530401_51_dialog_content = "Jalankan untuk hidup Anda!",
  ui_story_5053_50530401_52_dialog_content = "Terserang? Mia...!",
  ui_story_5053_50530401_53_dialog_content = "Jika Mia masih berdiri... Tidak, tidak mungkin...",
  ui_story_5053_50530401_54_dialog_content = "Adikku masih di Schwartz rumah besar. Jika para pemberontak menemukannya...",
  ui_story_5053_50530401_55_dialog_content = "PlayerName, pergi dengan Caleb!",
  ui_story_5053_50530401_56_dialog_content = "Jika saya tidak kembali dengan Mia, memberi tahu Jakine untuk mundur segera!",
  ui_story_5053_50530401_57_dialog_content = "Yang mulia Schwartz!!!",
  ui_story_5053_50530401_58_dialog_content = "(Apa yang terjadi? Apakah Crystal of Eternal Memory rusak?)",
  ui_story_5053_50530401_59_dialog_content = "(Atau mungkin Kegelapan Angel masih hidup dan ini semua yang dia lakukan...?)",
  ui_story_5053_50530401_60_dialog_content = "Jangan hanya berdiri di sana! Kita harus keluar dari sini!",
  ui_story_5053_50530401_61_dialog_content = "Bunuh... Bunuh... Bunuh...",
  ui_story_5053_50530402_1_dialog_content = "Hah!",
  ui_story_5053_50530402_2_dialog_content = "Ugh...",
  ui_story_5053_50530402_3_dialog_content = "Sialan para pemberontak... Terima kasih atas bantuannya, pak tua.",
  ui_story_5053_50530402_4_dialog_content = "Dimana yang mulia?",
  ui_story_5053_50530402_5_dialog_content = "Yang mulia? Anda harus berpikir tentang menjaga diri Anda tetap hidup.",
  ui_story_5053_50530402_6_dialog_content = "Bagaimana apanya?",
  ui_story_5053_50530402_7_dialog_content = "Putri Carleen, Putri Veronica dan Penguasa Kota diserang oleh naga... <color=#FFB400>Mereka mati</color>!",
  ui_story_5053_50530402_8_dialog_content = "Di mana? Di mana Putri Veronica?!",
  ui_story_5053_50530402_9_dialog_content = "Masih di mimbar. Jangan bilang kau ingin mengambil sisa-sisa mereka pada saat seperti ini?",
  ui_story_5053_50530402_10_dialog_content = "Terima kasih.",
  ui_story_5053_50530402_11_dialog_content = "Bodoh... Berpegang teguh pada apa yang sudah hilang hanya akan mengorbankan nyawamu.",
  ui_story_5053_50530402_12_dialog_content = "Yosua!",
  ui_story_5053_50530402_13_dialog_content = "Wanita Joshua! Jakine! Kamu ada di mana?",
  ui_story_5053_50530402_14_dialog_content = "Mengapa mereka tidak menanggapi ... Joshua!",
  ui_story_5053_50530402_15_dialog_content = "Aku di sini, Kaleb.",
  ui_story_5053_50530402_16_dialog_content = "Syukurlah Anda baik-baik saja! Kukira aku akan kehilanganmu lagi...",
  ui_story_5053_50530402_17_dialog_content = "Pemberontakan dinaikkan. Kami harus membawamu ke tempat yang aman.",
  ui_story_5053_50530402_18_dialog_content = "Dimana Jakine? Ke mana dia pergi pada saat seperti ini?",
  ui_story_5053_50530402_19_dialog_content = "Tetap tenang, Caleb, satu per satu.",
  ui_story_5053_50530402_20_dialog_content = "Anda berkeringat di mana-mana, bahkan kerah Anda berkerut. Di sini, biarkan saya memperbaikinya untuk Anda.",
  ui_story_5053_50530402_21_dialog_content = "Hah? Uh, aku bisa mengatasinya sendiri...",
  ui_story_5053_50530402_22_dialog_content = "T-Terima kasih, kak.",
  ui_story_5053_50530402_23_dialog_content = "Wanita Joshua baik-baik saja, tapi di mana melakukan Jakine lari ke?",
  ui_story_5053_50530402_24_dialog_content = "Kamu ada di mana, Jakine?!!",
  ui_story_5053_50530402_25_dialog_content = "Ugh...",
  ui_story_5053_50530402_26_dialog_content = "K... s...?",
  ui_story_5053_50530402_27_dialog_content = "Ada apa, Kaleb?",
  ui_story_5053_50530402_28_dialog_content = "I-Ini...",
  ui_story_5053_50530402_29_dialog_content = "Tapi kenapa?",
  ui_story_5053_50530402_30_dialog_content = "Dadamu, Caleb?!",
  ui_story_5053_50530402_31_dialog_content = "Apakah Anda terluka di jalan? T-Tidak, tidak mungkin...",
  ui_story_5053_50530402_32_dialog_content = "Mengapa Anda masih suka duduk di tanah di usia Anda?",
  ui_story_5053_50530402_33_dialog_content = "Masih belum dewasa seperti biasanya, Caleb.",
  ui_story_5053_50530402_34_dialog_content = "Betapa mengecewakan.",
  ui_story_5053_50530402_35_dialog_content = "Kenapa…",
  ui_story_5053_50530402_36_dialog_content = "Kakak...",
  ui_story_5053_50530402_37_dialog_content = "Mia...",
  ui_story_5053_50530402_38_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_39_dialog_content = "Aku tahu kita bisa memundurkan waktu...",
  ui_story_5053_50530402_40_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_41_dialog_content = "Tapi aku tidak ingin kau melalui ini...",
  ui_story_5053_50530402_42_dialog_content = "Bahkan jika Anda membenci saya karena mengirim Anda pergi dari saya, saya akan merasa damai mengetahui Anda aman dan sehat ...",
  ui_story_5053_50530402_43_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_44_dialog_content = "<size=45>Mengaum-!</size>",
  ui_story_5053_50530402_45_dialog_content = "Apakah Anda masih ingin membunuh saya, setelah membunuh keluarga saya?",
  ui_story_5053_50530402_46_dialog_content = "Saya akan membalas Anda dua kali lipat rasa sakit yang telah Anda berikan kepada mereka ...",
  ui_story_5053_50530402_47_dialog_content = "<size=45>Mengaum-!</size>",
  ui_story_5053_50530402_48_dialog_content = "<size=45>Sekarang mati!!!</size>",
  ui_story_5053_50530402_49_dialog_content = "<color=#e8d9bb>Buk, Buk...</color>",
  ui_story_5053_50530402_50_dialog_content = "(Mengapa mengapa mengapa?!)",
  ui_story_5053_50530402_51_dialog_content = "(Kenapa Nona Joshua membunuh Caleb, kakaknya sendiri?!)",
  ui_story_5053_50530402_52_dialog_content = "<color=#e8d9bb>Duk, duk, duk…</color>",
  ui_story_5053_50530402_53_dialog_content = "(Apakah semua orang di dunia ini sudah gila?)",
  ui_story_5053_50530402_54_dialog_content = "(Atau apakah saya terjebak dalam mimpi buruk yang tidak pernah berakhir?)",
  ui_story_5053_50530402_55_dialog_content = "<color=#e8d9bb>Duk, duk, duk…</color>",
  ui_story_5053_50530402_56_dialog_content = "(Apakah dia pergi?)",
  ui_story_5053_50530402_57_dialog_content = "(Tapi aku tidak bisa bersembunyi di bawah meja selamanya... Apa yang akan kulakukan?)",
  ui_story_5053_50530402_58_dialog_content = "<color=#e8d9bb>Bunyi gedebuk.</color>",
  ui_story_5053_50530402_59_dialog_content = "(Langkah kaki berhenti...)",
  ui_story_5053_50530402_60_dialog_content = "AKU MENEMUKANMU!",
  ui_story_5053_50530402_61_dialog_content = "Apa?!",
  ui_story_5053_50530402_62_dialog_content = "Oh, sayang, bahkan tidak Carleen masih main petak umpet.",
  ui_story_5053_50530402_63_dialog_content = "Kamu bukan anak kecil lagi, PlayerName. Berapa lama Anda ingin saya terus bermain game dengan Anda?",
  ui_story_5053_50530402_64_dialog_content = "Huff.. sip..",
  ui_story_5053_50530402_65_dialog_content = "Berhenti berlari. Itu hanya akan membuat kematianmu lebih menyakitkan.",
  ui_story_5053_50530402_66_dialog_content = "Mia, Caleb... Lumina mereka bagus. Saya tidak pernah merasa begitu bersemangat.",
  ui_story_5053_50530402_67_dialog_content = "Saya bertanya-tanya apa yang terjadi jika saya menggunakan Lumina Caelestite? Mungkin aku bisa membaca pikiran orang lain juga?",
  ui_story_5053_50530402_68_dialog_content = "Aku tidak akan membiarkanmu lolos begitu saja!",
  ui_story_5053_50530402_69_dialog_content = "Yah, aku sudah bisa mengendalikan orang di dunia ini.",
  ui_story_5053_50530402_70_dialog_content = "Itu pasti membuat segalanya menjadi sederhana dan mudah, bukan?",
  ui_story_5053_50530402_71_dialog_content = "Huff.. sip..",
  ui_story_5053_50530402_72_dialog_content = "(Hanya satu pintu di depanku... Tolong jangan biarkan ini menjadi jalan buntu!)",
  ui_story_5053_50530402_73_dialog_content = "Itu... Yah, kurasa itulah naluri The Last Caelestite.",
  ui_story_5053_50530402_74_dialog_content = "Pilihan bagus.",
  ui_story_5053_50530402_75_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5053_50530402_76_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_77_dialog_content = "Jakine?!",
  ui_story_5053_50530402_78_dialog_content = "Jakine! Tubuhnya dingin dan dia tidak bernapas...",
  ui_story_5053_50530402_79_dialog_content = "Anda pasti tahu cara memilih tempat, PlayerName.",
  ui_story_5053_50530402_80_dialog_content = "Peramal Northland bisa mengendalikan Crystal, jadi tentu saja, dia adalah orang pertama yang kubunuh.",
  ui_story_5053_50530402_81_dialog_content = "Kenapa lagi aku memintanya untuk tinggal bersamaku?",
  ui_story_5053_50530402_82_dialog_content = "Saya tidak mengerti, Nona Joshua, mengapa kau melakukan ini?",
  ui_story_5053_50530402_83_dialog_content = "Mengapa Anda membunuh Jakine dan saudaramu... Dan aku juga?",
  ui_story_5053_50530402_84_dialog_content = "Apakah begitu sulit untuk dipahami? Aku membutuhkan kekuatanmu.",
  ui_story_5053_50530402_85_dialog_content = "Saya tidak menanggung niat buruk Anda, tetapi pengorbanan Anda diperlukan.",
  ui_story_5053_50530402_86_dialog_content = "Saya tidak mengerti, apakah Anda yang sebenarnya Joshua?",
  ui_story_5053_50530402_87_dialog_content = "Apa yang Anda, benar-benar?",
  ui_story_5053_50530402_88_dialog_content = "Saya Joshua, yang asli Joshua!",
  ui_story_5053_50530402_89_dialog_content = "Buka mata Anda lebar-lebar dan perhatikan baik-baik. Ingat ini sebelum kamu mati.",
  ui_story_5053_50530402_90_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_5053_50530402_91_dialog_content = "Apa?",
  ui_story_5053_50530402_92_dialog_content = "Datanglah padaku, PlayerName...",
  ui_story_5053_50530402_93_dialog_content = "Jakine?!",
  ui_story_5053_50530402_94_dialog_content = "Kamu hidup? Saya pikir Anda ...",
  ui_story_5053_50530402_95_dialog_content = "Apakah kamu lupa? Saya telah menjadi peramal pengembara sejak saya masih kecil...",
  ui_story_5053_50530402_96_dialog_content = "Apa itu sedikit trik? ... (Mulai batuk)",
  ui_story_5053_50530402_97_dialog_content = "Jakine!",
  ui_story_5053_50530402_98_dialog_content = "Mana yang lainnya?",
  ui_story_5053_50530402_99_dialog_content = "...",
  ui_story_5053_50530402_100_dialog_content = "Kutukan...!",
  ui_story_5053_50530402_101_dialog_content = "Membuat ilusi dengan sihir Northland... Tidak heran kalian bisa menciptakan sesuatu seperti Crystal of Eternal Memory.",
  ui_story_5053_50530402_102_dialog_content = "Kecerdasan yang menjijikkan.",
  ui_story_5053_50530402_103_dialog_content = "Maaf, aku selalu menjadi anak nakal.",
  ui_story_5053_50530402_104_dialog_content = "Kalau begitu izinkan saya untuk menunjukkan kepada Anda beberapa disiplin!",
  ui_story_5053_50530402_105_dialog_content = "Waspada, bola kristal!",
  ui_story_5053_50530402_106_dialog_content = "Dapatkan Crystal of Eternal Memory itu di sini, PlayerName.",
  ui_story_5053_50530402_107_dialog_content = "Letakkan tanganmu di atasnya. Bahkan jika aku tidak bisa melakukannya...",
  ui_story_5053_50530402_108_dialog_content = "Anda tidak harus melepaskannya.",
  ui_story_5053_50530402_109_dialog_content = "Siap!",
  ui_story_5053_50530402_110_dialog_content = "Reditus, reditus, reditus!",
  ui_story_5053_50530402_111_dialog_content = "Putar balik ke awal...",
  ui_story_5053_50530402_112_dialog_content = "Abrakadabra—Urgh!",
  ui_story_5053_50530402_113_dialog_content = "Oh, tidak...",
  ui_story_5053_50530402_114_dialog_content = "Jakine... Jakine—!",
  ui_story_5053_50530501_0X_dialog_content = "<color=#e8d9bb>Setelah reset kedua—</color>",
  ui_story_5053_50530501_1_dialog_content = "Semuanya sudah diatur, tuanku.",
  ui_story_5053_50530501_2_dialog_content = "Gerbong menunggu di luar dan siap berangkat kapan saja.",
  ui_story_5053_50530501_3_dialog_content = "...",
  ui_story_5053_50530501_4_dialog_content = "Tuanku, apakah Anda masih mengkhawatirkan istri Anda?",
  ui_story_5053_50530501_5_dialog_content = "Joshua selalu dalam kesehatan yang baik dan dia biasanya tidak mengeluh tentang perasaan di bawah cuaca. Apalagi di hari seperti ini.",
  ui_story_5053_50530501_6_dialog_content = "Dia cukup sibuk akhir-akhir ini, mengadvokasi kebijakan baru kepada istri bangsawan. Saya membayangkan itu mengambil tol pada dirinya.",
  ui_story_5053_50530501_7_dialog_content = "Yakinlah, tuanku. Aku akan merawatnya dengan baik.",
  ui_story_5053_50530501_8_dialog_content = "Argh…",
  ui_story_5053_50530501_9_dialog_content = "Dimana saya...?",
  ui_story_5053_50530501_10_dialog_content = "Tunggu, tempat ini... Apakah di luar masih siang?",
  ui_story_5053_50530501_11_dialog_content = "Saya dikejar, dan saya berlari ke Jakine, Kemudian...",
  ui_story_5053_50530501_12_dialog_content = "(Terima kasih telah menyelamatkan saya, Jakine...)",
  ui_story_5053_50530501_13_dialog_content = "(Tapi aku tidak melihatnya di sekitar sini... Mungkinkah kita terpisah, seperti saat kita pertama kali tiba di dalam Crystal?)",
  ui_story_5053_50530501_14_dialog_content = "(Dan mengapa Lady Joshua menyerang kita seperti itu? Mungkinkah dia bukan yang sebenarnya Joshua?)",
  ui_story_5053_50530501_15_dialog_content = "(Tidak, dia <color=#FFB400>orang yang nyata</color>, sama seperti kita semua. Jakine membuktikannya menggunakan Crystal of Eternal Memory.)",
  ui_story_5053_50530501_16_dialog_content = "Saya Joshua, yang asli Joshua.",
  ui_story_5053_50530501_17_dialog_content = "(Cara dia menekankan identitasnya...apa maksudnya?)",
  ui_story_5053_50530501_18_dialog_content = "(Saya sangat bingung, tapi itu tidak penting sekarang. Jika ada sesuatu yang salah Joshua, bagaimana kita bisa kembali?)",
  ui_story_5053_50530501_19_dialog_content = "(Aaah... Ada begitu banyak hal yang tidak aku mengerti, dan kenapa hanya aku yang ada di sini?!)",
  ui_story_5053_50530501_20_dialog_content = "<color=#e8d9bb>Lubang, tepuk, lubang, tepuk—</color>",
  ui_story_5053_50530501_21_dialog_content = "Suara itu! Apakah itu...?",
  ui_story_5053_50530501_22_dialog_content = "Di Sini...?",
  ui_story_5053_50530501_23_dialog_content = "Bagaimana Dark Angel menemukan kami di sini? Saya pikir kami mengatur ulang semuanya!",
  ui_story_5053_50530501_24_dialog_content = "I-Itu suara kakakku...",
  ui_story_5053_50530501_25_dialog_content = "... Di Sini!",
  ui_story_5053_50530501_26_dialog_content = "Malam Putih, lindungi kami!",
  ui_story_5053_50530501_27_dialog_content = "Jangan kehilangan fokus dalam pertempuran, Caleb!",
  ui_story_5053_50530501_28_dialog_content = "Aaaah—!",
  ui_story_5053_50530501_29_dialog_content = "Sovereign's Blade!",
  ui_story_5053_50530501_30_dialog_content = "aku... benci...",
  ui_story_5053_50530501_31_dialog_content = "Argh!",
  ui_story_5053_50530501_32_dialog_content = "Itu cepat! Hati-hati, Tuhan Schwartz!",
  ui_story_5053_50530501_33_dialog_content = "Apakah Anda begitu putus asa untuk melawan saya satu lawan satu?",
  ui_story_5053_50530501_34_dialog_content = "Aku akan mengabulkan keinginanmu, kalau begitu.",
  ui_story_5053_50530501_35_dialog_content = "Sch... Schwartz...!",
  ui_story_5053_50530501_36_dialog_content = "Mia dan yang lainnya melawan Dark itu Angel lagi... Jadi kami berhasil memulai kembali memori!",
  ui_story_5053_50530501_37_dialog_content = "Saya harus ke sana dan membantu mereka!",
  ui_story_5053_50530501_38_dialog_content = "Kamu, disana... Berhenti.",
  ui_story_5053_50530501_39_dialog_content = "Penjaga? Waktu yang tepat! Lihat, saya—",
  ui_story_5053_50530501_40_dialog_content = "Tersangka... Basmi...",
  ui_story_5053_50530501_41_dialog_content = "(Hah? Sepertinya ada yang aneh dengan orang-orang ini?)",
  ui_story_5053_50530501_42_dialog_content = "Kalian sedang membicarakan apa?",
  ui_story_5053_50530501_43_dialog_content = "Wanita Joshua... seseorang ... penyusup?",
  ui_story_5053_50530501_44_dialog_content = "Penyusup... Harus menangkap... dan membunuh!",
  ui_story_5053_50530501_45_dialog_content = "(Pasti ada yang salah dengan pikiran mereka! Mereka seperti orang-orang dari alun-alun!)",
  ui_story_5053_50530501_46_dialog_content = "Aaaah!!!",
  ui_story_5053_50530502_1_dialog_content = "<color=#e8d9bb>Duaar—!!</color>",
  ui_story_5053_50530502_2_dialog_content = "Urgh... Batuk, batuk...",
  ui_story_5053_50530502_3_dialog_content = "Ke mana ia pergi?",
  ui_story_5053_50530502_4_dialog_content = "Mungkin melarikan diri di jalan setapak ke luar...",
  ui_story_5053_50530502_5_dialog_content = "Itu luar biasa, Tuhan Schwartz!",
  ui_story_5053_50530502_6_dialog_content = "Malaikat itu harus terluka, sekuat itu, dan mungkin tidak bisa pergi terlalu jauh.",
  ui_story_5053_50530502_7_dialog_content = "...",
  ui_story_5053_50530502_8_dialog_content = "Apakah Anda masih peduli tentang Dark Angel, Paman?",
  ui_story_5053_50530502_9_dialog_content = "Suaranya... Sudahlah, kakakku tidak akan pernah bisa menjadi monster.",
  ui_story_5053_50530502_10_dialog_content = "Tunggu, bukankah kita melupakan sesuatu? Oh tidak, di mana PlayerName?!",
  ui_story_5053_50530502_11_dialog_content = "Hei, kamu benar! Dimana PlayerName lari ke?!",
  ui_story_5053_50530502_12_dialog_content = "Oh, kalian semua!",
  ui_story_5053_50530502_13_dialog_content = "Fiuh ... Apakah saya kehilangan mereka?",
  ui_story_5053_50530502_14_dialog_content = "Di sana... Di sana!",
  ui_story_5053_50530502_15_dialog_content = "Bunuh penyusup!",
  ui_story_5053_50530502_16_dialog_content = "(Sial! Meskipun mereka tidak punya pikiran sekarang, para penjaga ini masih mustahil untuk digoyahkan!)",
  ui_story_5053_50530502_17_dialog_content = "Tidak... Di sana!",
  ui_story_5053_50530502_18_dialog_content = "(... Tunggu, saya mengerti!)",
  ui_story_5053_50530502_19_dialog_content = "<color=#e8d9bb>Gedebuk-</color>",
  ui_story_5053_50530502_20_dialog_content = "(Omong-omong, gerobak apa ini? Pasti untuk liburan... Pokoknya, kurasa mereka tidak akan melihatku di sini.)",
  ui_story_5053_50530502_21_dialog_content = "Tidak disana... Dimana?",
  ui_story_5053_50530502_22_dialog_content = "Jalan itu... Pergilah...",
  ui_story_5053_50530502_23_dialog_content = "Para penjaga itu bertingkah sangat aneh. Apakah mereka mengejar seseorang?",
  ui_story_5053_50530502_24_dialog_content = "Aku tidak yakin, tapi siapa yang mau memulai masalah di hari seperti ini? Parade akan segera dimulai juga!",
  ui_story_5053_50530502_25_dialog_content = "Saya tidak sabar untuk melihatnya!",
  ui_story_5053_50530502_26_dialog_content = "(Fiuh! Saya akhirnya berhasil kehilangan mereka...)",
  ui_story_5053_50530502_27_dialog_content = "(Menurut gadis itu, sepertinya pawai belum dimulai.)",
  ui_story_5053_50530502_28_dialog_content = "(Bagus. Itu memberi saya waktu untuk mengumpulkan pikiran dan memikirkan langkah saya selanjutnya.)",
  ui_story_5053_50530502_29_dialog_content = "(Saya punya beberapa pertanyaan serius untuk dipertimbangkan sekarang...)",
  ui_story_5053_50530502_30_option_content = "Situasi saat ini",
  ui_story_5053_50530502_31_dialog_content = "(Pawai masih belum dimulai, dan semua orang seharusnya sudah melihat Lady Joshua sekarang.)",
  ui_story_5053_50530502_32_dialog_content = "(Itu berarti ada dua kemungkinan skenario saat ini, yang keduanya bergantung pada <color=#FFB400>apakah semua orang ingat waktu reset</color>.)",
  ui_story_5053_50530502_33_dialog_content = "(Jika semua orang masih ingat, maka mereka pasti sudah melawan Lady Joshua dan melarikan diri.)",
  ui_story_5053_50530502_34_dialog_content = "(Jika itu masalahnya, yang lain seharusnya keluar mencariku sekarang. Aku masih belum terlalu familiar dengan Lumopolis, jadi sebaiknya aku tetap menunduk dan menunggu mereka menemukanku.)",
  ui_story_5053_50530502_35_dialog_content = "(Tapi jika tidak ada yang ingat waktu reset, maka mereka mungkin jatuh ke dalam perangkap Joshua...)",
  ui_story_5053_50530502_36_dialog_content = "(Jika demikian, maka semuanya harus terjadi persis seperti sebelum reset. Jakine akan tertinggal, dan yang lainnya akan menuju alun-alun.)",
  ui_story_5053_50530502_37_dialog_content = "(Kebetulan saya juga cukup dekat dengan alun-alun. Sepertinya taruhan terbaik saya adalah duduk di sini dan menunggu semua orang datang.)",
  ui_story_5053_50530502_38_dialog_content = "(Tapi kemudian ada Jakine... Sial! Kami tidak akan bisa menyelamatkannya sampai yang lain tiba di sini!)",
  ui_story_5053_50530502_39_option_content = "Ingatan\"",
  ui_story_5053_50530502_40_dialog_content = "(Berdasarkan Jakine, menggunakan ramalan untuk alasan apa pun membutuhkan a <color=#FFB400>kepatuhan yang ketat terhadap peraturannya</color>.)",
  ui_story_5053_50530502_41_dialog_content = "(Selama reset pertama, Jakine terus menyuruh kami <color=#FFB400>berpegangan erat pada tangan masing-masing</color>.)",
  ui_story_5053_50530502_42_dialog_content = "(Joshua juga mengatakan bahwa ini adalah alasan dia bisa mengingat peristiwa reset pertama. Itu karena dia bersama kami ketika itu terjadi.)",
  ui_story_5053_50530502_43_dialog_content = "(Apakah itu berarti dia berhasil memegang tangan kita tanpa kita sadari?)",
  ui_story_5053_50530502_44_dialog_content = "(Selama reset kedua, satu-satunya yang memegang Crystal of Eternal Memory adalah Jakine dan saya.)",
  ui_story_5053_50530502_45_dialog_content = "(Itu berarti Joshua dan yang lainnya tidak ingat reset kedua, kan?)",
  ui_story_5053_50530502_46_dialog_content = "(Jakine dan aku harus menjadi satu-satunya yang mengingat semua yang terjadi sejak kita tiba di sini...)",
  ui_story_5053_50530502_47_dialog_content = "(Atau setidaknya saya harap begitu.)",
  ui_story_5053_50530502_48_option_content = "Naga, para prajurit, dan Kegelapan Angel",
  ui_story_5053_50530502_49_dialog_content = "(Apa yang baru saja terjadi dengan para penjaga itu? Mengapa mereka mencoba menangkapku?)",
  ui_story_5053_50530502_50_dialog_content = "(Mereka sama gilanya dengan orang-orang dari alun-alun. Sepertinya mereka terserang penyakit misterius... Atau mereka sedang dikendalikan pikiran.)",
  ui_story_5053_50530502_51_dialog_content = "(Mengingat betapa bertekadnya mereka untuk memburuku, menurutku mereka berusaha memisahkanku dari yang lain. Mereka terus mengejarku, memaksaku meninggalkan mansion.)",
  ui_story_5053_50530502_52_dialog_content = "(Aku tidak bisa menggunakan kekuatan psikisku di dalam Crystal of Eternal Memory, jadi aku tidak tahu apa yang terjadi di lantai atas saat semua orang sedang bertarung.)",
  ui_story_5053_50530502_53_dialog_content = "(Dan saya akhirnya kehilangan kesempatan untuk bertemu kembali dengan mereka...)",
  ui_story_5053_50530502_54_dialog_content = "(Jika Joshua masih memiliki ingatannya, maka dia pasti mengirim tentara itu untuk membungkamku.)",
  ui_story_5053_50530502_55_dialog_content = "(Tapi jika tidak, maka dia pasti telah memerintahkan mereka untuk membunuh orang yang tersesat.)",
  ui_story_5053_50530502_56_dialog_content = "(Sama seperti pertama kali kita berpisah Jakine.)",
  ui_story_5053_50530502_57_dialog_content = "(Melawan Kegelapan Angel harus menjadi bagian dari rencananya juga. Dengan begitu, dia bisa memisahkan kita dan menghabisi kita Jakine!)",
  ui_story_5053_50530502_58_dialog_content = "(Pada titik ini, jelas bahwa para penjaga yang mengejarku bekerja untuknya...)",
  ui_story_5053_50530502_59_dialog_content = "(Mungkin aman untuk menganggap orang gila dari alun-alun dan naga hitam itu juga berada di bawah kendalinya.)",
  ui_story_5053_50530502_60_dialog_content = "(Yang berarti bahwa semua yang kami lalui sejak reset pertama adalah bagian dari rencananya... Sungguh menakutkan.)",
  ui_story_5053_50530502_61_dialog_content = "(Tapi bagaimana dengan Kegelapan Angel? Apa hubungannya dengan Joshua?)",
  ui_story_5053_50530502_62_dialog_content = "(Apakah mereka berdua bekerja sama? Atau ada cerita yang lebih dari itu...?)",
  ui_story_5053_50530502_63_dialog_content = "(Saya hanya tidak memiliki informasi yang cukup untuk dikerjakan saat ini.)",
  ui_story_5053_50530502_64_dialog_content = "(Sigh ... semua yang dikatakan, duduk di sini dan menunggu yang lain masih merupakan tindakan terbaik saya.)",
  ui_story_5053_50530502_65_dialog_content = "(Aku akan mengatakan yang sebenarnya kepada semua orang begitu mereka menemukanku, jadi kita bisa pergi menyelamatkan Jakine...)",
  ui_story_5053_50530502_66_dialog_content = "(Saya hanya berharap mereka semua baik-baik saja!)",
  ui_story_5053_50530601_1_dialog_content = "Jadi maksudmu...",
  ui_story_5053_50530601_2_dialog_content = "Kita bisa menghancurkan Kegelapan Angel dan membawa Lady Joshua dengan kami keluar dari sini ....",
  ui_story_5053_50530601_3_dialog_content = "... atau Kegelapan Angel membunuh kita dan lepas di dunia nyata?",
  ui_story_5053_50530601_4_dialog_content = "Itu benar, ya.",
  ui_story_5053_50530601_5_dialog_content = "...",
  ui_story_5053_50530601_6_dialog_content = "Aku mengerti rencana pelarian kita dengan baik, tapi...",
  ui_story_5053_50530601_7_dialog_content = "Dimana PlayerName? Aku benar-benar mulai khawatir tentang dia.",
  ui_story_5053_50530601_8_dialog_content = "Dia sudah terlalu lama terpisah dari kita. Sesuatu pasti telah terjadi padanya!",
  ui_story_5053_50530601_9_dialog_content = "Saya juga tidak yakin dengan situasinya saat ini, tapi jangan khawatir, saya akan mengirim tim penjaga untuk mencarinya.",
  ui_story_5053_50530601_10_dialog_content = "Kami kehabisan waktu. Jika kita ingin melarikan diri dari tempat ini dengan aman, prioritasnya adalah mengalahkan monster itu.",
  ui_story_5053_50530601_11_dialog_content = "Kalau begitu mari kita berburu Dark itu Angel!",
  ui_story_5053_50530601_12_dialog_content = "TIDAK, Jakine. Anda harus tinggal di sini bersamaku.",
  ui_story_5053_50530601_13_dialog_content = "Hah? Tapi kenapa? Bola kristalku juga sangat berguna dalam pertarungan!",
  ui_story_5053_50530601_14_dialog_content = "Ya, saya tahu, tapi Anda mengoperasikan Crystal.",
  ui_story_5053_50530601_15_dialog_content = "Jika yang lain terluka, kita selalu bisa memutar balik waktu untuk mengembalikan segalanya.",
  ui_story_5053_50530601_16_dialog_content = "Tetapi jika sesuatu terjadi pada Anda, itu tidak dapat diubah.",
  ui_story_5053_50530601_17_dialog_content = "J-Jika Anda mengatakan begitu ...",
  ui_story_5053_50530601_18_dialog_content = "Ibu? I-Jika Anda dan Jakine akan tinggal di sini, kemudian Carleen harus kembali juga.",
  ui_story_5053_50530601_19_dialog_content = "Aku tidak ingin dia dan Ayah merasa kesepian tanpa kita di sana.",
  ui_story_5053_50530601_20_dialog_content = "Sangat baik. Aku akan meminta penjaga memanggilnya kembali ke kamarnya untuk beristirahat.",
  ui_story_5053_50530601_21_dialog_content = "Anda tidak ingin dia di sini bersama kami, Ibu? Dia sudah lama menantikan hari ini, mengapa mengirimnya kembali ke kamarnya sendirian?",
  ui_story_5053_50530601_22_dialog_content = "Apakah dia tidak akan merasa buruk jika dia melewatkan pawai...?",
  ui_story_5053_50530601_23_dialog_content = "Vonnieku yang manis... Semua ini tidak nyata. Dunia di dalam Crystal of Eternal Memory tidak lebih dari sebuah ilusi.",
  ui_story_5053_50530601_24_dialog_content = "Kita harus mengikuti jalannya peristiwa yang telah ditentukan sebelumnya. Jangan biarkan kekhawatiran yang tidak perlu mengalihkan perhatian Anda dari tujuan Anda.",
  ui_story_5053_50530601_25_dialog_content = "Oh...",
  ui_story_5053_50530601_26_dialog_content = "Adikku benar, Mia. Ini semua hanya fantasi, jadi jangan biarkan emosi menguasai Anda.",
  ui_story_5053_50530601_27_dialog_content = "A-Baiklah. Maaf karena belum dewasa...",
  ui_story_5053_50530601_28_dialog_content = "...",
  ui_story_5053_50530601_29_dialog_content = "Joshua membuat poin yang valid. Keselamatan setiap orang harus menjadi prioritas utama kami, itulah sebabnya Caleb juga harus tinggal di sini.",
  ui_story_5053_50530601_30_dialog_content = "Aku akan mencari PlayerName saya sendiri. Untuk saat ini, semua orang harus tetap bersama.",
  ui_story_5053_50530601_31_dialog_content = "Itu tidak perlu. Sebuah tim penjaga dapat menemukan PlayerName sama cepatnya, jika tidak lebih.",
  ui_story_5053_50530601_32_dialog_content = "Selain itu, kami membutuhkan kekuatan semua orang jika kami berharap memiliki kesempatan melawan monster itu.",
  ui_story_5053_50530601_33_dialog_content = "Saya pikir Anda tahu sebaik saya tahu mana dari hal-hal ini yang lebih penting. Gunakan akal sehatmu, Daniel.",
  ui_story_5053_50530601_34_dialog_content = "Heh, penilaianmu setajam sebelumnya, Joshua. Saya harus mengatakan, ini benar-benar membawa saya kembali ke masa lalu kita.",
  ui_story_5053_50530601_35_dialog_content = "...",
  ui_story_5053_50530601_36_dialog_content = "Apakah ini benar-benar saat yang tepat untuk bernostalgia, kalian berdua? Kami masih berpacu dengan waktu.",
  ui_story_5053_50530601_37_dialog_content = "Bagaimanapun, saya sangat mampu menimbang pilihan untuk diri saya sendiri.",
  ui_story_5053_50530601_38_dialog_content = "Ayo, Mia.",
  ui_story_5053_50530601_39_dialog_content = "Y-Ya, Ayah.",
  ui_story_5053_50530601_40_dialog_content = "Ada apa dengan pria itu, tiba-tiba bertingkah aneh?!",
  ui_story_5053_50530601_41_dialog_content = "...",
  ui_story_5053_50530601_42_dialog_content = "Apakah sesuatu tentang Joshua mengganggumu, Mia?",
  ui_story_5053_50530601_43_dialog_content = "Ah! Um, yah... M-Mungkin sedikit...",
  ui_story_5053_50530601_44_dialog_content = "Mungkin hanya aku, tapi... setelah berpisah begitu lama, Ibu merasa agak asing.",
  ui_story_5053_50530601_45_dialog_content = "Katakan padaku, orang macam apa itu Joshua kepadamu?",
  ui_story_5053_50530601_46_dialog_content = "M-Ibu adalah... Ibu adalah orang yang paling baik dan paling sabar yang pernah saya kenal, dan dia mencintai anak-anak lebih dari apapun.",
  ui_story_5053_50530601_47_dialog_content = "Ya, itu Joshua di hati saya juga ada wanita yang hangat, baik hati, salah satu orang paling tabah dan tulus yang pernah saya temui.",
  ui_story_5053_50530601_48_dialog_content = "Ayah...!",
  ui_story_5053_50530601_49_dialog_content = "Percaya pada dirimu sendiri, Mia. Dan percayalah pada citra indah ibumu yang kau simpan dalam hatimu.",
  ui_story_5053_50530601_50_dialog_content = "Percaya padaku?",
  ui_story_5053_50530601_51_dialog_content = "Terlepas dari kecanggungan Anda yang biasa, Anda telah menunjukkan sisi diri Anda yang lebih kuat dan lebih berani selama cobaan ini.",
  ui_story_5053_50530601_52_dialog_content = "Saya pikir sudah waktunya bagi saya untuk menerima bahwa Anda telah dewasa.",
  ui_story_5053_50530601_53_dialog_content = "Mulai sekarang, saya berjanji untuk menghormati pendapat Anda alih-alih memberi tahu Anda bagaimana perasaan Anda.",
  ui_story_5053_50530601_54_dialog_content = "Tidak perlu ragu lagi, Mia. Apakah itu ada hubungannya dengan ibumu, atau Carleen, atau sesuatu yang lain...",
  ui_story_5053_50530601_55_dialog_content = "Lakukan apa pun yang menurut Anda benar, dan lakukan dengan berani. Aku akan selalu percaya padamu.",
  ui_story_5053_50530601_56_dialog_content = "(Apakah Ayah... Menyemangatiku?)",
  ui_story_5053_50530601_57_dialog_content = "(Aku belum pernah mendengar dia mengatakan hal seperti ini sebelumnya. Rasanya... menyenangkan.)",
  ui_story_5053_50530601_58_dialog_content = "Terima kasih ayah. Saya berjanji untuk menjadi lebih tegas mulai sekarang.",
  ui_story_5053_50530601_59_dialog_content = "Aku akan berdiri untuk mengawasi, seperti yang kita rencanakan. Jika saya melihat tanda-tanda Kegelapan Angel, Saya akan memberi tahu semua orang.",
  ui_story_5053_50530601_60_dialog_content = "Bagus. Waspadalah, Mia.",
  ui_story_5053_50530601_61_dialog_content = "(Mia harus aman di sana untuk saat ini. PlayerName, di sisi lain... Di mana dia sekarang?)",
  ui_story_5053_50530601_62_dialog_content = "(Ketidakhadirannya terasa sangat mencurigakan sekarang, tapi kenapa...?)",
  ui_story_5053_50530601_63_dialog_content = "Disini...",
  ui_story_5053_50530601_64_dialog_content = "... Di Sini!",
  ui_story_5053_50530601_65_dialog_content = "Suara itu...",
  ui_story_5053_50530601_66_dialog_content = "Sch... Schwartz...!!!",
  ui_story_5053_50530601_67_dialog_content = "Aaaaaah!!!",
  ui_story_5053_50530601_68_dialog_content = "Jadi ini adalah tempat Anda berada.",
  ui_story_5053_50530601_69_dialog_content = "Bagus. Selama Anda di sini, tidak ada orang lain yang dalam bahaya.",
  ui_story_5053_50530601_70_dialog_content = "Sakit! Mati mati!!!",
  ui_story_5053_50530601_71_dialog_content = "Anda tidak akan membodohi saya dengan meniru Joshua.",
  ui_story_5053_50530701_1_dialog_content = "Urgh... Aaaaah!",
  ui_story_5053_50530701_2_dialog_content = "(Tanpa Mia atau Caleb di sini, sepertinya kita seimbang. Sayangnya, Eclipsites ini sedikit memiringkan sisiknya.)",
  ui_story_5053_50530701_3_dialog_content = "\"Malam Putih, lindungi kami!\"",
  ui_story_5053_50530701_4_dialog_content = "Saya akan mengatakan kita telah mencapai jalan buntu. Apakah Anda puas sekarang?",
  ui_story_5053_50530701_5_dialog_content = "Sch... Schwartz...!",
  ui_story_5053_50530701_6_dialog_content = "Aku membencimu...!",
  ui_story_5053_50530701_7_dialog_content = "Kenapa…",
  ui_story_5053_50530701_8_dialog_content = "Itu sangat menyakitkan! Kenapa... Kenapa... mengkhianatiku?!",
  ui_story_5053_50530701_9_dialog_content = "Kamu bilang... Kita bangun... masa depan bersama! Anda berjanji...!",
  ui_story_5053_50530701_10_dialog_content = "Jadi mengapa... mengorbankan... keluarga?!",
  ui_story_5053_50530701_11_dialog_content = "Sakitnya...tak tertahankan!!!",
  ui_story_5053_50530701_12_dialog_content = "Apa katamu?",
  ui_story_5053_50530701_13_dialog_content = "Andai saja... Andai saja aku tahu...",
  ui_story_5053_50530701_14_dialog_content = "Aku tidak akan pernah... mencintai...",
  ui_story_5053_50530701_15_dialog_content = "Dan... memilihmu!!!",
  ui_story_5053_50530701_16_dialog_content = "?!",
  ui_story_5053_50530701_17_dialog_content = "Joshua...?!",
  ui_story_5053_50530701_18_dialog_content = "Tapi bagaimana ini bisa terjadi?",
  ui_story_5053_50530701_19_dialog_content = "...!!!",
  ui_story_5053_50530701_20_dialog_content = "Ahh...! M... Mia... bahaya...",
  ui_story_5053_50530701_21_dialog_content = "Kemana kamu pikir kamu akan pergi?!",
  ui_story_5053_50530701_22_dialog_content = "Graah—!",
  ui_story_5053_50530701_23_dialog_content = "Minggir, makhluk jahat!",
  ui_story_5053_50530701_24_dialog_content = "(Muda Schwartz baru saja menyelesaikan pidatonya, yang berarti duel akan segera dimulai.)",
  ui_story_5053_50530701_25_dialog_content = "(Jika semuanya berjalan seperti yang diharapkan, naga akan segera muncul dan orang-orang akan panik, bersama dengan para penjaga...)",
  ui_story_5053_50530701_26_dialog_content = "(Begitu itu terjadi, saya dapat memanfaatkan kekacauan dan berlari ke stand! Saya harus bertemu dengan yang lain dan memberi tahu mereka tentang Joshua sebelum terlambat!)",
  ui_story_5053_50530701_27_dialog_content = "Mengaum-!",
  ui_story_5053_50530701_28_dialog_content = "Aaaah!!!",
  ui_story_5053_50530701_29_dialog_content = "A-Benda apa itu?!",
  ui_story_5053_50530701_30_dialog_content = "Berlari! Tolong aku!!!",
  ui_story_5053_50530701_31_dialog_content = "Baiklah! Sekarang adalah kesempatanku untuk mencari Tuhan Schwartz dan yang lainnya—",
  ui_story_5053_50530701_32_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_5053_50530701_33_dialog_content = "Wah...! A-Apa itu tadi?!",
  ui_story_5053_50530701_34_dialog_content = "Mengaum-!",
  ui_story_5053_50530701_35_dialog_content = "<color=#e8d9bb>DUARR!!!</color>",
  ui_story_5053_50530701_36_dialog_content = "Aaaah...! Urgh!!!",
  ui_story_5053_50530701_37_dialog_content = "Kegelapan Angel?! Apa yang sedang terjadi?!",
  ui_story_5053_50530701_38_dialog_content = "Apa yang dia lakukan di langit? Apakah dia memblokir serangan naga?",
  ui_story_5053_50530701_39_dialog_content = "Seekor naga terbang?!",
  ui_story_5053_50530701_40_dialog_content = "Hidup naga! Hidup naga!!!",
  ui_story_5053_50530701_41_dialog_content = "Rumah Kartima? Jadi selama ini mereka adalah pengkhianat?",
  ui_story_5053_50530701_42_dialog_content = "Betapa beraninya mereka menunjukkan warna aslinya di saat seperti ini.",
  ui_story_5053_50530701_43_dialog_content = "(Tapi apa monster lain di langit itu...?)",
  ui_story_5053_50530701_44_dialog_content = "S-Kakak! Apa yang terjadi?",
  ui_story_5053_50530701_45_dialog_content = "Berlindunglah di belakangku, Carleen!",
  ui_story_5053_50530701_46_dialog_content = "(Itu Gelap Angel! Tapi kenapa dia ada di sini?)",
  ui_story_5053_50530701_47_dialog_content = "Apa-apaan ini...?!",
  ui_story_5053_50530701_48_dialog_content = "Veronica! Carleen! Tetap kembali!",
  ui_story_5053_50530701_49_dialog_content = "<color=#e8d9bb>Menghancurkan-!</color>",
  ui_story_5053_50530701_50_dialog_content = "(Dia terkena api naga! Tidak, tunggu... Sepertinya dia memblokir serangannya!)",
  ui_story_5053_50530701_51_dialog_content = "Tapi kenapa dia...",
  ui_story_5053_50530701_52_dialog_content = "Veronica, sepertinya dia membantu kita menangkis naga!",
  ui_story_5053_50530701_53_dialog_content = "D-Apakah dia kehilangan kesadaran?",
  ui_story_5053_50530701_54_dialog_content = "Kegelapan Angel... Saya tidak mengerti...",
  ui_story_5053_50530701_55_dialog_content = "Mia!!!",
  ui_story_5053_50530701_56_dialog_content = "Mia! Kau baik-baik saja?!",
  ui_story_5053_50530701_57_dialog_content = "PlayerName? Aku baik-baik saja, jangan khawatir! Kemana saja kamu selama ini?",
  ui_story_5053_50530701_58_dialog_content = "T-Di sini...!",
  ui_story_5053_50530701_59_dialog_content = "Bunuh... Bunuh penyusup!",
  ui_story_5053_50530701_60_dialog_content = "Sial! Bukan mereka lagi!",
  ui_story_5053_50530701_61_dialog_content = "Ada apa dengan para penjaga itu?!",
  ui_story_5053_50530701_62_dialog_content = "Hidup naga! Hidup naga!!!",
  ui_story_5053_50530701_63_dialog_content = "Menyerang!",
  ui_story_5053_50530701_64_dialog_content = "Mencari, PlayerName! Para pemberontak juga ikut berperang!",
  ui_story_5053_50530701_65_dialog_content = "Saya harus menjelaskan semuanya nanti, Mia. Saat ini, kita harus bersiap untuk pertarungan!",
  ui_story_5053_50530701_66_dialog_content = "Tidak peduli berapa banyak monster terbang atau bajingan pengkhianat yang memutuskan untuk menunjukkan wajah mereka hari ini! Atas nama Rumah Schwartz, kalian semua akan dihukum karena merusak hari ini!",
  ui_story_5053_50530701_67_dialog_content = "*Meraung*",
  ui_story_5053_50530701_68_dialog_content = "Hati-hati! Meninggalkan Kegelapan Angel sendirian untuk saat ini.",
  ui_story_5053_50530701_69_dialog_content = "Musuh kita berbeda dari sebelumnya. Jangan berharap untuk mengalahkannya dengan mudah.",
  ui_story_5053_50530701_70_dialog_content = "Dan siapakah Anda...?",
  ui_story_5053_50530701_71_dialog_content = "Fokuskan saja seranganmu pada naga itu, dan bantu aku menjatuhkannya!",
  ui_story_5053_50530701_72_dialog_content = "Hmph. Bahkan naga terbang bukanlah tandinganku.",
  ui_story_5053_50530701_73_dialog_content = "Cahaya Malam Putih!",
  ui_story_5053_50530701_74_dialog_content = "Mengaum-!!!",
  ui_story_5053_50530701_75_dialog_content = "Apa?! Aku menusuk tenggorokannya, tapi sembuh hampir seketika!!",
  ui_story_5053_50530701_76_dialog_content = "Regenerasi cepat... atau semacam kekebalan.",
  ui_story_5053_50530701_77_dialog_content = "Tapi bagaimana caranya? Siapa yang bisa memberikan kekuatan semacam ini padanya? Mungkinkah ini perbuatan Mime?",
  ui_story_5053_50530701_78_dialog_content = "...",
  ui_story_5053_50530701_79_dialog_content = "Waspada! Ini bersiap untuk menyerang lagi!",
  ui_story_5053_50530801_1_dialog_content = "Huff.. sip..",
  ui_story_5053_50530801_2_dialog_content = "Bunuh... Bunuh penyusup... Bunuh mereka semua!",
  ui_story_5053_50530801_3_dialog_content = "Ahhh! Membunuh mereka semua!!!",
  ui_story_5053_50530801_4_dialog_content = "Omong kosong! Mengapa semakin banyak penjaga gila ini muncul?! Bisakah kamu masih bertarung, Mia?",
  ui_story_5053_50530801_5_dialog_content = "Orang-orang ini mengerikan... Mata mereka benar-benar putih, dan wajah mereka semua berkerut!",
  ui_story_5053_50530801_6_dialog_content = "Aku baik-baik saja, tapi jumlah musuh terus bertambah!",
  ui_story_5053_50530801_7_dialog_content = "Orang-orang yang melarikan diri barusan telah bergabung dengan barisan mereka... Bahkan pemberontak yang jatuh pun ada di pihak mereka!",
  ui_story_5053_50530801_8_dialog_content = "Ini seperti semacam wabah...",
  ui_story_5053_50530801_9_dialog_content = "Jaga jarak dari mereka, Mia! Apa pun yang mengendalikan mereka tampaknya menyebar melalui serangan mereka!",
  ui_story_5053_50530801_10_dialog_content = "Tapi kita tidak akan bertahan lebih lama pada tingkat ini...!",
  ui_story_5053_50530801_11_dialog_content = "Apa ini juga bagian dari rencananya? Yang mulia Schwartz, kami butuh bantuan!",
  ui_story_5053_50530801_12_dialog_content = "Ayah terlalu sibuk melawan naga!",
  ui_story_5053_50530801_13_dialog_content = "(Ayah... Apa yang harus saya lakukan?)",
  ui_story_5053_50530801_14_dialog_content = "Tidak perlu ragu lagi, Mia. Apakah itu ada hubungannya dengan ibumu, atau Carleen, atau sesuatu yang lain...",
  ui_story_5053_50530801_15_dialog_content = "Lakukan apa pun yang menurut Anda benar, dan lakukan dengan berani. Aku akan selalu percaya padamu.",
  ui_story_5053_50530801_16_dialog_content = "(Percaya pada dirimu sendiri, Mia! Percayalah pada penilaian Anda!)",
  ui_story_5053_50530801_17_dialog_content = "Kuda nil—!",
  ui_story_5053_50530801_18_dialog_content = "<color=#e8d9bb>DUARR!!!</color>",
  ui_story_5053_50530801_19_dialog_content = "S-Sangat kuat!",
  ui_story_5053_50530801_20_dialog_content = "Kuda Nil! Terima kasih... Terima kasih telah menjawab panggilan saya! Aku berjanji tidak akan pernah meninggalkanmu lagi!",
  ui_story_5053_50530801_21_dialog_content = "Itu luar biasa, Mia! Anda mengalahkan setiap penjaga yang terinfeksi itu dalam satu gerakan!",
  ui_story_5053_50530801_22_dialog_content = "Saya senang itu berhasil! Ayo, ayo bantu ayahku!",
  ui_story_5053_50530801_23_dialog_content = "Mia... Tunggu...",
  ui_story_5053_50530801_24_dialog_content = "Terkesiap, terkesiap, terkesiap...",
  ui_story_5053_50530801_25_dialog_content = "V-Veronica...",
  ui_story_5053_50530801_26_dialog_content = "C-Carleen, kepalamu berdarah!!",
  ui_story_5053_50530801_27_dialog_content = "Apakah salah satu penjaga itu berhasil menyakitimu, Carleen? Apakah itu berarti dia akan...",
  ui_story_5053_50530801_28_dialog_content = "Menjauhlah darinya, Mia! Matanya mulai memutih, sama seperti yang lainnya!!",
  ui_story_5053_50530801_29_dialog_content = "Kemarilah, Carleen... Letakkan saja tombaknya, ya?",
  ui_story_5053_50530801_30_dialog_content = "Silakan?",
  ui_story_5053_50530801_31_dialog_content = "...",
  ui_story_5053_50530801_32_dialog_content = "Veronica... Sakit...",
  ui_story_5053_50530801_33_dialog_content = "Jangan takut, Carleen. Letakkan senjatamu dan biarkan aku membalut lukamu, oke?",
  ui_story_5053_50530801_34_dialog_content = "TIDAK! Kepalaku... sakit...!",
  ui_story_5053_50530801_35_dialog_content = "Ada suara aneh... Itu terus menyuruhku untuk membunuhmu! Tidak, saya tidak akan melakukannya!",
  ui_story_5053_50530801_36_dialog_content = "Aku tahu kamu tidak akan, Carleen. Aku akan melindungimu, jadi jangan takut!",
  ui_story_5053_50530801_37_dialog_content = "Tetap kembali!!",
  ui_story_5053_50530801_38_dialog_content = "Aku... aku Carleen de Schwartz... Bangga putri House Schwartz, dan pembela Lumopolis...",
  ui_story_5053_50530801_39_dialog_content = "Dan saya tidak akan pernah menyakiti siapa pun di keluarga saya! Tidak pernah!",
  ui_story_5053_50530801_40_dialog_content = "Urgh! Aku tidak ingin menyakitimu, Veronica! Itu sebabnya...",
  ui_story_5053_50530801_41_dialog_content = "Saya harus mengakhiri ini, di sini dan sekarang... Maaf, saudari... Selamat tinggal.",
  ui_story_5053_50530801_42_dialog_content = "Jangan lakukan itu, Carleen! Turunkan senjatamu!!",
  ui_story_5053_50530801_43_dialog_content = "Carleen!!!",
  ui_story_5053_50530801_44_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530801_45_dialog_content = "Dia menusuk lehernya dengan tombaknya sendiri...",
  ui_story_5053_50530801_46_dialog_content = "Carleen... Bagaimana Anda bisa ...",
  ui_story_5053_50530801_47_dialog_content = "...",
  ui_story_5053_50530801_48_dialog_content = "Tidak tidak...!",
  ui_story_5053_50530801_49_dialog_content = "Aaaaaahhhh!!!!",
  ui_story_5053_50530801_50_dialog_content = "Carleen!! Tidaaaaaak!!!",
  ui_story_5053_50530801_51_dialog_content = "Keluar darinya, Mia! Ini tidak nyata, ingat? Itu Carleen di dunia ini hanyalah ilusi!",
  ui_story_5053_50530801_52_dialog_content = "Aku tidak ingin kehilanganmu, Carleen!!! Tolong... jangan tinggalkan aku sendirian... tolong, Carleen...",
  ui_story_5053_50530801_53_dialog_content = "Tenang, Mia! Apakah Anda mendengarkan saya ?! Hai!!",
  ui_story_5053_50530801_54_dialog_content = "(Mia terlalu tertekan untuk mendengarku... Jangan bilang dia akan kehilangan kendali lagi?!)",
  ui_story_5053_50530801_55_dialog_content = "Waaaaaah!!!",
  ui_story_5053_50530801_56_dialog_content = "Itu panas!!!",
  ui_story_5053_50530801_57_dialog_content = "Kekuatan Mia akan mengamuk!!",
  ui_story_5053_50530801_58_dialog_content = "...",
  ui_story_5053_50530801_59_dialog_content = "A-Apa yang kau lakukan...?!",
  ui_story_5053_50530801_60_dialog_content = "Jangan menangis...",
  ui_story_5053_50530801_61_dialog_content = "Jangan menangis... Manisku, kecil... Vonnie...",
  ui_story_5053_50530801_62_dialog_content = "Semuanya akan baik-baik saja...",
  ui_story_5053_50530801_63_dialog_content = "Ah...",
  ui_story_5053_50530801_64_dialog_content = "Petik mawar... hanya untuk bayiku... ♪",
  ui_story_5053_50530801_65_dialog_content = "Angin sepoi-sepoi di wajahmu... hanya senyummu yang kubutuhkan... ♪",
  ui_story_5053_50530801_66_dialog_content = "Petiklah buket mawar... untuk ayah dan ibuku tersayang... ♪",
  ui_story_5053_50530801_67_dialog_content = "Meski dunia bisa berubah... Cinta kita akan selalu tetap sama... ♪",
  ui_story_5053_50530801_68_dialog_content = "Vonnie... Lihat... Ini Ibu...",
  ui_story_5053_50530801_69_dialog_content = "M-Ibu...? Ibu!",
  ui_story_5053_50530801_70_dialog_content = "Waaaaaaah!!!",
  ui_story_5053_50530801_71_dialog_content = "Ibu! Dia Carleen... Dia ...",
  ui_story_5053_50530801_72_dialog_content = "Tangannya... tangannya begitu hangat... dan ada darahnya...",
  ui_story_5053_50530801_73_dialog_content = "Ibu... Tolong...",
  ui_story_5053_50530801_74_dialog_content = "Ini... hanya mimpi buruk...",
  ui_story_5053_50530801_75_dialog_content = "Vonnie kecilku... Ini semua... hanya mimpi buruk...",
  ui_story_5053_50530801_76_dialog_content = "Anda bisa menangis ... jika Anda mau ...",
  ui_story_5053_50530801_77_dialog_content = "Ibu... disini...",
  ui_story_5053_50530801_78_dialog_content = "...",
  ui_story_5053_50530801_79_dialog_content = "Pelukan hangatnya... dan lagu pengantar tidur tadi...",
  ui_story_5053_50530801_80_dialog_content = "Ini benar-benar kamu, Ibu ...",
  ui_story_5053_50530801_81_dialog_content = "Saya sangat merindukan mu...",
  ui_story_5053_50530801_82_dialog_content = "Seperti aku... cintaku...",
  ui_story_5053_50530801_83_dialog_content = "(Kegelapan Angel... Dia menghibur Mia?!)",
  ui_story_5053_50530801_84_dialog_content = "(Tapi aku pikir dia hanya monster yang tidak punya pikiran! Tidak, tunggu... Joshua yang mengatakan itu, dan tidak ada yang dia katakan bisa dipercaya.)",
  ui_story_5053_50530801_85_dialog_content = "... Apa kamu baik baik saja, Mia? Apakah kamu masih bisa berdiri?",
  ui_story_5053_50530801_86_dialog_content = "PlayerName... Maaf, saya tidak bisa mengendalikan diri sekarang.",
  ui_story_5053_50530801_87_dialog_content = "Aku tidak menyakitimu, kan...?",
  ui_story_5053_50530801_88_dialog_content = "Tentu saja tidak! Melihat? Aku baik-baik saja, dan sepertinya kamu juga baik-baik saja.",
  ui_story_5053_50530801_89_dialog_content = "Jadi apa masalahnya dengan Dark ini Angel? Aku benar-benar tersesat sekarang...",
  ui_story_5053_50530801_90_dialog_content = "Dia ibuku, tidak diragukan lagi.",
  ui_story_5053_50530801_91_dialog_content = "Anda mengatakan ini adalah wanita sejati Joshua...?!",
  ui_story_5053_50530801_92_dialog_content = "Aku tahu ini sulit dimengerti, tapi hatiku berkata bahwa dia adalah ibuku yang sebenarnya...",
  ui_story_5053_50530801_93_dialog_content = "Yang lain memberi tahu kami bahwa Dark Angel tidak memiliki hati nurani dan hanya ada untuk menghancurkan... Tapi pelukannya barusan memberitahuku sebaliknya.",
  ui_story_5053_50530801_94_dialog_content = "Adapun Ibu yang kami temui di mansion, aku selalu merasakan sesuatu yang asing tentangnya...",
  ui_story_5053_50530801_95_dialog_content = "... Tidak, saya sepenuhnya mengerti. Sebenarnya, ini akan menjawab banyak pertanyaan.",
  ui_story_5053_50530801_96_dialog_content = "Hah? Apa maksudmu, PlayerName?",
  ui_story_5053_50530801_97_dialog_content = "Tidak ada cukup waktu untuk menjelaskan sekarang. Jakine dalam bahaya serius, dan kita harus menyelamatkannya.",
  ui_story_5053_50530801_98_dialog_content = "Saya akan memberi tahu Anda lebih banyak di jalan!",
  ui_story_5053_50530801_99_dialog_content = "Jakine? Saya pikir Anda tidak perlu khawatir. Bagaimanapun, Paman Caleb bersamanya.",
  ui_story_5053_50530801_100_dialog_content = "Caleb bersamanya?",
  ui_story_5053_50530801_101_dialog_content = "Itu benar. Ayah menyuruhnya untuk tetap tinggal, tapi aku tidak sepenuhnya yakin kenapa.",
  ui_story_5053_50530801_102_dialog_content = "Apa pun alasannya, tidak akan ada bedanya dengan hanya Caleb di sana.",
  ui_story_5053_50530801_103_dialog_content = "Itu Joshua dari mansion berencana untuk membunuh kita semua. Dia tidak bisa dipercaya.",
  ui_story_5053_50530801_104_dialog_content = "A-Apa yang kau bicarakan?!",
  ui_story_5053_50530801_105_dialog_content = "Ini bukan pertama kalinya semua ini terjadi, Mia!",
  ui_story_5053_50530801_106_dialog_content = "!!!",
  ui_story_5053_50530801_107_dialog_content = "Kaleb... Bahaya...",
  ui_story_5053_50530801_108_dialog_content = "M... Saudaraku... Caleb...",
  ui_story_5053_50530801_109_dialog_content = "Saudara... bahaya...",
  ui_story_5053_50530801_110_dialog_content = "Jadi maksudmu reset lain terjadi setelah yang pertama?",
  ui_story_5053_50530801_111_dialog_content = "Maka kita harus menemukan ayahku dan segera kembali!!",
  ui_story_5053_50530801_112_dialog_content = "Ayah!",
  ui_story_5053_50530801_113_dialog_content = "Yang mulia Schwartz, Kaleb dan Jakine berada dalam bahaya besar! Cepat, saya akan menjelaskan semuanya di jalan!",
  ui_story_5053_50530801_114_dialog_content = "Sch... Schwartz...",
  ui_story_5053_50530801_115_dialog_content = "... Tampaknya segalanya lebih rumit dari yang saya bayangkan.",
  ui_story_5053_50530801_116_dialog_content = "Sayangnya, saya tidak punya cara untuk meninggalkan tempat ini sekarang.",
  ui_story_5053_50530801_117_dialog_content = "Naga itu segera menyembuhkan setiap luka yang ditimbulkan padanya, bahkan yang paling parah sekalipun.",
  ui_story_5053_50530801_118_dialog_content = "Saya hanya bisa menggambarkan sifat tidak menyenangkan ini sebagai jenis kekebalan.",
  ui_story_5053_50530801_119_dialog_content = "Yang hanya ada di dalam dunia yang diciptakan oleh Crystal of Eternal Memory.",
  ui_story_5053_50530801_120_dialog_content = "Tapi bagaimana ini bisa terjadi...?",
  ui_story_5053_50530801_121_dialog_content = "Saya pikir yang lain Joshua pasti ada hubungannya dengan itu. Yang mulia Schwartz, bisakah kamu terus menangkis naga untuk saat ini?",
  ui_story_5053_50530801_122_dialog_content = "Joshua... Baiklah kalau begitu. Saya akan meninggalkan sisanya di tangan Anda.",
  ui_story_5053_50530801_123_dialog_content = "Veronica? Kenapa kamu tidak berlindung dari naga?! Dan siapa orang-orang ini...?",
  ui_story_5053_50530801_124_dialog_content = "...",
  ui_story_5053_50530801_125_dialog_content = "Ayah... Aku punya sesuatu yang mendesak untuk dilakukan di mansion. Tolong jangan mencoba untuk menghentikan saya.",
  ui_story_5053_50530801_126_dialog_content = "Tidak ada yang lebih mendesak daripada kesulitan kita saat ini, Veronica.",
  ui_story_5053_50530801_127_dialog_content = "Terlebih lagi, saya melarang Anda melibatkan diri dengan orang asing ini.",
  ui_story_5053_50530801_128_dialog_content = "Saya hampir tidak menganggap kami orang asing, Tuan Kota, mengingat kami telah bertarung di pihak yang sama untuk beberapa waktu sekarang.",
  ui_story_5053_50530801_129_dialog_content = "Ini bukan waktu atau tempat untuk tuntutan paternalistik.",
  ui_story_5053_50530801_130_dialog_content = "...",
  ui_story_5053_50530801_131_dialog_content = "Yakinlah, sebagai sekutu Veronica, PlayerName dan aku bersumpah untuk melindunginya dengan segala cara.",
  ui_story_5053_50530801_132_dialog_content = "Anda memiliki kewajiban untuk melindungi orang-orang Lumopolis, dan mereka membutuhkan Anda sekarang lebih dari sebelumnya.",
  ui_story_5053_50530801_133_dialog_content = "Cukup. Rekan saya, Ms. Rot, lebih dari mampu membela keluarga saya, dan istri saya juga tidak asing dengan pertempuran. Kami hampir tidak membutuhkan perlindungan dari luar, apalagi dari orang asing.",
  ui_story_5053_50530801_134_dialog_content = "Selain itu, saya tidak punya alasan untuk mempercayai kelompok yang menganggap monster sebagai salah satu dari mereka.",
  ui_story_5053_50530801_135_dialog_content = "...",
  ui_story_5053_50530801_136_dialog_content = "Ini bukan monster, Anda bisa yakin. Dia istriku.",
  ui_story_5053_50530801_137_dialog_content = "Apa...?!",
  ui_story_5053_50530801_138_dialog_content = "…!",
  ui_story_5053_50530801_139_dialog_content = "(Ayah mengira dia juga Ibu yang sebenarnya!)",
  ui_story_5053_50530801_140_dialog_content = "Ahem... Harus kuakui, seleramu cukup unik.",
  ui_story_5053_50530801_141_dialog_content = "Kalau begitu mari kita berhenti di situ.",
  ui_story_5053_50530801_142_dialog_content = "Tidak ada waktu untuk kalah. Mia, PlayerName, sisanya terserah padamu. Pergi sekarang!",
  ui_story_5053_50530801_143_dialog_content = "Ya!",
  ui_story_5053_50530801_144_dialog_content = "Kaleb...",
  ui_story_5053_50530801_145_dialog_content = "Anda ingin ikut juga, Bunda?",
  ui_story_5053_50530801_146_dialog_content = "Lindungi... Caleb...",
  ui_story_5053_50530801_147_dialog_content = "Saya mengerti. Kita akan melakukannya bersama, sekarang ayo pergi!",
  ui_story_5053_50530901_1_dialog_content = "Bagaimana keadaan di luar, Caleb?",
  ui_story_5053_50530901_2_dialog_content = "Aku punya firasat buruk tentang raungan yang kita dengar sebelumnya.",
  ui_story_5053_50530901_3_dialog_content = "Sepakat. Untuk beberapa alasan, naga itu muncul jauh lebih awal dari yang diperkirakan.",
  ui_story_5053_50530901_4_dialog_content = "Alun-alun pusat seharusnya benar-benar berantakan sekarang.",
  ui_story_5053_50530901_5_dialog_content = "Lalu bukankah itu berarti semua orang dalam bahaya sekarang?",
  ui_story_5053_50530901_6_dialog_content = "Yang mulia Schwartz, Mia, Dan PlayerName, yang masih belum muncul dimanapun...",
  ui_story_5053_50530901_7_dialog_content = "Tidak perlu khawatir. Saya yakin Daniel bisa menangani semuanya.",
  ui_story_5053_50530901_8_dialog_content = "Untuk diri kita sendiri... Bagus, kamu datang tepat waktu.",
  ui_story_5053_50530901_9_dialog_content = "...",
  ui_story_5053_50530901_10_dialog_content = "Melihat? Adikku selalu menjadi orang yang berpikir ke depan dan mempersiapkan diri.",
  ui_story_5053_50530901_11_dialog_content = "Anda dan yang lainnya aman, Jakine. Saya berjanji.",
  ui_story_5053_50530901_12_dialog_content = "Baiklah…",
  ui_story_5053_50530901_13_dialog_content = "Nah, maukah Anda menjadi sayang dan mengunci pintu untuk kami, Jakine?",
  ui_story_5053_50530901_14_dialog_content = "Oh, tentu! Lagi pula, bahkan kunci sederhana pun dapat melakukan keajaiban bagi keselamatan kita!",
  ui_story_5053_50530901_15_dialog_content = "Izinkan saya mengajukan pertanyaan, Caleb. Mengapa Anda ingin menyelamatkan saya?",
  ui_story_5053_50530901_16_dialog_content = "Hmm? Karena kau adikku, tentu saja! Kakak mana yang tidak mau membantu adiknya sendiri?",
  ui_story_5053_50530901_17_dialog_content = "Jadi karena hubungan kekerabatan kita... begitukah?",
  ui_story_5053_50530901_18_dialog_content = "Itu benar. Dunia mungkin berubah di sekitar kita, tapi ikatan di antara kita... Antara kamu, ayah kita, dan aku sendiri...",
  ui_story_5053_50530901_19_dialog_content = "Itu tidak akan pernah berubah. Tidak peduli berapa tahun berlalu, aku akan selalu merasa seperti ini.",
  ui_story_5053_50530901_20_dialog_content = "Apakah begitu? Terlepas dari motif Anda, saya harus berterima kasih karena telah menyelamatkan tubuh saya.",
  ui_story_5053_50530901_21_dialog_content = "Kau melakukannya dengan baik, Caleb.",
  ui_story_5053_50530901_22_dialog_content = "Joshua...!",
  ui_story_5053_50530901_23_dialog_content = "Memang benar dunia adalah tempat yang selalu berubah, tapi ada beberapa hal yang bahkan waktu pun tidak bisa berubah...",
  ui_story_5053_50530901_24_dialog_content = "Katakan padaku, seperti apa Lumopolis setelah dua belas tahun?",
  ui_story_5053_50530901_25_dialog_content = "Tidak ada yang berubah. Bangsawan parasit itu keras kepala dan tidak tahu malu seperti sebelumnya.",
  ui_story_5053_50530901_26_dialog_content = "Setelah menggemukkan diri demi kejayaan Lumopolis, yang tersisa hanyalah sistem pembusukan yang hanya ditutupi oleh veneer tertipis.",
  ui_story_5053_50530901_27_dialog_content = "Begitu... Dan bagaimana dengan House Schwartz?",
  ui_story_5053_50530901_28_dialog_content = "Schwartz? Dia yang paling menjijikkan dari semuanya.",
  ui_story_5053_50530901_29_dialog_content = "Dia membuat begitu banyak janji kepada Anda di masa lalu yang tidak pernah bisa dia tepati.",
  ui_story_5053_50530901_30_dialog_content = "Dia bahkan bersumpah akan mengubah Lumopolis menjadi mercusuar kebebasan dan kesetaraan...",
  ui_story_5053_50530901_31_dialog_content = "Pada titik ini, dia bisa melawan aristokrasi yang korup sampai nafas terakhirnya, dan tetap tidak ada yang berubah.",
  ui_story_5053_50530901_32_dialog_content = "Kelemahannya juga menjadi alasan keluargamu berantakan. Anda dan putri Anda seharusnya tidak pernah menderita seperti Anda, dan saya semakin membencinya karenanya!",
  ui_story_5053_50530901_33_dialog_content = "Aku mungkin tidak tahu banyak tentang politik, tapi kau terdengar sedikit ekstrim, Caleb.",
  ui_story_5053_50530901_34_dialog_content = "Saya pikir Tuhan Schwartz layak mendapatkan kredit lebih dari itu. Bahkan dengan semua pembuat kode yang mulia itu terus-menerus berkomplot melawannya, dia masih mempertahankan penampilan yang begitu terhormat di mata publik.",
  ui_story_5053_50530901_35_dialog_content = "Apa yang akan Anda ketahui tentang cara kerja bagian dalam Lumopolis, Jakine? Satu-satunya hal yang Anda dan seluruh dunia dapat lihat adalah apa yang disebut \"penampilan terhormat\".",
  ui_story_5053_50530901_36_dialog_content = "T-Tapi bahkan Ratu Bethlehem berpikir... Ugh, sudahlah! Aku hanya akan mengobrol dengan para penjaga!",
  ui_story_5053_50530901_37_dialog_content = "Bagaimana denganku, Kaleb? Apakah Anda melihat saya gagal dalam memilih Daniel sebagai suami saya?",
  ui_story_5053_50530901_38_dialog_content = "T-Tidak sama sekali! Anda hanyalah korban kebohongan besar Schwartz!",
  ui_story_5053_50530901_39_dialog_content = "Dan jika... pikiran Anda, ini murni hipotetis, tetapi jika Anda meninggalkannya... Rumah kami akan selalu terbuka untuk Anda.",
  ui_story_5053_50530901_40_dialog_content = "Dan jika Anda bosan dengan Lumopolis dan kotorannya, kami selalu bisa tinggal di tempat lain!",
  ui_story_5053_50530901_41_dialog_content = "Itu tidak perlu, Caleb. Saya tidak berniat membiarkan Lumopolis membusuk. Saya akan mengubah kota ini dalam hidup saya, jika itu hal terakhir yang saya lakukan.",
  ui_story_5053_50530901_42_dialog_content = "...",
  ui_story_5053_50530901_43_dialog_content = "Tapi Anda benar mengatakan itu Schwartz berada di luar tabungan. Aku telah kehilangan semua harapan padanya.",
  ui_story_5053_50530901_44_dialog_content = "Joshua... Anda akhirnya mau menceraikannya?!",
  ui_story_5053_50530901_45_dialog_content = "Caleb, hanya sedikit orang yang mau menentang Schwartz.",
  ui_story_5053_50530901_46_dialog_content = "Tampaknya upaya kami untuk membesarkanmu tidak sia-sia.",
  ui_story_5053_50530901_47_dialog_content = "Kita? Joshua, apakah Anda mungkin berbicara tentang ayah kami? Apa hubungannya dia dengan ini? Dan mengapa mengatakan hal seperti itu...?",
  ui_story_5053_50530901_48_dialog_content = "Tampaknya waktunya telah tiba untuk mengatakan yang sebenarnya, Caleb. Penjaga, tangkap dia.",
  ui_story_5053_50530901_49_dialog_content = "...",
  ui_story_5053_50530901_50_dialog_content = "Aduh!!! Hei, apa yang kalian lakukan?!",
  ui_story_5053_50530901_51_dialog_content = "Apa yang Anda maksud dengan kebenaran, Joshua? Dan apa yang kamu lakukan Jakine??",
  ui_story_5053_50530901_52_dialog_content = "Kaleb... <color=#FFB400>Aku bukan saudara perempuanmu dengan darah</color>.",
  ui_story_5053_50530901_53_dialog_content = "Apa...?",
  ui_story_5053_50530901_54_dialog_content = "Bertahun-tahun yang lalu, keluarga saya menolak untuk tunduk pada House Schwartz dan pemerintahannya yang lalim. Akibatnya, keluarga saya diberantas oleh ayah Daniel, penguasa kota sebelumnya.",
  ui_story_5053_50530901_55_dialog_content = "Banyak keluarga lain berbagi nasib kami juga. Hanya sedikit dari kami yang selamat dan saat itu aku masih anak-anak.",
  ui_story_5053_50530901_56_dialog_content = "Kami semua datang untuk membenci House Schwartz, dan kami bersumpah untuk membalas dendam pada setiap orang dari mereka.",
  ui_story_5053_50530901_57_dialog_content = "Akhirnya, saya menemukan jalan ke Taman Lumopolis. Keluarga bangsawan yang berduka yang kehilangan putri mereka karena tirani Schwartz menerima saya sebagai salah satu dari mereka.",
  ui_story_5053_50530901_58_dialog_content = "Tunggu... Keluarga yang berduka... Siapa <color=#FFB400>kehilangan putri mereka Schwartz</color>...",
  ui_story_5053_50530901_59_dialog_content = "Itu benar <color=#FFB400>Joshua</color>, adikmu. Kakak dan ibu kandungmu sudah lama terbunuh.",
  ui_story_5053_50530901_60_dialog_content = "Mereka tidak pernah bertengkar dengan House Schwartz. Mereka hanya mengunjungi seorang teman, lawan politik Schwartz yang keluarganya telah ditandai untuk dieliminasi.",
  ui_story_5053_50530901_61_dialog_content = "... Dan Ayah, apakah dia tahu tentang ini...?",
  ui_story_5053_50530901_62_dialog_content = "Tentu saja dia melakukannya. Ayahmu adalah orang yang memintaku menggantikan putrinya dan membalas dendam terhadap House Schwartz.",
  ui_story_5053_50530901_63_dialog_content = "I-Tidak mungkin! Bagaimana bisa pria yang baik dan jujur seperti ayahku...",
  ui_story_5053_50530901_64_dialog_content = "Kebencian bahkan dapat mendorong orang yang paling berbelas kasih untuk melakukan hal-hal jahat, Caleb.",
  ui_story_5053_50530901_65_dialog_content = "Itu adalah balas dendam, bukan cinta, yang memotivasi kami untuk membesarkan Anda menjadi pria seperti sekarang ini.",
  ui_story_5053_50530901_66_dialog_content = "Ketika upaya pembunuhan ayahmu berakhir dengan kegagalan, dia mengambil nyawanya sendiri bukan hanya untuk melindungi kita, tapi untuk melindungi bara balas dendam.",
  ui_story_5053_50530901_67_dialog_content = "Ketika saya melihat ketulusan Daniel bertahun-tahun yang lalu, saya memberinya satu kesempatan terakhir untuk pindah rumah Schwartz dan Lumopolis menjadi lebih baik.",
  ui_story_5053_50530901_68_dialog_content = "Saya menawarkan dukungan saya yang tak tergoyahkan dalam kampanyenya untuk menjadi Tuan Kota berikutnya.",
  ui_story_5053_50530901_69_dialog_content = "Saya berkata pada diri sendiri bahwa saya lebih baik daripada ayahnya, bahwa saya tidak akan pernah membungkuk begitu rendah untuk membunuh orang yang tidak bersalah, hanya untuk mendapatkan apa yang saya inginkan.",
  ui_story_5053_50530901_70_dialog_content = "Tapi saya salah. Daniel terlalu tidak kompeten untuk mengubah apa pun, jadi saya menyadari sudah waktunya untuk House Schwartz menderita murka kita.",
  ui_story_5053_50530901_71_dialog_content = "Caleb, buang <color=#FFB400>Jakine</color>.",
  ui_story_5053_50530901_72_dialog_content = "... Apa? Apa yang kamu katakan, Joshua?!",
  ui_story_5053_50530901_73_dialog_content = "Saya membutuhkan Lumina dari orang luar untuk pergi dari sini. Saya masih memiliki tujuan untuk dipenuhi di luar sana.",
  ui_story_5053_50530901_74_dialog_content = "TIDAK, Joshua... Jakine tidak ada hubungannya dengan semua ini! Anda mengatakannya sendiri, Anda tidak mau membunuh orang yang tidak bersalah untuk mendapatkan apa yang Anda inginkan!",
  ui_story_5053_50530901_75_dialog_content = "Kematiannya adalah pengorbanan yang diperlukan.",
  ui_story_5053_50530901_76_dialog_content = "Apa... Apa kau sudah gila?! Apa yang terjadi pada Lady yang manis dan lembut Joshua dari sebelumnya?!",
  ui_story_5053_50530901_77_dialog_content = "Saya ingin menanyakan hal yang sama! Anda membesarkan saya bukan karena cinta, tetapi untuk balas dendam ... Saya belum pernah mendengar hal yang lebih menggelikan dalam hidup saya! Jakine, apakah Anda yakin orang ini bukan hanya ilusi lain ?!",
  ui_story_5053_50530901_78_dialog_content = "Dia tidak, percayalah! Dan aku juga tidak merapal mantra padanya!",
  ui_story_5053_50530901_79_dialog_content = "Berapa lama kamu akan terus mengabaikan kebenaran, Caleb? Apakah Anda ingin pengorbanan keluarga Anda sia-sia?",
  ui_story_5053_50530901_80_dialog_content = "...",
  ui_story_5053_50530901_81_dialog_content = "Tidak masalah, saya bisa membuangnya Jakine saya sendiri. Sepertinya kami gagal mendidikmu secara menyeluruh, Caleb.",
  ui_story_5053_50530901_82_dialog_content = "Saya akan memberi Anda satu kesempatan terakhir untuk membuktikan tekad Anda. Ketika saatnya tiba, Anda harus menghilangkannya secara pribadi Schwartz, bersama yang lainnya.",
  ui_story_5053_50530901_83_dialog_content = "Argh, lepaskan aku! Kau gila jika berpikir bisa membunuh kami semua!!!",
  ui_story_5053_50530901_84_dialog_content = "Anda tidak punya siapa-siapa untuk disalahkan Schwartz. Selamat tinggal, utusan Northland.",
  ui_story_5053_50530901_85_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5053_50530901_86_dialog_content = "... Kamu benar, Joshua. Meskipun sebagian besar dari Anda telah menjadi asing bagi saya, tidak dapat disangkal bahwa Anda adalah saudara perempuan saya yang terkasih.",
  ui_story_5053_50530901_87_dialog_content = "Karena itulah aku harus menghentikanmu! Aku tidak akan membiarkanmu hidup dengan penyesalan karena melakukan sesuatu yang sangat buruk!",
  ui_story_5053_50530901_88_dialog_content = "Menyesali? Saya tidak pernah sekalipun menyesali apa pun. Saya memilih untuk membesarkan Anda di tempat ayah pengecut Anda sehingga Anda akan mewarisi keinginan kami untuk membalas dendam.",
  ui_story_5053_50530901_89_dialog_content = "Argh...!",
  ui_story_5053_50530901_90_dialog_content = "Namun Anda telah memilih untuk mengkhianati saya... Sama seperti yang lainnya!!!",
  ui_story_5053_50530901_91_dialog_content = "TIDAK, Joshua... Aku tidak akan pernah mengkhianatimu!",
  ui_story_5053_50530901_92_dialog_content = "Hmph, jadi kamu berhasil melucuti senjataku... Tapi trik kecil tidak akan menyelamatkanmu sekarang!",
  ui_story_5053_50530901_93_dialog_content = "Jika kita jujur, saya juga harus membuat pengakuan. Bertahun-tahun ini, saya telah mengatakan itu Schwartz tidak layak untukmu, tapi kenyataannya adalah...",
  ui_story_5053_50530901_94_dialog_content = "Aku membencinya! Dengan sepenuh hati, aku membenci pria itu dan anak-anak yang kau lahirkan karena mereka mengambilmu dariku! Mereka mengambil satu-satunya keluarga yang tersisa di dunia ini!",
  ui_story_5053_50530901_95_dialog_content = "Saya tidak peduli bahwa kami tidak memiliki hubungan darah ... Anda membesarkan saya dari seorang anak menjadi dewasa, dan Anda akan selalu menjadi saudara perempuan saya tercinta!",
  ui_story_5053_50530901_96_dialog_content = "Tampaknya Anda tidak akan pernah lebih dari seorang anak yang menangis, sangat membutuhkan perhatian saudara perempuannya. Sekarang menyingkirlah!",
  ui_story_5053_50530901_97_dialog_content = "Itu benar! Dan saya tidak akan pernah berubah, tidak peduli seberapa banyak Anda mengejek saya!",
  ui_story_5053_50530901_98_dialog_content = "Tapi saya tahu... Saya tahu betapa Anda mencintai suami dan putri Anda; tidak ada yang saya lakukan yang bisa mengubahnya!",
  ui_story_5053_50530901_99_dialog_content = "Sudah kubilang itu semua hanya akting!!",
  ui_story_5053_50530901_100_dialog_content = "aku... aku minta maaf, Joshua, tapi saya menolak untuk percaya itu.",
  ui_story_5053_50530901_101_dialog_content = "Dan saya menolak untuk membiarkan Anda melalui ini. Aku akan melindungi keluargamu yang berharga, bahkan dengan nyawaku sendiri!",
  ui_story_5053_50530901_102_dialog_content = "Baiklah, maka hidup Anda dan Lumina Anda sekarang hilang.",
  ui_story_5053_50530901_103_dialog_content = "Urgh...?!",
  ui_story_5053_50530901_104_dialog_content = "Tidak... Tidaaaaaak!! Kaleb!!!",
  ui_story_5053_50530901_105_dialog_content = "... Anda membuat pilihan Anda.",
  ui_story_5053_50530901_130_dialog_content = "Kaleb!!!",
  ui_story_5053_50530901_131_dialog_content = "<color=#e8d9bb>Menghancurkan-!</color>",
  ui_story_5053_50530901_132_dialog_content = "<size=45>Aaaaaah—!</size>",
  ui_story_5053_50530901_133_dialog_content = "Ugh!",
  ui_story_5053_50530901_134_dialog_content = "Urgh—!",
  ui_story_5053_50530901_135_dialog_content = "?!",
  ui_story_5053_50530901_136_dialog_content = "Oh, makhluk menjijikkan, muncul di saat seperti ini...!",
  ui_story_5053_50530901_138_dialog_content = "Kaleb! Tunggu saja, tolong!!!",
  ui_story_5053_50530901_139_dialog_content = "K... Kaleb...!!",
  ui_story_5053_50530901_140_dialog_content = "Heh... Membunuhku dengan satu serangan... Jadi masih ada sedikit belas kasihan di hatinya...",
  ui_story_5053_50530901_141_dialog_content = "Ini tidak baik. Lukanya terlalu dalam, dia kehilangan terlalu banyak darah...",
  ui_story_5053_50530901_143_dialog_content = "Sangat gelap... Aku tidak bisa melihat apa-apa.",
  ui_story_5053_50530901_145_dialog_content = "Tidak... Tolong...",
  ui_story_5053_50530901_146_dialog_content = "Joshua...? Apakah itu kamu...?",
  ui_story_5053_50530901_147_dialog_content = "Kaleb... Kaleb!",
  ui_story_5053_50530901_148_dialog_content = "Aku disini...",
  ui_story_5053_50530901_149_dialog_content = "Aku... Aku mengerti... Batuk, batuk!!!",
  ui_story_5053_50530901_150_dialog_content = "Apakah Anda ... Apakah Anda meletakkan senjata Anda, Joshua?",
  ui_story_5053_50530901_151_dialog_content = "Saya sangat senang...",
  ui_story_5053_50530901_152_dialog_content = "...",
  ui_story_5053_50530901_153_dialog_content = "Kaleb?! Kaleb!!!",
  ui_story_5053_50530901_155_dialog_content = "Kumohon... Caleb!!!",
  ui_story_5053_50530901_156_dialog_content = "Tidak tidak...!!",
  ui_story_5053_50530901_157_dialog_content = "<size=50>Hraaaaaaaaaah!!!</size>",
  ui_story_5053_50531001_1_dialog_content = "Hosh... Hosh...",
  ui_story_5053_50531001_2_dialog_content = "Apakah kamu baik-baik saja, PlayerName? Kita bisa berhenti dan istirahat jika perlu.",
  ui_story_5053_50531001_3_dialog_content = "Aku baik-baik saja, jangan khawatir. Aku hanya khawatir karena Gelap Angel lepas landas begitu cepat sekarang.",
  ui_story_5053_50531001_4_dialog_content = "Dia bersama kami selama ini, tapi kemudian dia tiba-tiba terbang seolah-olah dia merasakan sesuatu yang salah...",
  ui_story_5053_50531001_5_dialog_content = "Dia melakukan hal yang persis sama sebelumnya, ketika dia merasa bahwa kamu dalam bahaya. Aku benar-benar mulai khawatir Jakine dan Kaleb.",
  ui_story_5053_50531001_6_dialog_content = "Kami hampir sampai! Semoga mereka masih baik-baik saja...",
  ui_story_5053_50531001_7_dialog_content = "Mia, apakah Anda yakin itu Jakine tidak ingat apapun tentang reset kedua?",
  ui_story_5053_50531001_8_dialog_content = "Saya yakin itu. Tak satu pun dari kami yang mengingatnya pernah terjadi... Itulah sebabnya kami percaya semua yang lain Joshua memberitahu kami.",
  ui_story_5053_50531001_9_dialog_content = "Sejujurnya, aku masih kesulitan mempercayai ceritamu sendiri, PlayerName...",
  ui_story_5053_50531001_10_dialog_content = "Itu sebabnya... Aku perlu melihat kebenarannya sendiri!",
  ui_story_5053_50531001_11_dialog_content = "(Jadi mengapa saya mengingat semuanya, meskipun Jakine tidak? Itu tidak masuk akal...)",
  ui_story_5053_50531001_12_dialog_content = "Ada yang tidak beres. Kemana semua penjaga?",
  ui_story_5053_50531001_13_dialog_content = "Rasanya bumi bergetar... Mia, mencari!!",
  ui_story_5053_50531001_14_dialog_content = "?!",
  ui_story_5053_50531001_15_dialog_content = "Penyusup! Pengkhianat! Mati-!",
  ui_story_5053_50531001_16_dialog_content = "Ahhh—!!!",
  ui_story_5053_50531001_17_dialog_content = "Mati! Mati! Mati!",
  ui_story_5053_50531001_18_dialog_content = "Bukan penjaga gila itu lagi!",
  ui_story_5053_50531001_19_dialog_content = "Ahhhh!!! Seseorang selamatkan aku!!!",
  ui_story_5053_50531001_20_dialog_content = "Apakah itu... Jakine?!",
  ui_story_5053_50531001_21_dialog_content = "Para penjaga mengejarnya! Kita harus berjuang melewati gerombolan ini, Mia!",
  ui_story_5053_50531001_22_dialog_content = "Jumlah mereka terlalu banyak! Kuda Nil—",
  ui_story_5053_50531001_23_dialog_content = "Minggir, Putri Veronica—!",
  ui_story_5053_50531001_24_dialog_content = "?!?!",
  ui_story_5053_50531001_25_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5053_50531001_26_dialog_content = "Urgh...!!",
  ui_story_5053_50531001_27_dialog_content = "Aaaaaahhh!!!",
  ui_story_5053_50531001_28_dialog_content = "(Ms. Blanc?! Itu luar biasa! Dia menari di antara gerombolan penjaga dan menghabisi mereka semua!)",
  ui_story_5053_50531001_29_dialog_content = "Nona Busuk! Dibelakangmu!",
  ui_story_5053_50531001_30_dialog_content = "Jangan khawatirkan dirimu, Putri Veronica.",
  ui_story_5053_50531001_31_dialog_content = "Sebagai anggota Nightwatch, tugas saya adalah mencegah siapa pun mencemarkan Lumopolis.",
  ui_story_5053_50531001_32_dialog_content = "Tidak ada yang akan mengganggu kedamaian dan ketertiban Lumopolis di bawah pengawasanku!",
  ui_story_5053_50531001_33_dialog_content = "Demi White Night!",
  ui_story_5053_50531001_34_dialog_content = "Ugh—!!",
  ui_story_5053_50531001_35_dialog_content = "Yarrgh!!",
  ui_story_5053_50531001_36_dialog_content = "Putri Veronica, Nona Jakine, Apakah kamu terluka?",
  ui_story_5053_50531001_37_dialog_content = "Aku... aku baik-baik saja.",
  ui_story_5053_50531001_38_dialog_content = "Anda datang tepat pada waktunya. Saya tidak berpikir kami bisa menang tanpa Anda, Ms. Rot.",
  ui_story_5053_50531001_39_dialog_content = "Apa yang sedang terjadi di dunia ini, Yang Mulia? Penjaga ini tidak bertindak seperti pemberontak biasa.",
  ui_story_5053_50531001_40_dialog_content = "Itu karena mereka bukan pemberontak! Seluruh kekacauan ini adalah milik Joshua—",
  ui_story_5053_50531001_41_dialog_content = "Diam, pengkhianat! Syukurlah Anda datang, Ms. Rot.",
  ui_story_5053_50531001_42_dialog_content = "Para penyerang ini bersekutu dengan PlayerName Dan Jakine, bersama dengan kelompok orang luar berbahaya lainnya. Mereka bahkan berhasil mencuci otak Veronica untuk bergabung dengan mereka!",
  ui_story_5053_50531001_43_dialog_content = "Dia terlalu jauh untuk diselamatkan sekarang. Sebagai ibunya, saya sangat kecewa.",
  ui_story_5053_50531001_44_dialog_content = "Saya khawatir saya tidak punya pilihan sekarang. Nona Rot, saya perintahkan Anda untuk membuang ketiganya.",
  ui_story_5053_50531001_45_dialog_content = "...",
  ui_story_5053_50531001_46_dialog_content = "Apa yang kamu katakan, Ibu ?! Jadi PlayerName benar selama ini...",
  ui_story_5053_50531001_47_dialog_content = "Dengarkan aku, Nona Rot! \"Joshua\"di depanmu hanyalah seorang penipu! Aku masih tidak tahu persis apa yang terjadi...",
  ui_story_5053_50531001_48_dialog_content = "Tapi tolong percayalah padaku ketika aku memberitahumu bahwa dia bukan itu Joshua Anda selalu tahu!",
  ui_story_5053_50531001_49_dialog_content = "PlayerName mengatakan yang sebenarnya! Demi kehormatan saya sebagai anggota Schwartz keluarga, saya bisa membuktikannya!",
  ui_story_5053_50531001_50_dialog_content = "Anda tahu ibu saya lebih baik dari siapa pun! Bagaimana dia bisa menyuruhmu melakukan hal seperti ini?!",
  ui_story_5053_50531001_51_dialog_content = "...",
  ui_story_5053_50531001_52_dialog_content = "Mengapa Anda masih ragu-ragu? Apakah Anda lupa semua yang telah saya ajarkan kepada Anda?",
  ui_story_5053_50531001_53_dialog_content = "Seorang pembunuh harus mematuhi tuannya tanpa pertanyaan. Mereka harus siap membayar harga berapa pun untuk melaksanakan kehendak benar tuannya.",
  ui_story_5053_50531001_54_dialog_content = "Anda tidak membiarkan emosi Anda mengesampingkan rasa tanggung jawab Anda, bukan? Ingat, emosi tidak lebih dari penghalang menuju masa depan makmur Lumopolis.",
  ui_story_5053_50531001_55_dialog_content = "(Apa? Saya tidak tahu Ms. Blanc adalah murid Joshua?!)",
  ui_story_5053_50531001_56_dialog_content = "... Anda benar, Guru. Semua yang saya lakukan adalah untuk masa depan Lumopolis.",
  ui_story_5053_50531001_57_dialog_content = "Apa…?!",
  ui_story_5053_50531001_58_dialog_content = "Untuk menciptakan dunia yang lebih baik, di mana anak-anak dapat tertawa dan hidup dalam harmoni yang damai... Saya akan menghilangkan segala rintangan di jalan saya, bahkan jika rintangan itu adalah Anda.",
  ui_story_5053_50531001_59_dialog_content = "...",
  ui_story_5053_50531001_60_dialog_content = "Betapa beraninya kau mengarahkan pedangmu padaku. Saya kira saya tidak perlu terkejut.",
  ui_story_5053_50531001_61_dialog_content = "Jika ini pilihanmu, maka kamu bisa mati di sini bersama yang lainnya!",
  ui_story_5053_50531001_62_dialog_content = "<color=#e8d9bb>*klang!*</color>",
  ui_story_5053_50531001_63_dialog_content = "Urgh—!",
  ui_story_5053_50531001_64_dialog_content = "(Serangannya terlalu cepat...!)",
  ui_story_5053_50531001_65_dialog_content = "Nona Busuk?!",
  ui_story_5053_50531001_66_dialog_content = "PlayerName! Bawa Putri Veronica dan Nona Jakine, dan lari!!!",
  ui_story_5053_50531001_67_dialog_content = "Aku tidak tahu apakah aku cukup kuat untuk mengalahkannya, jadi kalian bertiga harus melarikan diri selagi bisa!",
  ui_story_5053_50531001_68_dialog_content = "T-tapi...",
  ui_story_5053_50531001_69_dialog_content = "Simpan nafasmu! Keselamatan Anda didahulukan dari hal lain, sekarang pergilah!",
  ui_story_5053_50531001_70_dialog_content = "... Saya minta maaf! Mia, Jakine, Ayo pergi dari sini!!",
  ui_story_5053_50531001_71_dialog_content = "(Harap hati-hati, Ms. Rot...!)",
  ui_story_5053_50531002_1_dialog_content = "Di sana! Apakah kita memiliki hal lain untuk memblokir pintu?",
  ui_story_5053_50531002_2_dialog_content = "Saya khawatir tidak. Kursi itu adalah satu-satunya yang tersisa.",
  ui_story_5053_50531002_3_dialog_content = "Aduh! Ini semua terlalu aneh!!",
  ui_story_5053_50531002_4_dialog_content = "Jika apa PlayerName mengatakan benar, maka kita sudah melalui ulang kedua.",
  ui_story_5053_50531002_5_dialog_content = "Semua orang berpegangan tangan untuk pertama kalinya, jadi kami mengingat semuanya. Begitulah cara saya tahu saya melakukannya dengan benar.",
  ui_story_5053_50531002_6_dialog_content = "Saya ada di sana untuk reset kedua, tetapi saya tidak menyimpan ingatan saya ...",
  ui_story_5053_50531002_7_dialog_content = "Menurut Anda mengapa itu terjadi, Jakine?",
  ui_story_5053_50531002_8_dialog_content = "... Saya pikir saya punya ide.",
  ui_story_5053_50531002_9_dialog_content = "Crystal of Eternal Memory pasti kehabisan Lumina!",
  ui_story_5053_50531002_10_dialog_content = "Apa?!",
  ui_story_5053_50531002_11_dialog_content = "Ugh... Sepertinya kita berlebihan dengan pertarungan kita melawan musuh.",
  ui_story_5053_50531002_12_dialog_content = "Dengan begitu sedikit Lumina yang tersisa, Crystal of Eternal Memory tidak dapat mempertahankan semua fungsinya.",
  ui_story_5053_50531002_13_dialog_content = "Tapi kemudian, mengapa Anda bisa menyimpan semua kenangan Anda, PlayerName?",
  ui_story_5053_50531002_14_dialog_content = "Dan sekarang ada dua Joshuas... Segalanya terus menjadi lebih gila!",
  ui_story_5053_50531002_15_dialog_content = "Mungkin Joshua dari mansion benar-benar penipu?",
  ui_story_5053_50531002_16_dialog_content = "Aku sama bingungnya denganmu, tapi ayahku masih terlalu sibuk melawan naga untuk membantu kami. Aku juga khawatir padanya...",
  ui_story_5053_50531002_17_dialog_content = "Kami tidak punya banyak pilihan saat ini. Mengapa kita tidak mencoba melakukan reset lagi?",
  ui_story_5053_50531002_18_dialog_content = "Apakah Anda keluar dari pikiran Anda ?! Jika tidak ada dari kami yang berhasil menyimpan ingatan kami, Anda harus bertarung Joshua semuanya sendiri!",
  ui_story_5053_50531002_19_dialog_content = "Dia benar. Anda tidak akan memiliki kesempatan melawan dia sendiri.",
  ui_story_5053_50531002_20_dialog_content = "Memblokir pintu dengan semua sampah ini seharusnya memberi kita waktu. Coba saya lihat apa yang ada di buku...",
  ui_story_5053_50531002_21_dialog_content = "\"Seni ramalan Northland berasal dari pemukiman Aurorian kuno...\" Aurorian Kuno, hmmm...",
  ui_story_5053_50531002_22_dialog_content = "Tunggu, itu dia! Seni ramalan dirancang dan digunakan oleh orang Aurorian, tapi PlayerName adalah Caelestite!",
  ui_story_5053_50531002_23_dialog_content = "Bisakah itu mempengaruhi ras lain secara berbeda? Lagi pula, buku itu tidak menyebutkan orang non-Aurora yang menggunakan mantera.",
  ui_story_5053_50531002_24_dialog_content = "Begitu... Mungkin itu juga menjelaskan mengapa kemampuan psikisku jauh lebih lemah juga?",
  ui_story_5053_50531002_25_dialog_content = "Mengatakan, PlayerName? Apakah Anda pernah memainkan salah satu game dari Illumina?",
  ui_story_5053_50531002_26_dialog_content = "Saat Anda memulai permainan, karakter kehilangan semua kemajuannya, tetapi pemain masih mengingat semua yang terjadi.",
  ui_story_5053_50531002_27_dialog_content = "Apakah Anda mengatakan itu di sini, saya pemainnya?",
  ui_story_5053_50531002_28_dialog_content = "Bingo! Itulah mengapa Anda tidak terikat oleh semua aturan yang sama seperti kami semua!",
  ui_story_5053_50531002_29_dialog_content = "Itu sebabnya kita perlu merencanakan semuanya dengan sempurna jika ingin mengatur ulang waktu lagi.",
  ui_story_5053_50531002_30_dialog_content = "Saya setuju. Akan terlalu berbahaya bagi Anda untuk kembali ke masa lalu tanpa persiapan.",
  ui_story_5053_50531002_31_dialog_content = "Kurasa kau benar... Kalau begitu mari kita rencanakan semuanya.",
  ui_story_5053_50531002_32_dialog_content = "Saat ini, ancaman terbesar kita adalah Joshua.",
  ui_story_5053_50531002_33_dialog_content = "Adapun mengapa tiba-tiba ada dua, saya masih belum sepenuhnya yakin.",
  ui_story_5053_50531002_34_dialog_content = "Terlalu membingungkan untuk menyebut mereka berdua sebagai Joshua, karena salah satunya adalah Gelap Angel...",
  ui_story_5053_50531002_35_dialog_content = "Kita bisa memanggil yang lain Setan Putih!",
  ui_story_5053_50531002_37_dialog_content = "Iblis Putih... Aku tidak ingin memanggil Ibu dengan nama itu, tapi itu adalah cara yang pas untuk menggambarkannya seperti sekarang ini.",
  ui_story_5053_50531002_38_dialog_content = "Dilihat dari perilaku dan pengetahuan Iblis Putih, aman untuk berasumsi bahwa dia bukan penipu.",
  ui_story_5053_50531002_39_dialog_content = "Ketika Benih ditanam di inang yang hidup, itu menciptakan kepribadian ganda... Berdasarkan pengalaman saya sendiri, saya dapat memahami situasinya.",
  ui_story_5053_50531002_40_dialog_content = "Dan seperti Baba Yaga dan saya sendiri, tidak ada cara untuk menentukan siapa di antara kami yang baik atau buruk.",
  ui_story_5053_50531002_41_dialog_content = "Tindakannya terkadang ekstrem, tapi itu tidak membuat Baba Yaga jahat. PlayerName tahu itu juga.",
  ui_story_5053_50531002_42_dialog_content = "Apakah mungkin bahwa Dark Angel dan Setan Putih itu sama?",
  ui_story_5053_50531002_43_dialog_content = "Terlepas dari perilakunya yang menakutkan, Dark Angel memang menyelamatkan kami kembali di alun-alun.",
  ui_story_5053_50531002_44_dialog_content = "Mungkin dia hanya kesulitan mengendalikan dirinya sendiri?",
  ui_story_5053_50531002_45_dialog_content = "Yah, meskipun dia memiliki beberapa sifat yang sama dengan Baba Yaga, menurutku kau dan Iblis Putih tidak sama, Mia.",
  ui_story_5053_50531002_46_dialog_content = "Dia hanyalah seorang pembunuh yang berhati dingin dan kejam. Apakah Anda mengatakan Nyonya Joshua punya sisi seperti ini?",
  ui_story_5053_50531002_47_dialog_content = "Saya juga tidak mengerti. Ibu selalu orang yang baik dan lembut... Saya tidak pernah melihat sedikit pun kejahatan dalam dirinya.",
  ui_story_5053_50531002_48_dialog_content = "Eh, mungkin saya bisa menambahkan ceritanya di sini.",
  ui_story_5053_50531002_49_dialog_content = "Dia dulunya adalah seorang pembunuh. Aku mendengarnya langsung dari mulutnya beberapa waktu lalu...",
  ui_story_5053_50531002_50_dialog_content = "Bertahun-tahun yang lalu, keluarga saya menolak untuk tunduk pada House Schwartz dan pemerintahannya yang lalim. Akibatnya, keluarga saya diberantas oleh ayah Daniel, Penguasa Kota sebelumnya.",
  ui_story_5053_50531002_51_dialog_content = "Banyak keluarga lain berbagi nasib kami juga. Hanya sedikit dari kami yang selamat dan saat itu aku masih anak-anak.",
  ui_story_5053_50531002_52_dialog_content = "Kami semua datang untuk membenci House Schwartz, dan kami bersumpah untuk membalas dendam pada setiap orang dari mereka.",
  ui_story_5053_50531002_53_dialog_content = "Akhirnya, saya menemukan jalan ke Taman Lumopolis. Keluarga bangsawan yang berduka yang kehilangan putri mereka karena tirani Schwartz menerima saya sebagai salah satu dari mereka.",
  ui_story_5053_50531002_54_dialog_content = "Apa...? T-Tapi bagaimana bisa?! D-Dia adalah istri Lord Schwartz!!",
  ui_story_5053_50531002_55_dialog_content = "Tidakkah menurutmu dia mungkin berbohong?",
  ui_story_5053_50531002_56_dialog_content = "Saya juga sulit membayangkannya...",
  ui_story_5053_50531002_57_dialog_content = "...",
  ui_story_5053_50531002_58_dialog_content = "Anda tidak percaya itu, kan Mia?!",
  ui_story_5053_50531002_59_dialog_content = "Sebenarnya... Akan sangat masuk akal jika dia mengatakan yang sebenarnya.",
  ui_story_5053_50531002_60_dialog_content = "Selain sebagai ibu yang baik dan penyayang, dia juga orang yang sangat kuat.",
  ui_story_5053_50531002_61_dialog_content = "Terlepas dari statusnya yang tinggi sebagai istri penguasa kota, dia tidak pernah melupakan moralnya. Dia mendekati segala sesuatu dengan pikiran rasional dan hati yang lembut ...",
  ui_story_5053_50531002_62_dialog_content = "Dalam kehidupan pribadi kami, dia merawat kami semua, termasuk ayah saya. Di depan umum, dia adalah pasangan yang sempurna bagi penguasa kota Lumopolis.",
  ui_story_5053_50531002_63_dialog_content = "Dia tidak pernah termotivasi oleh kekayaan atau kekuasaan. Bahkan dalam situasi yang paling mengerikan, dia akan selalu mengorbankan kepentingannya demi orang lain.",
  ui_story_5053_50531002_64_dialog_content = "Itu bukanlah sesuatu yang bisa dilakukan oleh wanita bangsawan mana pun.",
  ui_story_5053_50531002_65_dialog_content = "Masa lalu yang kejam dan tragis, diikuti oleh pengorbanan dirinya seumur hidup dan menekan kebutuhannya sendiri, sementara tidak ada yang memahaminya ...",
  ui_story_5053_50531002_66_dialog_content = "Penderitaan ibu saya sejuta kali lebih menyakitkan daripada saya.",
  ui_story_5053_50531002_67_dialog_content = "Saya tidak akan menyalahkannya jika Setan Putih ini adalah manifestasi dari kebenciannya.",
  ui_story_5053_50531002_68_dialog_content = "Oh, begitu…",
  ui_story_5053_50531002_69_dialog_content = "Wanita Joshua... Sungguh keberadaan yang luar biasa namun tragis.",
  ui_story_5053_50531002_70_dialog_content = "Tetapi jika teori kami benar, mengapa Baba Yaga dan saya tidak berpisah juga?",
  ui_story_5053_50531002_71_dialog_content = "Anda benar, dan itu perbedaan besar antara Anda dan Nona Joshua.",
  ui_story_5053_50531002_72_dialog_content = "Baba Yaga adalah temanmu, Mia. Dia selalu berusaha melindungimu.",
  ui_story_5053_50531002_73_dialog_content = "Mungkin saja dia tidak ingin melepaskan diri dari Anda. Itu akan menjelaskan mengapa kita tidak melihatnya sejak memasuki dunia Crystal.",
  ui_story_5053_50531002_74_dialog_content = "Joshua, di sisi lain, justru sebaliknya. Kedua bagiannya benar-benar bertentangan satu sama lain.",
  ui_story_5053_50531002_75_dialog_content = "K-Kamu pikir begitu? Saya lega mendengarnya... Selama ini, saya pikir dia hanya marah karena saya mengganti pakaian saya tanpa berkonsultasi dengannya.",
  ui_story_5053_50531002_76_dialog_content = "Baba Yaga... Saat kita kembali, aku harus berterima kasih padanya karena perhatiannya...",
  ui_story_5053_50531002_77_dialog_content = "Mari kita kembali ke apa yang dikatakan Iblis Putih tadi.",
  ui_story_5053_50531002_78_dialog_content = "Menurutnya, satu-satunya cara untuk melarikan diri tanpa menyakiti siapa pun... Adalah dengan membawa mereka berdua bersama kita.",
  ui_story_5053_50531002_79_dialog_content = "Anda tidak berpikir dia berbohong ketika dia mengatakan itu, kan...?",
  ui_story_5053_50531002_80_dialog_content = "Saya kira tidak demikian. Bagaimanapun, itu sesuai dengan apa yang terjadi selama reset terakhir.",
  ui_story_5053_50531002_81_dialog_content = "Masalahnya adalah, kita tidak tahu apakah dia masih memiliki sesuatu di lengan bajunya atau tidak...",
  ui_story_5053_50531002_82_dialog_content = "...",
  ui_story_5053_50531002_83_dialog_content = "Mia?",
  ui_story_5053_50531002_84_dialog_content = "Maaf, aku hanya ingin tahu seperti apa Ibu nanti setelah kita kembali ke dunia nyata...",
  ui_story_5053_50531002_85_dialog_content = "Apakah dia akan terus menderita seperti sebelumnya? Atau lebih buruk... Apakah dia akan berubah menjadi Eclipsite?",
  ui_story_5053_50531002_86_dialog_content = "Saya... Saya pikir kita harus mencoba untuk tetap optimis untuk saat ini.",
  ui_story_5053_50531002_87_dialog_content = "Apapun yang terjadi, kita semua akan ada untuk membantu. Yang mulia Schwartz, Kaleb, Jakine... dan aku juga.",
  ui_story_5053_50531002_88_dialog_content = "Dengan kekuatan gabungan kita, kita harus mampu menangani apa pun yang menghadang kita.",
  ui_story_5053_50531002_89_dialog_content = "Tapi tidak ada yang akan berubah kecuali kita keluar dari sini dulu!",
  ui_story_5053_50531002_90_dialog_content = "... Anda benar sekali!",
  ui_story_5053_50531002_91_dialog_content = "Membuat mereka berdua keluar pada saat yang sama tidak akan mudah. Saya ragu Setan Putih akan datang dengan tenang.",
  ui_story_5053_50531002_92_dialog_content = "Dia juga membuatnya sangat jelas bahwa dia membenci dirinya yang lain dan menolak untuk menjadi satu dengan dia lagi...",
  ui_story_5053_50531002_93_dialog_content = "Benar, itulah sebabnya dia berencana membunuh kita semua.",
  ui_story_5053_50531002_94_dialog_content = "Satu-satunya pilihan kita adalah menaklukkannya dengan paksa dan membawanya bersama kita.",
  ui_story_5053_50531002_95_dialog_content = "Tapi dengan semua penjaga ceroboh dan seekor naga di jalan...",
  ui_story_5053_50531002_96_dialog_content = "Apakah buku itu mengatakan sesuatu tentang mengapa mereka bertingkah sangat aneh, Jakine?",
  ui_story_5053_50531002_97_dialog_content = "Coba saya lihat... Ada! \"Siapa pun yang pertama kali mengaktifkan Crystal of Eternal Memory memiliki kekuatan untuk mengubah jalannya peristiwa sampai tingkat tertentu.\"",
  ui_story_5053_50531002_98_dialog_content = "... Tunggu, apakah itu? Argh, tidak bisakah Ibu menjelaskan sedikit lagi, Bu?!",
  ui_story_5053_50531002_99_dialog_content = "Sepertinya kita harus menemukan jawabannya sendiri. Hmmm...",
  ui_story_5053_50531002_100_dialog_content = "Dunia di dalam Crystal of Eternal Memory diciptakan dan dipertahankan oleh <color=#FFB400>Air Danau Cermin</color> Dan <color=#FFB400>Lumina siapa pun yang mengaktifkannya</color>.",
  ui_story_5053_50531002_101_dialog_content = "<color=#FFB400>Lumina aktivator</color>... Dengan kata lain, Lumina-nya Joshua! Seluruh dunia ilusi ini adalah produk dari Lumina-nya sendiri.",
  ui_story_5053_50531002_102_dialog_content = "Dia menyebutkan bahwa kekuatannya telah terbelah, kan?!",
  ui_story_5053_50531002_103_dialog_content = "Oke…",
  ui_story_5053_50531002_104_dialog_content = "Dia juga mengatakan bahwa dia perlu menyerap Lumina kita untuk menjadi dirinya sendiri!",
  ui_story_5053_50531002_105_dialog_content = "Itu benar! Apakah kamu tidak melihat?!",
  ui_story_5053_50531002_106_dialog_content = "Ketika Gelap Angel memisahkan diri dari Iblis Putih, dia mengambil setengah dari kekuatannya bersamanya!",
  ui_story_5053_50531002_107_dialog_content = "Adapun setengah lainnya, saya tidak berpikir dia kehilangan itu sama sekali! Saya pikir dia menggunakannya untuk memanipulasi Crystal of Eternal Memory!",
  ui_story_5053_50531002_108_dialog_content = "Lagi pula, naga dan para penjaga adalah produk Lumina milik Joshua.",
  ui_story_5053_50531002_109_dialog_content = "Itu berarti dia satu-satunya yang mampu mengganggu mereka... Atau, dalam hal ini, menginfeksi mereka!",
  ui_story_5053_50531002_110_dialog_content = "Kalau begitu, Iblis Putih sudah membohongi kita sejak awal!",
  ui_story_5053_50531002_111_dialog_content = "Apakah itu benar-benar mungkin?! Lalu Bu Rot...",
  ui_story_5053_50531002_112_dialog_content = "... Mungkin dalam banyak bahaya sekarang.",
  ui_story_5053_50531002_113_dialog_content = "Ini menakutkan, dia bisa begitu kejam dan penuh perhitungan...",
  ui_story_5053_50531002_114_dialog_content = "Aku tidak pernah takut pada Ibu, tapi tanpa sisi hangat dan lembutnya...",
  ui_story_5053_50531002_115_dialog_content = "Apakah dia benar-benar akan menjadi orang yang seperti ini?",
  ui_story_5053_50531002_116_dialog_content = "Jadi naga dan gerombolan orang gila kemungkinan besar adalah bidak Iblis Putih. Mengalahkan mereka harus mengurangi kekuatannya.",
  ui_story_5053_50531002_117_dialog_content = "Selain itu, apa kita punya cara lain untuk melawannya—tunggu!",
  ui_story_5053_50531002_118_dialog_content = "Kegelapan Angel! Dia damai bagi Tuhan Schwartz dan anggota keluarganya yang lain, dan Iblis Putih tidak dapat membunuhnya sendirian!",
  ui_story_5053_50531002_119_dialog_content = "Jika kita bisa meyakinkannya untuk bertarung di pihak kita, kita akan memiliki peluang menang yang jauh lebih tinggi!",
  ui_story_5053_50531002_120_dialog_content = "Itu salah satu skema bodoh yang Anda dapatkan di sana! Saya selalu tahu Anda memiliki sisi sembrono!",
  ui_story_5053_50531002_121_dialog_content = "Tapi saya harus memperingatkan Anda, PlayerName...",
  ui_story_5053_50531002_122_dialog_content = "Crystal of Eternal Memory hanya memiliki Lumina yang tersisa untuk satu reset terakhir.",
  ui_story_5053_50531002_123_dialog_content = "Itu berarti kegagalan bukanlah pilihan. Anda harus berhasil, atau kita semua selesai!",
  ui_story_5053_50531002_124_dialog_content = "Aku harus berhasil... Mengerti...",
  ui_story_5053_50531002_125_dialog_content = "PlayerName? Setelah reset terakhir, bagaimana jika Anda langsung pergi ke White Demon dan langsung mengeksposnya?",
  ui_story_5053_50531002_126_dialog_content = "Whoa... Itu bahkan lebih liar dari PlayerNameide! Kesanku padamu telah banyak berubah sejak kita tiba di sini, Mia.",
  ui_story_5053_50531002_127_dialog_content = "B-benarkah?",
  ui_story_5053_50531002_128_dialog_content = "Itu akan sangat berisiko, tidak diragukan lagi.",
  ui_story_5053_50531002_129_dialog_content = "Saya tidak punya cara untuk membela diri. Setan Putih tidak akan kesulitan menyingkirkanku.",
  ui_story_5053_50531002_130_dialog_content = "Tak satu pun dari Anda akan memiliki ingatan Anda juga, jadi Anda mungkin tidak langsung percaya tuduhan saya.",
  ui_story_5053_50531002_131_dialog_content = "Anda benar... Paman Caleb akan mengalami kesulitan untuk memercayai kesaksian Anda.",
  ui_story_5053_50531002_132_dialog_content = "Tapi jujur saja, PlayerName, Saya pikir Anda tidak perlu terlalu khawatir tentang ini.",
  ui_story_5053_50531002_133_dialog_content = "Ayah saya sangat perseptif. Dia memiliki kecurigaan tentang Iblis Putih sejak pertama kali kami bertemu dengannya kali ini.",
  ui_story_5053_50531002_134_dialog_content = "Saya pikir dia meminta Paman Caleb untuk tetap tinggal sehingga dia bisa melihat kebenaran dengan matanya sendiri...",
  ui_story_5053_50531002_135_dialog_content = "Itu sebabnya Anda harus memusatkan perhatian Anda pada Kegelapan Angel alih-alih.",
  ui_story_5053_50531002_136_dialog_content = "Kedengarannya seperti Tuhan Schwartz...",
  ui_story_5053_50531002_137_dialog_content = "<color=#e8d9bb>Brak! Brak! Brak!</color>",
  ui_story_5053_50531002_138_dialog_content = "A-Apa itu tadi?!",
  ui_story_5053_50531002_139_dialog_content = "Oh tidak, para penjaga menyusul!",
  ui_story_5053_50531002_140_dialog_content = "Aku akan menahan mereka! Jakine, bersiaplah untuk melakukan reset terakhir...",
  ui_story_5053_50531002_141_dialog_content = "<color=#e8d9bb>Duar!!!</color>",
  ui_story_5053_50531002_142_dialog_content = "Awas, Mia!",
  ui_story_5053_50531002_143_dialog_content = "Apakah itu...?!",
  ui_story_5053_50531002_144_dialog_content = "...",
  ui_story_5053_50531002_145_dialog_content = "Nona Busuk?!",
  ui_story_5053_50531002_146_dialog_content = "Kembali, Mia!",
  ui_story_5053_50531002_147_dialog_content = "...Tidak.",
  ui_story_5053_50531002_148_dialog_content = "Anda pasti sangat kesakitan sekarang, Ms. Rot... Sama seperti Carleen, ketika dia berjuang sampai akhir untuk menjaga kewarasannya.",
  ui_story_5053_50531002_149_dialog_content = "... Aku tidak akan membiarkan hal itu terjadi lagi. Aku tidak akan membiarkanmu menderita di jalan Carleen menderita.",
  ui_story_5053_50531002_150_dialog_content = "Aku akan membebaskanmu dari rasa sakitmu!",
  ui_story_5053_50531002_151_dialog_content = "Datang kepadaku!",
  ui_story_5053_50531002_152_dialog_content = "—!",
  ui_story_5053_50531002_153_dialog_content = "Mia...",
  ui_story_5053_50531002_154_dialog_content = "Dia berjuang sekuat tenaga untuk membelikan kita waktu, Jakine... Mari kita mulai mengatur ulang.",
  ui_story_5053_50531002_155_dialog_content = "Begitu saya bangun, saya hanya perlu menemukan Kegelapan Angel, lalu bersembunyi dari para penjaga itu, lalu...",
  ui_story_5053_50531002_156_dialog_content = "PlayerName? Tanganmu gemetar...",
  ui_story_5053_50531002_157_dialog_content = "...",
  ui_story_5053_50531002_158_dialog_content = "Aku tahu kami menempatkan banyak hal di pundakmu sekarang. Aku akan gugup jika aku harus melakukan semuanya sendiri juga, tapi jangan takut.",
  ui_story_5053_50531002_159_dialog_content = "Semuanya akan baik-baik saja. Kami percaya Anda, apa pun yang terjadi!",
  ui_story_5053_50531002_160_dialog_content = "Jakine...!",
  ui_story_5053_50531002_161_dialog_content = "Benar! Serahkan saja padaku!",
  ui_story_5053_50531002_162_dialog_content = "Reditus, reditus, reditus! Biarkan semuanya kembali seperti semula!",
  ui_story_5053_50531002_163_dialog_content = "Omong kosong!",
  ui_story_5053_50531101_0X_dialog_content = "<color=#e8d9bb>Setelah reset ketiga—</color>",
  ui_story_5053_50531101_1_dialog_content = "Semuanya sudah diatur, tuanku.",
  ui_story_5053_50531101_2_dialog_content = "Gerbong menunggu di luar dan siap berangkat kapan saja.",
  ui_story_5053_50531101_3_dialog_content = "Aku mengerti.",
  ui_story_5053_50531101_4_dialog_content = "Masuk gerbong, Carleen.",
  ui_story_5053_50531101_5_dialog_content = "Aku... Aku ingin tinggal bersama Ibu!",
  ui_story_5053_50531101_6_dialog_content = "Jakine... Mia... Saya harus...",
  ui_story_5053_50531101_7_dialog_content = "Hmm...dimana aku...?",
  ui_story_5053_50531101_8_dialog_content = "Itu benar, Jakine mengirim saya kembali dalam waktu lagi!",
  ui_story_5053_50531101_9_dialog_content = "Dan di sana... Diri Lord Schwartz yang lebih muda sedang mengawal Carleen keluar dari sini.",
  ui_story_5053_50531101_10_dialog_content = "Sepertinya reset berhasil!",
  ui_story_5053_50531101_11_dialog_content = "Baiklah, hal pertama yang pertama ...",
  ui_story_5053_50531101_12_dialog_content = "Orang yang mencurigakan... harus dimusnahkan...",
  ui_story_5053_50531101_13_dialog_content = "Orang yang mencurigakan... tidak di sini...",
  ui_story_5053_50531101_14_dialog_content = "Fiuh, aku berhasil menghindari para penjaga! Itu mengurus itu!",
  ui_story_5053_50531101_15_dialog_content = "(Sebelum penyetelan ulang, kami bertiga menyusun rencana tiga langkah untuk mengeluarkan kami dari sini.)",
  ui_story_5053_50531101_16_dialog_content = "(Pertama, temukan Kegelapan Angel dan yakinkan dia untuk bertarung di pihak kita.)",
  ui_story_5053_50531101_17_dialog_content = "(Dan kemudian, cegah naga dan penjaga yang terinfeksi meluncurkan serangan mereka.)",
  ui_story_5053_50531101_18_dialog_content = "(Terakhir, kalahkan White Demon sebelum orang lain terluka atau lebih buruk.)",
  ui_story_5053_50531101_19_dialog_content = "(Mia, Jakine...)",
  ui_story_5053_50531101_20_dialog_content = "(Ini adalah pengaturan ulang terakhir kami. Saya harus melakukan ini, atau kita semua akan mati.)",
  ui_story_5053_50531101_21_dialog_content = "Orang yang mencurigakan... basmi...",
  ui_story_5053_50531101_22_dialog_content = "!!!",
  ui_story_5053_50531101_23_dialog_content = "Tidak disini...",
  ui_story_5053_50531101_24_dialog_content = "(Hampir saja... Berdasarkan beberapa pertikaian terakhirku dengan para penjaga ini, mereka tidak akan berhenti mengejarku sampai akhir.)",
  ui_story_5053_50531101_25_dialog_content = "(Saya kekurangan waktu, kekuatan tempur, dan mobilitas ... Yang berarti saya harus menyelesaikan ketiga langkah sekaligus.)",
  ui_story_5053_50531101_26_dialog_content = "(Saya hanya punya satu kesempatan untuk ini!)",
  ui_story_5053_50531102_1_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_5053_50531102_2_dialog_content = "Urgh... Batuk, batuk...",
  ui_story_5053_50531102_3_dialog_content = "Dimana Dark Angel pergi?",
  ui_story_5053_50531102_4_dialog_content = "Sepertinya dia melarikan diri melalui jalur luar.",
  ui_story_5053_50531102_5_dialog_content = "Itu luar biasa, Tuhan Schwartz!",
  ui_story_5053_50531102_6_dialog_content = "Aku hanya bersyukur tidak ada yang terluka—",
  ui_story_5053_50531102_7_dialog_content = "Oh, kalian semua!",
  ui_story_5053_50531102_8_dialog_content = "Ibu... Apa yang kamu lakukan di sini? Bukankah seharusnya kau menonton pawai?",
  ui_story_5053_50531102_9_dialog_content = "...",
  ui_story_5053_50531102_10_dialog_content = "... Sepertinya kita kedatangan tamu tak diundang.",
  ui_story_5053_50531102_11_dialog_content = "Apakah semua orang baik-baik saja?",
  ui_story_5053_50531102_12_dialog_content = "Joshua? T-Tapi Gelap Angel baru saja...",
  ui_story_5053_50531102_13_dialog_content = "Heheh, jadi si jenius kecilku juga mengalami kebingungan.",
  ui_story_5053_50531102_14_dialog_content = "Anda semua pasti lelah dari pertempuran Anda. Masuklah dan istirahat, bukan?",
  ui_story_5053_50531102_15_dialog_content = "Jangan khawatir tentang monster itu. Aku akan mengirim pengawalku untuk memburunya sebentar.",
  ui_story_5053_50531102_16_dialog_content = "Ibu, tunggu sebentar, sepertinya ada yang tidak beres...",
  ui_story_5053_50531102_17_dialog_content = "Apakah ada yang melihat PlayerName?",
  ui_story_5053_50531102_18_dialog_content = "Oh ya! Dimana PlayerName? Saya tidak melihatnya di mana pun.",
  ui_story_5053_50531102_19_dialog_content = "Dia telah hilang sepanjang waktu.",
  ui_story_5053_50531102_20_dialog_content = "Apa...",
  ui_story_5053_50531102_21_dialog_content = "Maafkan aku, Ibu. Kita harus pergi mencari PlayerName sebelum dia menghadapi bahaya...",
  ui_story_5053_50531102_22_dialog_content = "Sungguh menghangatkan hati saya melihat betapa Anda peduli pada teman Anda, Vonnie... Tapi saya memiliki sesuatu yang sangat penting untuk dibagikan kepada semua orang.",
  ui_story_5053_50531102_23_dialog_content = "Saya akan mengirim tim penjaga untuk mencari PlayerName. Mari kita masuk ke dalam sekarang, oke?",
  ui_story_5053_50531102_24_dialog_content = "Hah? Um... O-Oke...",
  ui_story_5053_50531102_25_dialog_content = "... Itu saja?",
  ui_story_5053_50531102_26_dialog_content = "Sama sekali tidak seperti Anda berbicara tentang keadaan hidup atau mati seseorang dengan begitu acuh tak acuh.",
  ui_story_5053_50531102_27_dialog_content = "Oh? Apakah itu yang Anda pikirkan tentang saya? Wanita bangsawan biasa yang lemah? DANIEL.",
  ui_story_5053_50531102_28_dialog_content = "...",
  ui_story_5053_50531102_29_dialog_content = "Daniel? Tetapi Joshua, bagaimana Anda—mungkinkah itu?!",
  ui_story_5053_50531201_1_dialog_content = "Heh, heh...",
  ui_story_5053_50531201_2_dialog_content = "Aku tahu aku melihatnya lewat sini, tapi kenapa aku tidak bisa menemukannya?",
  ui_story_5053_50531201_3_dialog_content = "Sch... wartz...",
  ui_story_5053_50531201_4_dialog_content = "Di sana! Di balik peti itu!",
  ui_story_5053_50531201_5_dialog_content = "...!!!",
  ui_story_5053_50531201_6_dialog_content = "Tunggu, aku tidak ingin melawanmu! Caleb dan Veronica dalam bahaya, dan mereka butuh bantuanmu!",
  ui_story_5053_50531201_7_dialog_content = "Ca... Kaleb...? Veronica...?",
  ui_story_5053_50531201_8_dialog_content = "Itu benar! Kakakmu Caleb, dan putrimu Veronica!",
  ui_story_5053_50531201_9_dialog_content = "Mereka keluargamu, bukan?",
  ui_story_5053_50531201_10_dialog_content = "Keluarga saya...",
  ui_story_5053_50531201_11_dialog_content = "Ya, keluargamu! Dan mereka dalam bahaya serius sekarang!",
  ui_story_5053_50531201_12_dialog_content = "Keluargaku... dalam bahaya...",
  ui_story_5053_50531201_13_dialog_content = "Apakah ada yang salah...?",
  ui_story_5053_50531201_14_dialog_content = "<size=50>Keluarga saya... Schwartz!!!</size>",
  ui_story_5053_50531201_15_dialog_content = "H-Hah?! Hei, pertahankan! Anda akan memberi tahu para penjaga!",
  ui_story_5053_50531201_16_dialog_content = "(Ketika kami mengatakan Caleb dalam bahaya terakhir kali, dia bersedia membantu kami. Kenapa dia marah kali ini?!)",
  ui_story_5053_50531201_17_dialog_content = "(Apakah mungkin Dark Angel hanya akan mendengarkan Mia atau orang lain dari keluarganya?)",
  ui_story_5053_50531201_18_dialog_content = "Nyeri...! Sakit sekali...!",
  ui_story_5053_50531201_19_dialog_content = "Ah, ini tidak bagus... Aku kehabisan waktu! Apa yang harus saya lakukan?!",
  ui_story_5053_50531201_20_dialog_content = "Jangan menangis...",
  ui_story_5053_50531201_21_dialog_content = "Jangan menangis... Manisku, kecil... Vonnie...",
  ui_story_5053_50531201_22_dialog_content = "Segalanya akan baik-baik saja...",
  ui_story_5053_50531201_23_dialog_content = "Ah...",
  ui_story_5053_50531201_24_dialog_content = "(Aku perlu menenangkannya entah bagaimana. Jadi, cara yang dilakukan Aurorian untuk saling menghibur... satu hal yang berarti kedamaian dan keamanan bagi Dark Angel...)",
  ui_story_5053_50531201_25_dialog_content = "(Ini satu-satunya kesempatan saya!)",
  ui_story_5053_50531201_26_dialog_content = "Petik mawar... Hanya untuk bayiku? ♪",
  ui_story_5053_50531201_27_dialog_content = "Sesuatu, sesuatu... Hanya angin di wajahmu yang kubutuhkan? ♪",
  ui_story_5053_50531201_28_dialog_content = "…?",
  ui_story_5053_50531201_29_dialog_content = "...",
  ui_story_5053_50531201_30_dialog_content = "Pilih mawar...? Untuk ayah dan ibuku tersayang... ♪",
  ui_story_5053_50531201_31_dialog_content = "Diam.",
  ui_story_5053_50531201_32_dialog_content = "Saya minta maaf jika nyanyian saya jelek.",
  ui_story_5053_50531201_33_dialog_content = "Saya mendengar lagu ini di jalan dari waktu ke waktu. Ini menarik, tapi saya tidak pernah bisa mengingat kata-katanya.",
  ui_story_5053_50531201_34_dialog_content = "Melodi juga sering luput dari perhatian saya.",
  ui_story_5053_50531201_35_dialog_content = "Seorang anggota DPR Schwartz tidak berhak menyanyikan lagu Lumopolis Bawah.",
  ui_story_5053_50531201_36_dialog_content = "... Mengapa Anda membenci House Schwartz banyak?",
  ui_story_5053_50531201_37_dialog_content = "Kebencian itu bahkan memaksamu untuk menutupi dan mengorbankan dirimu untuk mendekatiku, menjadi kekasihku.",
  ui_story_5053_50531201_38_dialog_content = "Semua ini, hanya agar kau bisa membunuh ayahku.",
  ui_story_5053_50531201_39_dialog_content = "...",
  ui_story_5053_50531201_40_dialog_content = "Tindakan Anda sempurna, dan keahlian Anda dalam pertempuran dan akademisi tidak ada duanya.",
  ui_story_5053_50531201_41_dialog_content = "Katakan padaku, berapa lama waktu yang dibutuhkan untuk mengasah kemampuan ini?",
  ui_story_5053_50531201_42_dialog_content = "Lima tahun? Sepuluh tahun? Atau mungkin... seumur hidup Anda?",
  ui_story_5053_50531201_43_dialog_content = "Semua pelatihan dan persiapan hanya untuk melakukan satu pembunuhan profil tinggi.",
  ui_story_5053_50531201_44_dialog_content = "Apakah hidup ayahku benar-benar layak untuk kebencian di hatimu dan di hati para komplotanmu?",
  ui_story_5053_50531201_45_dialog_content = "Sebelum Anda sampai pada kesimpulan yang salah, izinkan saya menjelaskan satu hal.",
  ui_story_5053_50531201_46_dialog_content = "Aku mengatakan hal-hal ini, bukan hanya untuk membela kehormatan ayahku... Tapi karena aku tidak ingin melihatmu termakan oleh kebencian.",
  ui_story_5053_50531201_47_dialog_content = "Rumah Schwartz adalah perwujudan dari penindasan dan tirani.",
  ui_story_5053_50531201_48_dialog_content = "Semua makanan yang Anda miliki, dan semua pakaian yang Anda kenakan berlumuran darah korban Anda.",
  ui_story_5053_50531201_49_dialog_content = "Korban, katamu. Apakah mereka termasuk adik kandung Caleb dan juga keluarga aslimu?",
  ui_story_5053_50531201_50_dialog_content = "...",
  ui_story_5053_50531201_51_dialog_content = "Ini hanya spekulasi di pihak saya, setidaknya untuk saat ini.",
  ui_story_5053_50531201_52_dialog_content = "Tujuh tahun lalu, ibu Caleb secara tragis dan tidak sengaja terbunuh dalam operasi antipemberontakan.",
  ui_story_5053_50531201_53_dialog_content = "saudara perempuannya, Joshua, juga hadir selama penyerangan.",
  ui_story_5053_50531201_54_dialog_content = "Namun entah bagaimana, seolah-olah dengan keajaiban, dia muncul sebagai satu-satunya yang selamat dari operasi tersebut... Tapi itu bukan keajaiban, bukan?",
  ui_story_5053_50531201_55_dialog_content = "Baru kemudian, yang sama sekali baru \"Joshua\"seperti dirimu bisa muncul. Apakah sejauh ini aku salah?",
  ui_story_5053_50531201_56_dialog_content = "...",
  ui_story_5053_50531201_57_dialog_content = "Saya tidak pernah berbagi kecurigaan saya dengan siapa pun, saya juga tidak memberi tahu siapa pun tentang kehadiran Anda di sini.",
  ui_story_5053_50531201_58_dialog_content = "Semua orang menganggap Anda baru saja pulang. Aku bahkan mengatakan sebanyak itu kepada ayah angkatmu.",
  ui_story_5053_50531201_59_dialog_content = "Tapi nyatanya, kamu tidak pernah kembali. Ayah angkatmu juga tidak pernah menyebutkan tentang kepergianmu.",
  ui_story_5053_50531201_60_dialog_content = "Jelas, dia tahu mengapa kamu hilang.",
  ui_story_5053_50531201_61_dialog_content = "...",
  ui_story_5053_50531201_62_dialog_content = "Namun, alih-alih menghindari subjek, dia mendekati saya selama kelas dan bertanya bagaimana kabar kami akhir-akhir ini.",
  ui_story_5053_50531201_63_dialog_content = "Merencanakan kematian penguasanya adalah kejahatan yang dapat dihukum dengan kematian yang paling mengerikan, namun pada saat itu, dia lebih mementingkan keselamatan Anda daripada keselamatannya sendiri.",
  ui_story_5053_50531201_64_dialog_content = "Alih-alih memilih ketakutan atau kebencian, cendekiawan tua yang baik hati itu memilih Anda.",
  ui_story_5053_50531201_65_dialog_content = "Jadi, tolong... Demi dia, tolong hentikan rencanamu untuk membunuh ayahku.",
  ui_story_5053_50531201_66_dialog_content = "Jika Anda melakukannya, saya berjanji untuk bersikap seolah-olah tidak terjadi apa-apa dan mengembalikan Anda ke keluarga Anda.",
  ui_story_5053_50531201_67_dialog_content = "Luangkan aku sandiwara, Schwartz. Saya tidak akan mendengarkan, dan jika dia ada di sini sekarang... Dia juga tidak akan mendengarkan.",
  ui_story_5053_50531201_68_dialog_content = "Kami terikat oleh kebencian timbal balik kami terhadap House Schwartz. Mengorbankan diri kita untuk mengejar ambisi kita adalah kehormatan tertinggi.",
  ui_story_5053_50531201_69_dialog_content = "Hmm? Bukankah saya mengatakan bahwa saya hanya membuat dugaan? Saya tidak pernah punya bukti untuk membuktikan klaim saya.",
  ui_story_5053_50531201_70_dialog_content = "Tapi sekarang kau telah mengaku bersekongkol melawan House Schwartz dengan ayah Caleb...",
  ui_story_5053_50531201_71_dialog_content = "Hahaha, sepertinya ronde ini milikku, Joshua!",
  ui_story_5053_50531201_72_dialog_content = "...",
  ui_story_5053_50531201_73_dialog_content = "Ahem, maafkan saya untuk sedikit sombong itu. Aku hanya ingin sedikit mencairkan suasana...",
  ui_story_5053_50531201_74_dialog_content = "Bagaimanapun, saya dapat memahami ketidakpercayaan Anda.",
  ui_story_5053_50531201_75_dialog_content = "Ayah saya selalu menjadi pria yang kejam dan teguh. Ketika datang untuk membungkam musuh-musuhnya... Dia akan melakukannya tanpa pandang bulu, daripada membiarkan satu orang pun melarikan diri.",
  ui_story_5053_50531201_76_dialog_content = "Dia mengklaim tindakannya diperlukan untuk membangun front persatuan.",
  ui_story_5053_50531201_77_dialog_content = "Semua harus menghormati House Schwartz, dan semua harus mematuhi satu penguasa.",
  ui_story_5053_50531201_78_dialog_content = "Ketika setiap warga setia kepada satu pemimpin yang dapat dipercaya, orang yang tamak dan jahat tidak akan punya tempat untuk bersembunyi.",
  ui_story_5053_50531201_79_dialog_content = "Dan begitu kotoran mereka dibersihkan dari kota, Lumopolis akan bersinar di atas dunia sebagai utopia yang murni dan sempurna.",
  ui_story_5053_50531201_80_dialog_content = "Visi ayah tentang masa depan sama besarnya dengan idealnya. Saya semakin menghormatinya untuk itu.",
  ui_story_5053_50531201_81_dialog_content = "Namun... dasar utopia ayahku masih diletakkan, dan tidak semua orang memiliki visi yang sama.",
  ui_story_5053_50531201_82_dialog_content = "Katakan padaku, apakah kamu memperhatikan ekspresi wajah semua orang saat pertama kali tiba di rumahku?",
  ui_story_5053_50531201_83_dialog_content = "Setiap kali saya hadir, semua orang memperlakukan saya dengan sanjungan gugup.",
  ui_story_5053_50531201_84_dialog_content = "Hanya dari jauh aku bisa melihat senyum mereka yang sebenarnya... Saat-saat bahagia mereka yang sebenarnya.",
  ui_story_5053_50531201_85_dialog_content = "Jadi saya bertanya kepada ayah saya mengapa mereka memperlakukan saya seperti ini.",
  ui_story_5053_50531201_86_dialog_content = "Dia mengatakan itu karena mereka semua sudah terbiasa hidup dalam dosa yang memalukan.",
  ui_story_5053_50531201_87_dialog_content = "Sehingga, mereka tidak tega memandang anggota DPR Schwartz, yang melambangkan kebenaran dan ketertiban.",
  ui_story_5053_50531201_88_dialog_content = "Itu adalah sifat mereka, kejahatan yang tidak pernah bisa dibasmi... Itulah sebabnya mereka membutuhkan bimbingan kita.",
  ui_story_5053_50531201_89_dialog_content = "Itu adalah tugas mulia House Schwartz menanggung beban pemerintahan dan memperbaiki perilaku mereka.",
  ui_story_5053_50531201_90_dialog_content = "... Tapi sejujurnya, tinggal di sini sangat mencekik.",
  ui_story_5053_50531201_91_dialog_content = "Karena alasan ini, saya sering menyamar dan menyelinap pergi dari rumah untuk menikmati jeda sejenak.",
  ui_story_5053_50531201_92_dialog_content = "Selama ini kupikir kau berbeda Joshua. Anda adalah satu-satunya orang yang akan tertawa bersama saya, Joshua.",
  ui_story_5053_50531201_93_dialog_content = "Tapi saya melihat sekarang bahwa itu hanya angan-angan... Dan saya masih harus banyak belajar.",
  ui_story_5053_50531201_94_dialog_content = "... Bodoh.",
  ui_story_5053_50531201_95_dialog_content = "Haha... Saya setuju. Andai saja aku tidak pernah dilahirkan a Schwartz.",
  ui_story_5053_50531201_96_dialog_content = "Itulah alasan mengapa saya harus menghadapi rasa sakit dan kebencian Anda.",
  ui_story_5053_50531201_97_dialog_content = "Pembunuhan sempurna seperti ini tidak akan pernah bisa dilakukan hanya oleh beberapa orang.",
  ui_story_5053_50531201_98_dialog_content = "Mereka dapat menyembunyikan identitas asli Anda, melatih Anda dari tahun ke tahun, mendapatkan bantuan dari semua personel terkait...",
  ui_story_5053_50531201_99_dialog_content = "Saya tidak dapat membayangkan berapa banyak orang yang diperlukan untuk mencapai prestasi seperti itu, apalagi melakukannya dengan presisi sempurna.",
  ui_story_5053_50531201_100_dialog_content = "Tekanan yang diberikan oleh House Schwartz jauh dari memberantas keserakahan dan kejahatan. Sebaliknya, itu telah membuat kita menjadi musuh banyak orang.",
  ui_story_5053_50531201_101_dialog_content = "Ini tidak pernah menjadi niat ayahku...",
  ui_story_5053_50531201_102_dialog_content = "Jangan mencoba membujukku dengan pidato menyedihkanmu, Schwartz. Jika Anda telah mengakui kesalahan Anda, Anda dan ayah Anda harus menerima tanggung jawab untuk itu... Dan membayarnya dengan nyawa Anda.",
  ui_story_5053_50531201_103_dialog_content = "Mati untuk kesalahan seseorang berarti menghindari tanggung jawab atas kesalahan itu, Joshua.",
  ui_story_5053_50531201_104_dialog_content = "Penglihatan ayahku tidak sepenuhnya salah. Nyatanya, ada banyak kualitas penebusan di dalamnya.",
  ui_story_5053_50531201_105_dialog_content = "Plot pembunuhan ini adalah bukti yang tak terbantahkan.",
  ui_story_5053_50531201_106_dialog_content = "…?",
  ui_story_5053_50531201_107_dialog_content = "Dulu, pangkat dan garis keturunan menentukan segalanya di Lumopolis.",
  ui_story_5053_50531201_108_dialog_content = "Suap dan penggelapan adalah kejadian umum di kalangan bangsawan. Dengan pengaruh politik mereka, mereka menduduki setiap posisi kekuasaan dan menggunakan hukum untuk memajukan kepentingan mereka sendiri.",
  ui_story_5053_50531201_109_dialog_content = "Namun di bawah tekanan ayah saya, masyarakat Lumopolis Bawah juga diberi hak untuk mencari keadilan.",
  ui_story_5053_50531201_110_dialog_content = "Dengan ancaman keadilan menggantung di atas kepala mereka, para bangsawan Lumopolis mulai mengakui kejahatan mereka dengan imbalan keringanan hukuman.",
  ui_story_5053_50531201_111_dialog_content = "Melalui sistem penilaian, orang-orang juga mulai menaiki jajaran hierarki kota kami.",
  ui_story_5053_50531201_112_dialog_content = "Ini sejalan dengan visi ayah saya: dunia di mana nilai seseorang ditentukan oleh keterampilan dan tekad mereka, bukan kelahiran mereka.",
  ui_story_5053_50531201_113_dialog_content = "Bukankah ayah Caleb adalah seorang sarjana yang lahir dari keluarga biasa?",
  ui_story_5053_50531201_114_dialog_content = "Jika yang kukatakan adalah kebohongan, maka seseorang seperti dia, tanpa kekayaan maupun status, tidak akan pernah bisa memasuki Taman Lumopolis hanya dengan bakat.",
  ui_story_5053_50531201_115_dialog_content = "Anda juga tidak bisa menggunakan statusnya sebagai profesor untuk lebih dekat dengan saya.",
  ui_story_5053_50531201_116_dialog_content = "Orang yang merencanakan pembunuhan ini mengakui kebenaran ini, dan mendasarkan seluruh rencana mereka di sekitarnya.",
  ui_story_5053_50531201_117_dialog_content = "...",
  ui_story_5053_50531201_118_dialog_content = "Jadi katakan padaku, Joshua. Di mana kebijakan ayah saya salah?",
  ui_story_5053_50531201_119_dialog_content = "Apakah karena Lumopolis Bawah masih dilanda kejahatan? Atau karena pembersihannya yang terlalu menentukan mengakibatkan keguguran keadilan yang tak terhitung jumlahnya?",
  ui_story_5053_50531201_120_dialog_content = "Apapun itu, aku bersumpah tidak akan berhenti sampai kebenaran terungkap.",
  ui_story_5053_50531201_121_dialog_content = "Mungkin tidak mungkin untuk menebus rasa sakit yang Anda rasakan saat ini ...",
  ui_story_5053_50531201_122_dialog_content = "Tapi paling tidak, kita harus mencoba meluruskan semuanya. Demi kepentingan orang lain dan juga kepentingan kita sendiri.",
  ui_story_5053_50531201_123_dialog_content = "... Anda masih tidak mengerti.",
  ui_story_5053_50531201_124_dialog_content = "Apa yang orang butuhkan bukanlah pemerintahan yang tepat tetapi kebebasan sejati dan mutlak.",
  ui_story_5053_50531201_125_dialog_content = "Mutlak... kebebasan?",
  ui_story_5053_50531201_126_dialog_content = "Ya. Hak untuk hidup sesuka mereka alih-alih mematuhi hierarki sosial.",
  ui_story_5053_50531201_127_dialog_content = "Hak untuk mengatakan apa yang ada di pikiran mereka tanpa takut kehilangan kekayaan atau bahkan nyawa mereka.",
  ui_story_5053_50531201_128_dialog_content = "Itulah kebebasan.",
  ui_story_5053_50531201_129_dialog_content = "Para pelayan itu sangat takut padamu karena mereka tahu kamu bisa mengambil semuanya dari mereka kapanpun kamu mau.",
  ui_story_5053_50531201_130_dialog_content = "\"Dunia di mana nilai seseorang ditentukan oleh keterampilan dan tekad mereka...\" Jangan membuatku tertawa!",
  ui_story_5053_50531201_131_dialog_content = "Bagi House Schwartz, kami hanyalah ternak yang keberadaannya hanya bergantung pada persetujuan Anda!",
  ui_story_5053_50531201_132_dialog_content = "...",
  ui_story_5053_50531201_133_dialog_content = "...",
  ui_story_5053_50531201_134_dialog_content = "Jadi dengan membunuh ayahku dan memberantas House Schwartz...",
  ui_story_5053_50531201_135_dialog_content = "Anda ingin menciptakan dunia kebebasan mutlak, dunia yang ada tanpa Rumah Schwartz?",
  ui_story_5053_50531201_136_dialog_content = "Akankah itu benar-benar membuatmu bahagia, Joshua?",
  ui_story_5053_50531201_137_dialog_content = "Kebahagiaan saya tidak terikat dengan semua ini.",
  ui_story_5053_50531201_138_dialog_content = "Setelah pembunuhan itu akhirnya dilakukan, hidupku juga akan berakhir.",
  ui_story_5053_50531201_139_dialog_content = "Dengan kata lain, Anda telah memilih kematian terlepas dari hasilnya?",
  ui_story_5053_50531201_140_dialog_content = "Apakah ini untuk melindungi sekutu Anda?",
  ui_story_5053_50531201_141_dialog_content = "Tidak. Setelah misiku selesai, aku tidak punya alasan untuk hidup lebih lama lagi.",
  ui_story_5053_50531201_142_dialog_content = "Tak ada alasan...?",
  ui_story_5053_50531201_143_dialog_content = "Para bangsawan didorong oleh kepentingan pribadi, tetapi kami didorong oleh cita-cita kami.",
  ui_story_5053_50531201_144_dialog_content = "Kita hidup bukan untuk kekayaan atau status, tetapi untuk mengangkat matahari baru ke langit, yang menyinari dunia secara merata.",
  ui_story_5053_50531201_145_dialog_content = "Untuk menjatuhkan matahari yang tua dan menindas, kita rela mengorbankan diri kita sendiri. Jangan berpikir Anda bisa menilai kami dengan pemikiran utilitarian Anda yang busuk.",
  ui_story_5053_50531201_146_dialog_content = "Heh, Meskipun saya merasa terhormat Anda telah berbagi begitu banyak dengan saya, mengapa semuanya begitu samar dan tidak jelas?",
  ui_story_5053_50531201_147_dialog_content = "Jadi ini cara bicara pilihanmu...?",
  ui_story_5053_50531201_148_dialog_content = "Jika ayah saya dan pemerintahannya mewakili \"matahari tua\", bukankah yang disebut \"matahari baru\" ini hanya akan menjadi penguasa lain?",
  ui_story_5053_50531201_149_dialog_content = "Orang di balik rencana pembunuhan... Apakah mereka berusaha menggantikan posisi ayahku sebagai penguasa baru?",
  ui_story_5053_50531201_150_dialog_content = "...",
  ui_story_5053_50531201_151_dialog_content = "... Sulit dipercaya.",
  ui_story_5053_50531201_152_dialog_content = "Saya bisa mengerti mati dengan musuh Anda untuk melindungi keluarga dan sekutu Anda ... Tapi apa yang Anda maksud dengan Anda tidak punya alasan untuk hidup?",
  ui_story_5053_50531201_153_dialog_content = "Bagaimana dengan adik laki-lakimu, yang menentangku siang dan malam sejak aku mencurimu darinya?",
  ui_story_5053_50531201_154_dialog_content = "Bagaimana dengan ayah angkat Anda, yang mengkhawatirkan keselamatan Anda dan hanya ingin Anda pulang?",
  ui_story_5053_50531201_155_dialog_content = "Apakah mereka tidak cukup alasan untuk hidup...?",
  ui_story_5053_50531201_156_dialog_content = "Jika Anda benar-benar percaya Rumah itu Schwartz telah merampok kebebasan setiap orang, Anda hanya perlu menghancurkan kami untuk merebutnya kembali!",
  ui_story_5053_50531201_157_dialog_content = "Jadi mengapa Anda harus menghilangkan kebebasan yang sama, bahkan jika Anda berhasil?",
  ui_story_5053_50531201_158_dialog_content = "Apakah ini berarti Anda akan mengakhiri hidup Anda sendiri jika ayah saya meninggal secara tidak terduga? Apakah nasib Anda begitu terjalin ?!",
  ui_story_5053_50531201_159_dialog_content = "Saya sudah cukup membuktikannya, bukan? Semua ikatan dan hubungan dengan pria itu dan putranya yang bodoh hanyalah penyamaran.",
  ui_story_5053_50531201_160_dialog_content = "Saya adalah senjata yang tujuan utamanya adalah untuk mengakhiri aturan House Schwartz.",
  ui_story_5053_50531201_161_dialog_content = "Tanpa musuh saya, saya tidak punya alasan untuk hidup. Kebebasan adalah milik rakyat, bukan milik saya.",
  ui_story_5053_50531201_162_dialog_content = "... Betapa munafik.",
  ui_story_5053_50531201_163_dialog_content = "Tampaknya \"matahari baru\" ini tidak pernah mengajari Anda arti sebenarnya dari cinta atau kebebasan.",
  ui_story_5053_50531201_164_dialog_content = "Bagaimana mungkin Anda bisa memberikan yang baik kepada orang-orang?",
  ui_story_5053_50531201_165_dialog_content = "...",
  ui_story_5053_50531201_166_dialog_content = "... Saya mengerti sekarang.",
  ui_story_5053_50531201_167_dialog_content = "Aku tidak pernah menjadi bagian dari duniamu. Saya tidak memiliki cara untuk benar-benar memahami bagaimana rakyat menderita di bawah pemerintahan yang ketat.",
  ui_story_5053_50531201_168_dialog_content = "Kamu juga tidak pernah menjadi bagian dari duniaku. Anda tidak memiliki cara untuk memahami arti sebenarnya dari cinta atau kebebasan.",
  ui_story_5053_50531201_169_dialog_content = "Ini adalah celah yang tidak pernah bisa kita harapkan untuk dijembatani.",
  ui_story_5053_50531201_170_dialog_content = "Setuju, jadi menyerah saja sudah ...",
  ui_story_5053_50531201_171_dialog_content = "Itulah mengapa kita harus bekerja sama, dan saling mengimbangi kekurangan satu sama lain!",
  ui_story_5053_50531201_172_dialog_content = "Kamu gila.",
  ui_story_5053_50531201_173_dialog_content = "Entah itu kami, atau ayahku, atau bahkan orang \"matahari baru\" ini...",
  ui_story_5053_50531201_174_dialog_content = "Tidak ada yang mampu melihat sesuatu dari sudut pandang semua orang. Tidak sendirian, setidaknya.",
  ui_story_5053_50531201_175_dialog_content = "Tapi jika kita mengesampingkan perbedaan kita dan mencoba bekerja sama...",
  ui_story_5053_50531201_176_dialog_content = "Kita bisa menciptakan dunia baru yang bebas! Di mana suara semua orang dapat didengar!",
  ui_story_5053_50531201_177_dialog_content = "Ini adalah tujuan Anda juga, bukan?",
  ui_story_5053_50531201_178_dialog_content = "...",
  ui_story_5053_50531201_179_dialog_content = "Sejak aku menghentikanmu hari itu, aku selalu memikirkannya.",
  ui_story_5053_50531201_180_dialog_content = "Apakah salah jika kita mempercayakan impian kita kepada orang lain?",
  ui_story_5053_50531201_181_dialog_content = "Entah itu mewujudkan visi ayahku atau membunuhnya untuk memunculkan \"matahari baru\"...",
  ui_story_5053_50531201_182_dialog_content = "Mungkin mengambil takdir kita ke tangan kita sendiri adalah cara terbaik untuk mewujudkan impian kita.",
  ui_story_5053_50531201_183_dialog_content = "Sama bingung dan bodohnya aku sekarang...",
  ui_story_5053_50531201_184_dialog_content = "Saya percaya bahwa dengan bekerja sama, kita dapat mencapai apapun yang kita inginkan.",
  ui_story_5053_50531201_185_dialog_content = "Yang perlu kita lakukan adalah mengambil langkah pertama.",
  ui_story_5053_50531201_186_dialog_content = "Anda bisa membuka mata saya ke dunia di luar Lumopolis Gardens.",
  ui_story_5053_50531201_187_dialog_content = "Baru setelah itu saya bisa melihat kekurangan politik ayah saya.",
  ui_story_5053_50531201_188_dialog_content = "Sebagai gantinya, saya akan membantu Anda mengalami hidup sepenuhnya, sehingga Anda dapat tertawa dari lubuk hati Anda lagi.",
  ui_story_5053_50531201_189_dialog_content = "Saat hari itu tiba, Anda dapat berbagi kegembiraan itu dengan seluruh dunia!",
  ui_story_5053_50531201_190_dialog_content = "... Betapa tidak ada gunanya.",
  ui_story_5053_50531201_191_dialog_content = "Ada banyak wanita lain yang akan sangat senang bermain-main dengan Anda. Mengapa membuang waktumu untukku?",
  ui_story_5053_50531201_192_dialog_content = "Yah... jujur saja...",
  ui_story_5053_50531201_193_dialog_content = "Ada begitu sedikit orang yang mau menentang ayahku, dan penduduk Taman Lumopolis tidak dapat memahami dunia luar...",
  ui_story_5053_50531201_194_dialog_content = "Dan, er... Seperti yang kubilang saat pertama kali kita bertemu—",
  ui_story_5053_50531201_195_dialog_content = "Aku jatuh cinta padamu pada pandangan pertama!",
  ui_story_5053_50531201_196_dialog_content = "...",
  ui_story_5053_50531201_197_dialog_content = "(Kegelapan Angel sudah lama tidak bergerak. Apakah dia akhirnya tenang...?)",
  ui_story_5053_50531201_198_dialog_content = "Hai! Apakah Anda akhirnya mau mendengarkan saya?",
  ui_story_5053_50531201_199_dialog_content = "Dengar, Setan Putih... Maksudku, kamu yang lain, ingin membunuh Caleb, Veronica, dan yang lainnya.",
  ui_story_5053_50531201_200_dialog_content = "Mereka sangat membutuhkan Anda...",
  ui_story_5053_50531201_201_dialog_content = "Da... Niel...",
  ui_story_5053_50531201_202_dialog_content = "Hah?",
  ui_story_5053_50531201_203_dialog_content = "Daniel... Kenapa kamu... mengkhianatiku?!",
  ui_story_5053_50531201_204_dialog_content = "<size=45>Daniel!!!</size>",
  ui_story_5053_50531201_205_dialog_content = "Apa yang—?! Dia bahkan lebih mengamuk dari sebelumnya! T-Tolong tenang! Aku bukan Tuhan Schwartz!",
  ui_story_5053_50531201_206_dialog_content = "<size=45>Daniel! Daniel!</size>",
  ui_story_5053_50531201_207_dialog_content = "(Saya kehabisan waktu, tapi setidaknya saya mendapatkan perhatiannya! Saya harus menariknya ke alun-alun!)",
  ui_story_5053_50531201_208_dialog_content = "<size=45>Daniel—</size>",
  ui_story_5053_50531301_1_dialog_content = "Terima kasih saya sampaikan kepada semua orang Lumopolis yang berkumpul di sini hari ini untuk merayakan acara khusus ini.",
  ui_story_5053_50531301_2_dialog_content = "Rumah Schwartz adalah permata mahkota kota, serta fondasinya.",
  ui_story_5053_50531301_3_dialog_content = "Kami mengangkat tangan kami untuk mempertahankan Lumopolis, memegang pedang yang dibuat oleh orang-orangnya sendiri.",
  ui_story_5053_50531301_4_dialog_content = "Hari ini, kami memuji tidak hanya House Schwartz dan teladan moralnya, tetapi juga orang-orang Lumopolis yang bangga dan saleh!",
  ui_story_5053_50531301_5_dialog_content = "Dengan ini saya menyatakan dimulainya Schwartz Perayaan Hari Keluarga!",
  ui_story_5053_50531301_6_dialog_content = "Perayaan akan segera dimulai, tapi Kegelapan Angel belum muncul di dekat stand.",
  ui_story_5053_50531301_7_dialog_content = "Singkirkan... Penyusup...",
  ui_story_5053_50531301_8_dialog_content = "Hmm? Ada apa dengan para penjaga ini?",
  ui_story_5053_50531301_9_dialog_content = "Jika saya ingat dengan benar, orang-orang di dalam Crystal of Eternal Memory tidak lebih dari ilusi yang diciptakan oleh Lumina.",
  ui_story_5053_50531301_10_dialog_content = "Mengapa mereka tiba-tiba berperilaku tidak menentu? Seolah-olah mereka telah kehilangan perasaan mereka ...",
  ui_story_5053_50531301_11_dialog_content = "Saya akan berada di mimbar untuk berjaga-jaga. Jika saya melihat tanda-tanda Kegelapan Angel, saya akan memberi tahu semua orang.",
  ui_story_5053_50531301_12_dialog_content = "Bagus. Waspadalah, Mia.",
  ui_story_5053_50531301_13_dialog_content = "(Mia harus aman di sana untuk saat ini. PlayerName, di sisi lain, di mana dia sekarang?)",
  ui_story_5053_50531301_14_dialog_content = "Apa?",
  ui_story_5053_50531301_15_dialog_content = "PlayerName…",
  ui_story_5053_50531301_16_dialog_content = "Harus menemukan... PlayerName...",
  ui_story_5053_50531301_17_dialog_content = "Berhenti. Kalian jelas bukan ksatria House Kartima.",
  ui_story_5053_50531301_18_dialog_content = "House Kartima sedang mengawasi keamanan untuk perayaan tahun ini, jadi mengapa Anda berkeliaran seperti ini?",
  ui_story_5053_50531301_19_dialog_content = "(Para penjaga ini terus terhuyung-huyung dan bergumam pada diri mereka sendiri... Mungkinkah mereka mabuk?)",
  ui_story_5053_50531301_20_dialog_content = "(Dan mengapa mereka begitu tertarik untuk menemukan PlayerName?)",
  ui_story_5053_50531301_21_dialog_content = "Harus menemukan... PlayerName...",
  ui_story_5053_50531301_22_dialog_content = "Harus menghilangkan... PlayerName...",
  ui_story_5053_50531301_23_dialog_content = "Maafkan saya? Apa yang baru saja Anda katakan adalah pelanggaran serius terhadap tugas kesatria Anda.",
  ui_story_5053_50531301_24_dialog_content = "Jelaskan dirimu saat ini juga, kalian semua.",
  ui_story_5053_50531301_25_dialog_content = "Hilangkan... Penyusup...!",
  ui_story_5053_50531301_26_dialog_content = "Mereka bahkan tidak bisa berbicara dengan jelas, apalagi memberi tahu saya siapa atau apa yang ada di balik ini. Apa yang salah dengan para ksatria ini?",
  ui_story_5053_50531301_27_dialog_content = "(Setelah reset, tidak seorang pun di Crystal of Eternal Memory harus mengenalinya PlayerName lagi.)",
  ui_story_5053_50531301_28_dialog_content = "(Mereka bahkan seharusnya tidak menyadari keberadaannya, apalagi memiliki niat membunuh terhadapnya.)",
  ui_story_5053_50531301_29_dialog_content = "Itu tidak perlu. Sebuah tim penjaga dapat menemukan PlayerName sama cepatnya, jika tidak lebih.",
  ui_story_5053_50531301_30_dialog_content = "Selain itu, kami membutuhkan kekuatan semua orang jika kami berharap memiliki kesempatan melawan monster itu.",
  ui_story_5053_50531301_31_dialog_content = "Saya pikir Anda tahu sebaik saya tahu mana dari hal-hal ini yang lebih penting. Gunakan akal sehatmu, Daniel.",
  ui_story_5053_50531301_32_dialog_content = "(... Joshua adalah satu-satunya di luar kelompok kami yang tahu tentang PlayerName.)",
  ui_story_5053_50531301_33_dialog_content = "(Dia juga satu-satunya orang yang hidup di dalam Crystal of Eternal Memory selain kita.)",
  ui_story_5053_50531301_34_dialog_content = "(Tapi kenapa dia ingin memburu anak kecil, yang tidak ada hubungannya dengan dia?)",
  ui_story_5053_50531301_35_dialog_content = "(Memberitahu Caleb untuk tetap di sisinya adalah pilihan yang tepat.)",
  ui_story_5053_50531301_36_dialog_content = "(Saya hanya berdoa agar dia tidak membiarkan kegembiraan bersatu kembali dengan saudara perempuannya mengaburkan penilaiannya dan mengungkap kebenaran sebagai pengganti saya.)",
  ui_story_5053_50531301_37_dialog_content = "Huff... huff... L-Lord Schwartz! Oh, syukurlah aku menemukanmu!",
  ui_story_5053_50531301_38_dialog_content = "PlayerName...?",
  ui_story_5053_50531301_39_dialog_content = "Aaaaaah—!",
  ui_story_5053_50531301_40_dialog_content = "PlayerName, turun!",
  ui_story_5053_50531301_41_dialog_content = "Lupakan tentang Kegelapan Angel! Mia dalam bahaya! Kita harus ke stand!",
  ui_story_5053_50531301_42_dialog_content = "Apa maksudmu?",
  ui_story_5053_50531301_43_dialog_content = "Percayalah padaku! Sekarang ayo pergi!!",
  ui_story_5053_50531301_44_dialog_content = "Sangat baik...",
  ui_story_5053_50531301_45_dialog_content = "Bwaaah! A-Apa ini?!",
  ui_story_5053_50531301_46_dialog_content = "Diam. Aku akan membawamu ke stand.",
  ui_story_5053_50531301_47_dialog_content = "?!",
  ui_story_5053_50531301_48_dialog_content = "D... Daniel...? Daniel!!!",
  ui_story_5053_50531301_49_dialog_content = "Hai! Berhenti mendorong!",
  ui_story_5053_50531301_50_dialog_content = "A-Apa yang terjadi?",
  ui_story_5053_50531301_51_dialog_content = "Raksasa! Itu monster!!",
  ui_story_5053_50531301_52_dialog_content = "Kerumunan gempar. Apa yang terjadi di bawah sana?",
  ui_story_5053_50531301_53_dialog_content = "<size=30> Itu... Ayah dan PlayerName! Tunggu, apa itu... si Kegelapan Angel?!</size>",
  ui_story_5053_50531301_54_dialog_content = "Ada apa, Veronica?",
  ui_story_5053_50531301_55_dialog_content = "T-Tidak apa-apa, Ayah...",
  ui_story_5053_50531301_56_dialog_content = "Mereka menerobos kerumunan dan menuju tribun!",
  ui_story_5053_50531301_57_dialog_content = "Hentikan mereka, penjaga!!",
  ui_story_5053_50531301_58_dialog_content = "(Kegelapan Angel benar-benar memburu Ayah... Seperti yang Ibu katakan.)",
  ui_story_5053_50531301_59_dialog_content = "(Aku tidak tahu kenapa mereka lari ke sini, tapi aku harus melindunginya.)",
  ui_story_5053_50531301_60_dialog_content = "(Oh, Hippoca, tolong jawab aku, aku membutuhkanmu lebih dari sebelumnya!)",
  ui_story_5053_50531301_61_dialog_content = "Veronika, apa yang terjadi? Siapakah orang-orang asing yang berkelahi di antara kerumunan itu?",
  ui_story_5053_50531301_62_dialog_content = "Aku tidak tahu Carleen, tapi tetap dekat dengan kami.",
  ui_story_5053_50531301_63_dialog_content = "Pria di depan itu adalah sesuatu yang lain.",
  ui_story_5053_50531301_64_dialog_content = "Dia menghindari penjaga kami dengan mudah, sambil menggendong seseorang.",
  ui_story_5053_50531301_65_dialog_content = "Bahkan, dia hampir terlihat seperti ...",
  ui_story_5053_50531301_66_dialog_content = "D-Dia menjatuhkan salah satu penjaga dan menggunakannya untuk melompat keluar dari kerumunan! Dia datang tepat ke arah kita!",
  ui_story_5053_50531301_67_dialog_content = "Teman-teman, lindungi yang lain! Aku akan menangani mereka sendiri.",
  ui_story_5053_50531301_68_dialog_content = "...",
  ui_story_5053_50531301_69_dialog_content = "Siapa Anda, dan apa urusan Anda di sini?",
  ui_story_5053_50531301_70_dialog_content = "Di mana bahaya yang Anda sebutkan, PlayerName?",
  ui_story_5053_50531301_71_dialog_content = "Saya mengajukan pertanyaan, Pak!",
  ui_story_5053_50531301_72_dialog_content = "Diatas kita! Ini akan berada di sini sebentar lagi!",
  ui_story_5053_50531301_73_dialog_content = "Dari mana datangnya makhluk busuk ini?! Penjaga! Lindungi aku! Penjaga!!!",
  ui_story_5053_50531301_74_dialog_content = "D... Daniel? Daniel... Daniel...",
  ui_story_5053_50531301_75_dialog_content = "Aaaaaah—Daniel—!!!",
  ui_story_5053_50531301_76_dialog_content = "Jauhi ayahku!",
  ui_story_5053_50531301_77_dialog_content = "... Itu disini! Naga itu ada di sini sekarang!!",
  ui_story_5053_50531301_78_dialog_content = "<size=50>Mengaum-!!!</size>",
  ui_story_5053_50531301_79_dialog_content = "Seekor naga terbang?",
  ui_story_5053_50531301_80_dialog_content = "Sebuah perjanjian terukir dalam garis keturunan House Kartima... Tapi bukankah itu masih terlalu dini?",
  ui_story_5053_50531301_81_dialog_content = "Saya akan menyarankan Anda untuk fokus pada bahaya yang ada, anak muda.",
  ui_story_5053_50531301_82_dialog_content = "Kartima pengkhianat... Anda tidak akan pernah memegang kendali di sini!",
  ui_story_5053_50531301_83_dialog_content = "Berkonsentrasilah pada musuhmu yang sebenarnya! Itu datang untuk kita!",
  ui_story_5053_50531301_84_dialog_content = "...",
  ui_story_5053_50531301_85_dialog_content = "I-Naga! Tapi itu belum seharusnya ada di sini!",
  ui_story_5053_50531301_86_dialog_content = "Jangan khawatir, Veronica! Aku akan melindungimu!",
  ui_story_5053_50531301_87_dialog_content = "Tidak... Para pemberontak menjalankan rencana mereka lebih cepat dari yang kita duga! Berlindung, Carleen!",
  ui_story_5053_50531301_88_dialog_content = "Carleen...? Veronika...?",
  ui_story_5053_50531301_89_dialog_content = "Roooooaaaaar!!!!!!",
  ui_story_5053_50531301_90_dialog_content = "Naga itu akan menyerang!",
  ui_story_5053_50531301_91_dialog_content = "—!!!",
  ui_story_5053_50531301_92_dialog_content = "Dari mana datangnya naga itu?!",
  ui_story_5053_50531301_93_dialog_content = "Waaaah! Ayah, dimana kamu?!",
  ui_story_5053_50531301_94_dialog_content = "Itu bernapas api! Berlari!!!",
  ui_story_5053_50531301_95_dialog_content = "Putra! Dimana kamu, anakku?!",
  ui_story_5053_50531301_96_dialog_content = "...",
  ui_story_5053_50531301_97_dialog_content = "Tolong pak! Pernahkah Anda melihat anak laki-laki saya? Dia setinggi ini, dan...",
  ui_story_5053_50531301_98_dialog_content = "Hilangkan ... mereka semua ...",
  ui_story_5053_50531301_99_dialog_content = "Hah? Apa katamu?",
  ui_story_5053_50531301_100_dialog_content = "Lebih banyak sekutu... singkirkan mereka semua...",
  ui_story_5053_50531301_101_dialog_content = "Urk?! A-apa yang kamu...",
  ui_story_5053_50531301_102_dialog_content = "Lebih banyak sekutu... singkirkan mereka semua...",
  ui_story_5053_50531301_103_dialog_content = "*Batuk* Veronica? Ayah? Kamu ada di mana?",
  ui_story_5053_50531301_104_dialog_content = "Carleen! Apa kamu baik baik saja?",
  ui_story_5053_50531301_105_dialog_content = "Saya baik-baik saja. Hanya saja tenggorokanku sakit karena semua debu.",
  ui_story_5053_50531301_106_dialog_content = "Ah, syukurlah...",
  ui_story_5053_50531301_107_dialog_content = "Veronica... Carleen...",
  ui_story_5053_50531301_108_dialog_content = "Itu berhasil! Mereka berempat mampu mengalahkan naga!!",
  ui_story_5053_50531301_109_dialog_content = "(Sepertinya hanya anggota keluarga yang bisa menenangkan Kegelapan Angel turun. Itu pertaruhan besar, tapi saya senang itu terbayar!",
  ui_story_5053_50531301_110_dialog_content = "Masih terlalu dini untuk merayakannya.",
  ui_story_5053_50531301_111_dialog_content = "Naga itu hanya mundur untuk mengumpulkan kekuatannya untuk serangan api lainnya.",
  ui_story_5053_50531301_112_dialog_content = "Itu akan segera menimpa kita.",
  ui_story_5053_50531301_113_dialog_content = "Itu berarti kita harus mengalahkannya sebelum meluncurkan serangan berikutnya.",
  ui_story_5053_50531301_114_dialog_content = "Maka Anda sebaiknya melakukannya dengan baik untuk menargetkan titik lemahnya.",
  ui_story_5053_50531301_115_dialog_content = "Lebih khusus lagi, Anda perlu menyerang—",
  ui_story_5053_50531301_116_dialog_content = "Aku tahu di mana harus menyerang binatang itu.",
  ui_story_5053_50531301_117_dialog_content = "Itu tidak akan ada gunanya bagi kita! Naga itu memiliki semacam kekebalan, yang memungkinkannya menyembuhkan luka secara instan.",
  ui_story_5053_50531301_118_dialog_content = "Apa?",
  ui_story_5053_50531301_119_dialog_content = "Yang mulia Schwartz! Pemberontakan telah dimulai!",
  ui_story_5053_50531301_120_dialog_content = "Kemudian lanjutkan dengan rencananya. Kumpulkan lebih banyak orang dan tekan para pemberontak.",
  ui_story_5053_50531301_121_dialog_content = "Serahkan naga itu padaku, dan suruh prajurit yang tersisa mengevakuasi orang-orang dari daerah ini.",
  ui_story_5053_50531301_122_dialog_content = "Tapi Tuanku... Pemberontak bukan satu-satunya yang melakukan kerusuhan! Kebanyakan orang di daerah itu, termasuk beberapa tentara kita sendiri, juga mulai menyerang!",
  ui_story_5053_50531301_123_dialog_content = "Apa…?!",
  ui_story_5053_50531301_124_dialog_content = "Mereka tampaknya telah kehilangan kendali atas tubuh dan pikiran mereka, Tuanku. Mereka menyerang makhluk hidup apa pun yang dapat mereka jangkau, apakah mereka teman atau musuh!",
  ui_story_5053_50531301_125_dialog_content = "Tetapi hal yang paling mengganggu adalah kegilaan mereka tampaknya menyebar ke siapa pun yang berhasil mereka lukai! Seolah-olah...",
  ui_story_5053_50531301_126_dialog_content = "Seolah-olah mereka terinfeksi dan berubah menjadi mati berjalan, bukan?",
  ui_story_5053_50531301_127_dialog_content = "P-Tepatnya.",
  ui_story_5053_50531301_128_dialog_content = "Anda tampaknya cukup menyadari situasi kita saat ini.",
  ui_story_5053_50531301_129_dialog_content = "Waktu tidak ada di pihak kita, jadi beri tahu kami apa yang Anda ketahui.",
  ui_story_5053_50531301_130_dialog_content = "Aku…",
  ui_story_5053_50531301_131_dialog_content = "(Muda Schwartz menatapku juga...)",
  ui_story_5053_50531301_132_dialog_content = "(Jika saya tidak memberinya penjelasan yang cukup baik, dia tidak akan melepaskan saya dengan mudah.)",
  ui_story_5053_50531301_133_dialog_content = "(Tapi jika aku mengatakan yang sebenarnya padanya sekarang, itu hanya akan membuatnya meragukanku! Aku harus memberikan alasan yang tepat...)",
  ui_story_5053_50531301_134_dialog_content = "Apakah Anda segan untuk membocorkan kebenaran di hadapan saya?",
  ui_story_5053_50531301_135_dialog_content = "Atau mungkinkah pelakunya berdiri di antara kalian orang luar—",
  ui_story_5053_50531301_136_dialog_content = "Seperti mungkin monster bersayap di sana?",
  ui_story_5053_50531301_137_dialog_content = "Tolong jangan panggil dia seperti itu! Dia bukan monster, dia...",
  ui_story_5053_50531301_138_dialog_content = "Di atas sana, sang naga bersiap turun untuk serangan lain.",
  ui_story_5053_50531301_139_dialog_content = "Sementara pasukan mayat hidup mengelilingi kita dari bawah.",
  ui_story_5053_50531301_140_dialog_content = "Saya yakin Anda tahu apa yang diutamakan pada saat seperti ini, ya?",
  ui_story_5053_50531301_141_dialog_content = "... Tentu saja saya tahu.",
  ui_story_5053_50531301_142_dialog_content = "Penjaga, hubungi Lachon dan Otto, dan beri tahu mereka bahwa tentara di alun-alun berada di bawah komando mereka sekarang.",
  ui_story_5053_50531301_143_dialog_content = "Beri tahu mereka untuk membentengi pertahanan tribun dan membawa penyintas yang tidak terinfeksi ke sini.",
  ui_story_5053_50531301_144_dialog_content = "Baik tuan ku!",
  ui_story_5053_50531301_145_dialog_content = "(Beruntung Tuhan itu Schwartz bisa melepaskan dirinya yang lebih muda dari punggungku. Dia pasti menyadari bahwa saya punya alasan untuk tidak mengatakan yang sebenarnya.)",
  ui_story_5053_50531301_146_dialog_content = "(Saya tidak bisa menyia-nyiakan waktu kita lagi, tidak setelah kita sampai sejauh ini. Sudah waktunya bagi kita untuk kembali ke Schwartz Rumah besar!)",
  ui_story_5053_50531301_147_dialog_content = "Veronica... Kenapa memanggil namaku?",
  ui_story_5053_50531301_148_dialog_content = "Jaga jarak dengannya, Carleen.",
  ui_story_5053_50531301_149_dialog_content = "Veronica... Carleen... Apakah kamu terluka...?",
  ui_story_5053_50531301_150_dialog_content = "Apakah kamu terluka...?",
  ui_story_5053_50531301_151_dialog_content = "Aku akan memelukmu... dan bernyanyi...",
  ui_story_5053_50531301_152_dialog_content = "Hah? Aku baik-baik saja, dan begitu juga Carleen.",
  ui_story_5053_50531301_153_dialog_content = "Jadi Anda bisa berkomunikasi dengan kami... Anda adalah bagian dari Ibu, bukan?",
  ui_story_5053_50531301_154_dialog_content = "Ibu... aku.. Ibu...",
  ui_story_5053_50531301_155_dialog_content = "Lalu bisakah kamu berhenti menyerang kami? Bisakah kamu berhenti berusaha menyakiti Ayah?",
  ui_story_5053_50531301_156_dialog_content = "Veronica... Ayah? Danial...Daniel...!!!",
  ui_story_5053_50531301_157_dialog_content = "K-Kamu tidak pernah ingin kami melihat kalian berdua berkelahi!",
  ui_story_5053_50531301_158_dialog_content = "Bukankah itu benar?",
  ui_story_5053_50531301_159_dialog_content = "...",
  ui_story_5053_50531301_160_dialog_content = "Tidak lagi... Tidak ada lagi perkelahian... Itu membuat para gadis ketakutan...",
  ui_story_5053_50531301_161_dialog_content = "Jangan berkelahi lagi... Veronica... jangan takut...",
  ui_story_5053_50531301_162_dialog_content = "Aku tahu, Ibu. Terima kasih.",
  ui_story_5053_50531301_163_dialog_content = "(Kata Ibu Gelap Angel lahir dari Benih, dan bahwa dia tidak lebih dari binatang buas yang tidak berakal.)",
  ui_story_5053_50531301_164_dialog_content = "(Tapi aku tidak hanya bisa berkomunikasi dengannya... Aku bahkan bisa merasakan kebaikan tertentu datang darinya.)",
  ui_story_5053_50531301_165_dialog_content = "(Kebaikan yang belum pernah kurasakan dari ibu di mansion. Apa yang sebenarnya terjadi...?)",
  ui_story_5053_50531301_166_dialog_content = "<size=30>Hai! Di sini, Veronica!</size>",
  ui_story_5053_50531301_167_dialog_content = "PlayerName! Ayah! Apakah kalian berdua baik-baik saja?",
  ui_story_5053_50531301_168_dialog_content = "Ssst! Tetap tenang!",
  ui_story_5053_50531301_169_dialog_content = "Sedangkan yang muda Schwartz sibuk melawan naga, kami bertiga dan Kegelapan Angel harus pergi.",
  ui_story_5053_50531301_170_dialog_content = "Meninggalkan? Tapi kemana? Dan mengapa Dark Angel harus ikut dengan kami?",
  ui_story_5053_50531301_171_dialog_content = "Ke Schwartz Rumah besar. Kaleb dan Jakine berada dalam bahaya serius.",
  ui_story_5053_50531301_172_dialog_content = "Hah? Maafkan aku, ini semua sangat membingungkan. Apa sebenarnya...",
  ui_story_5053_50531301_173_dialog_content = "PlayerName telah berjanji untuk menjelaskan semuanya di jalan. Kita harus pergi selagi masih ada kesempatan.",
  ui_story_5053_50531301_174_dialog_content = "Y-Ya, kalau begitu.",
  ui_story_5053_50531301_175_dialog_content = "Daniel...",
  ui_story_5053_50531301_176_dialog_content = "Dan Anda yakin dia tidak akan menyerang saya lagi, PlayerName?",
  ui_story_5053_50531301_177_dialog_content = "Uh, aku cukup yakin kau aman untuk saat ini...",
  ui_story_5053_50531301_178_dialog_content = "Dia tidak akan, Ayah. Ibu sudah berjanji padaku bahwa dia tidak akan melakukannya, kan?",
  ui_story_5053_50531301_179_dialog_content = "Saya berjanji...",
  ui_story_5053_50531301_180_dialog_content = "... Bagus.",
  ui_story_5053_50531301_181_dialog_content = "Bagian belakang dudukan harus bebas dari penonton. Kita harus pergi sebelum mereka selesai memperkuat pertahanan mereka.",
  ui_story_5053_50531301_182_dialog_content = "Kemana kamu pergi, Veronica?",
  ui_story_5053_50531301_183_dialog_content = "Ayah menyuruh kami tinggal di sini dan menunggu Ms. Rot mengantar kami ke tempat aman.",
  ui_story_5053_50531301_184_dialog_content = "Saya minta maaf, Carleen, tapi aku tidak bisa tinggal. Ada sesuatu yang sangat penting yang harus saya lakukan.",
  ui_story_5053_50531301_185_dialog_content = "Tapi gadis pemberani sepertimu seharusnya tidak masalah menunggu Ms. Rot sendirian, kan?",
  ui_story_5053_50531301_186_dialog_content = "Aku akan baik-baik saja, tapi aku lebih mengkhawatirkanmu, Veronica.",
  ui_story_5053_50531301_187_dialog_content = "Ketika Anda pergi sendiri, biasanya menangis sendiri ...",
  ui_story_5053_50531301_188_dialog_content = "Tapi kamu tidak perlu menangis lagi, Veronica! Aku berjanji akan menjadi lebih kuat suatu hari nanti dan melindungimu, apapun yang terjadi!",
  ui_story_5053_50531301_189_dialog_content = "Heehee... Kamu telah menjadi orang yang berani dan dewasa, Carleen.",
  ui_story_5053_50531301_190_dialog_content = "Anda juga tidak perlu khawatir. Aku tidak lemah dan tak berdaya seperti dulu.",
  ui_story_5053_50531301_191_dialog_content = "Kakak perempuanmu akan baik-baik saja, aku janji.",
  ui_story_5053_50531301_192_dialog_content = "Saya tahu saya selalu setengah langkah di belakang Anda di masa lalu dan mempersulit semua orang.",
  ui_story_5053_50531301_193_dialog_content = "Tapi mulai sekarang, aku akan bekerja keras dan menjadi kakak perempuan yang bisa diandalkan yang bisa membantumu menanggung bebanmu.",
  ui_story_5053_50531301_194_dialog_content = "Veronika...?",
  ui_story_5053_50531301_195_dialog_content = "Jadi tolong, percayalah padaku.",
  ui_story_5053_50531301_196_dialog_content = "Ya. Saya percaya kamu.",
  ui_story_5053_50531301_197_dialog_content = "Heehee, terima kasih.",
  ui_story_5053_50531301_198_dialog_content = "Sampai lain kali... Sayangku, kecil Carleen.",
  ui_story_5053_50531302_1_dialog_content = "... Ini adalah situasi saat ini di alun-alun.",
  ui_story_5053_50531302_2_dialog_content = "Setiap lorong menuju alun-alun telah ditutup sepenuhnya.",
  ui_story_5053_50531302_3_dialog_content = "Di bawah komando Lord Schwartz, kerusuhan mulai terkendali. Anda dapat menenangkan pikiran Anda, Yang Mulia.",
  ui_story_5053_50531302_4_dialog_content = "... Dipahami. Anda dapat pergi sekarang.",
  ui_story_5053_50531302_5_dialog_content = "Baiklah.",
  ui_story_5053_50531302_6_dialog_content = "Nah, maukah Anda menjadi sayang dan mengunci pintu untuk kami, Jakine?",
  ui_story_5053_50531302_7_dialog_content = "Oh, tentu! Lagi pula, bahkan kunci sederhana pun dapat melakukan keajaiban bagi keselamatan kita!",
  ui_story_5053_50531302_8_dialog_content = "Izinkan saya mengajukan pertanyaan, Caleb. Mengapa Anda ingin menyelamatkan saya?",
  ui_story_5053_50531302_9_dialog_content = "Hah?",
  ui_story_5053_50531302_10_dialog_content = "Hmm? Karena kau adikku, tentu saja! Kakak mana yang tidak mau membantu adiknya sendiri?",
  ui_story_5053_50531302_11_dialog_content = "<color=#e8d9bb>Buk, Buk, Buk!</color>",
  ui_story_5053_50531302_12_dialog_content = "Wanita Joshua, Saya datang untuk mengantar Anda ke tempat yang aman. May Saya masuk?",
  ui_story_5053_50531302_13_dialog_content = "Tentu, masuk saja ke sini!",
  ui_story_5053_50531302_14_dialog_content = "Jakine, apakah Anda lupa bahwa Anda adalah tamu di sini? Adikku belum selesai berbicara!",
  ui_story_5053_50531302_15_dialog_content = "...",
  ui_story_5053_50531302_16_dialog_content = "Maafkan interupsi...",
  ui_story_5053_50531302_17_dialog_content = "Ada apa, Nona Rot?",
  ui_story_5053_50531302_18_dialog_content = "Saya diberitahu bahwa Anda tidak enak badan hari ini. Seperti itu, Tuhan Schwartz memerintahkan saya untuk tinggal di sisi Anda dan memastikan keselamatan Anda.",
  ui_story_5053_50531302_19_dialog_content = "Mengingat beratnya situasi, saya harus meminta Anda untuk mengikuti saya ke lokasi lain yang aman.",
  ui_story_5053_50531302_20_dialog_content = "Setelah Anda berlindung, saya akan mengawal Putri Carleen untuk keselamatan juga. Yakinlah, aku tidak akan membiarkan dia terluka.",
  ui_story_5053_50531302_21_dialog_content = "Jadi begitu. Kamu baik sekali.",
  ui_story_5053_50531302_22_dialog_content = "Namun, tamu saya dan saya sangat aman di sini. Jika ada, Anda harus lebih memperhatikan keselamatan Carleen sekarang.",
  ui_story_5053_50531302_23_dialog_content = "Saya khawatir saya tidak bisa melakukan itu.",
  ui_story_5053_50531302_24_dialog_content = "Jika aku pergi sekarang... Kau tidak akan kesulitan membunuh dua tamumu saat aku tidak ada.",
  ui_story_5053_50531302_25_dialog_content = "M-Pembunuhan?!",
  ui_story_5053_50531302_26_dialog_content = "Apa artinya ini, Ms. Rot?! Adikku tidak akan pernah...",
  ui_story_5053_50531302_27_dialog_content = "... Joshua?",
  ui_story_5053_50531302_28_dialog_content = "Ya, Kaleb. Saya tidak akan pernah melakukan sesuatu yang begitu kejam dan mengerikan.",
  ui_story_5053_50531302_29_dialog_content = "Mengapa Anda menuduh saya tentang itu, Ms. Rot?",
  ui_story_5053_50531302_30_dialog_content = "Anda dapat membuang tindakan tersebut.",
  ui_story_5053_50531302_31_dialog_content = "Belati itu tersembunyi di kakimu, bukan? Metode pembunuhan yang cukup klasik.",
  ui_story_5053_50531302_32_dialog_content = "Kemampuan Anda untuk menyembunyikan senjata tidak ada bandingannya, tetapi tangan Anda yang melayang di atas gagangnya membuat niat Anda terlalu jelas.",
  ui_story_5053_50531302_33_dialog_content = "...",
  ui_story_5053_50531302_34_dialog_content = "Anda adalah pembunuh yang sangat terlatih, dan tidak diragukan lagi.",
  ui_story_5053_50531302_35_dialog_content = "Anda sangat mirip dengan tuan saya, tetapi Anda tidak lebih dari seorang penipu yang sangat menarik.",
  ui_story_5053_50531302_36_dialog_content = "Seorang penipu? T-Tapi suara dan penampilannya... Aku tidak pernah salah mengira mereka!",
  ui_story_5053_50531302_37_dialog_content = "Dia benar, dan Crystal of Eternal Memory dengan jelas menunjukkan bahwa dia juga orang yang hidup dan bernafas!",
  ui_story_5053_50531302_38_dialog_content = "Apa kemungkinan ada orang lain di sini yang menyamar sebagai Lady Joshua?!",
  ui_story_5053_50531302_39_dialog_content = "Saya tidak tahu bagaimana kalian berdua terhubung dengan pembunuh ini, tapi demi keselamatan Anda, saya sarankan Anda menjaga jarak darinya.",
  ui_story_5053_50531302_40_dialog_content = "Jika saya harus menebak, Anda pasti sisa lain dari organisasi itu, yang juga mereka latih dalam seni membunuh.",
  ui_story_5053_50531302_41_dialog_content = "Lagi pula, kemiripan antara kamu dan mantan majikanku sangat luar biasa.",
  ui_story_5053_50531302_42_dialog_content = "Justru karena alasan inilah Anda tidak akan pernah bisa menggantikannya. Wanita Joshua hari ini adalah istri yang penuh kasih, ibu yang mengasuh, dan saudara perempuan yang peduli.",
  ui_story_5053_50531302_43_dialog_content = "Apakah saya benar mengatakan demikian?",
  ui_story_5053_50531302_44_dialog_content = "...",
  ui_story_5053_50531302_45_dialog_content = "L-Nyonya Joshua memiliki belati di tangannya! Bagaimana dia menariknya entah dari mana...?",
  ui_story_5053_50531302_46_dialog_content = "Argh, itu berhasil! Dimana bola kristalku?!",
  ui_story_5053_50531302_47_dialog_content = "Tidak salah lagi, Jakine... Dia benar-benar adikku. Tapi bagaimana... Bagaimana ini bisa terjadi?!",
  ui_story_5053_50531302_48_dialog_content = "Berhentilah berdiri, Caleb! Jika Anda tidak akan bertarung, berlindunglah!",
  ui_story_5053_50531302_49_dialog_content = "<size=45>Aaaaaah—!</size>",
  ui_story_5053_50531302_50_dialog_content = "I-Itu kamu—!!",
  ui_story_5053_50531302_51_dialog_content = "Itu adalah Kegelapan Angel!",
  ui_story_5053_50531302_52_dialog_content = "Kegelapan Angel...?",
  ui_story_5053_50531302_53_dialog_content = "Jauh... dari Kaleb...",
  ui_story_5053_50531302_54_dialog_content = "<size=45>Tinggalkan... Caleb... Sendirian!!!</size>",
  ui_story_5053_50531302_55_dialog_content = "Sedang apa kau di sini?!",
  ui_story_5053_50531302_56_dialog_content = "Menjauhlah dariku, dasar menjijikkan!",
  ui_story_5053_50531302_57_dialog_content = "Tidak ada jalan keluar!",
  ui_story_5053_50531302_58_dialog_content = "Ibu Negara Joshua ingin membunuh kita, dan sekarang si Kegelapan Angel mengejarnya...",
  ui_story_5053_50531302_59_dialog_content = "A-Apa yang terjadi lagi?! Seseorang perlu menjelaskan kekacauan ini sekarang!",
  ui_story_5053_50531302_60_dialog_content = "A-Wah, Hippoca! Berhenti...!!",
  ui_story_5053_50531302_61_dialog_content = "Bwaaa! Dan sekarang seekor kuda laba-laba raksasa baru saja terbang melalui jendela!!!",
  ui_story_5053_50531302_62_dialog_content = "Tunggu... PlayerName?! Dengan Mia dan Tuhan Schwartz!",
  ui_story_5053_50531302_63_dialog_content = "Bagus sekali, Mia. Anda tampaknya memiliki bakat yang cukup ketika menggunakan pemanggilan Lumina Anda sebagai tunggangan.",
  ui_story_5053_50531302_64_dialog_content = "*Terengah-engah* Sejujurnya... Itu pertama kalinya aku menggunakan Hippoca seperti itu...",
  ui_story_5053_50531302_65_dialog_content = "Ugh... Kami melompati begitu banyak bangunan di punggung Hippoca... Kurasa aku akan sakit...",
  ui_story_5053_50531302_66_dialog_content = "Apa kalian bertiga...",
  ui_story_5053_50531302_67_dialog_content = "Oh bagus, sepertinya Caleb dan Jakine masih oke...",
  ui_story_5053_50531302_68_dialog_content = "Syukurlah kita berhasil tepat waktu... Urk...!",
  ui_story_5053_50531401_1_dialog_content = "Jadi maksudmu Iblis Putih ini telah mempermainkan kita selama ini sebagai orang bodoh.",
  ui_story_5053_50531401_2_dialog_content = "Dan bahwa dia dan Dark Angel keduanya adalah bagian dari Lady Joshua, tapi mereka tidak bisa berdamai satu sama lain.",
  ui_story_5053_50531401_3_dialog_content = "Jadi rencananya adalah membunuh kita semua, menyerap Lumina kita, dan membebaskan dirinya dengan itu...",
  ui_story_5053_50531401_4_dialog_content = "Meskipun kedengarannya sangat sulit dipercaya, saya pikir saya mengerti keadaannya.",
  ui_story_5053_50531401_5_dialog_content = "Rasa sakit yang membelah kepala, ketakutan akan dirinya yang lain...",
  ui_story_5053_50531401_6_dialog_content = "Tapi meski kami sangat berbeda, Baba Yaga dan aku adalah satu orang yang sama.",
  ui_story_5053_50531401_7_dialog_content = "Dan jika aku bisa belajar hidup berdampingan dengannya, maka pasti ibu bisa...",
  ui_story_5053_50531401_8_dialog_content = "Apakah Anda pikir kami masih memiliki kesempatan untuk meyakinkan Setan Putih untuk menghentikan rencananya yang gila, PlayerName?",
  ui_story_5053_50531401_9_dialog_content = "Yah... Saya pikir hanya Lady yang sebenarnya Joshua akan tahu itu.",
  ui_story_5053_50531401_10_dialog_content = "Yang saya tahu adalah Crystal of Eternal Memory hampir habis Lumina.",
  ui_story_5053_50531401_11_dialog_content = "Ini adalah kesempatan terakhir kita untuk keluar dari sini. Kita tidak bisa membuang-buang waktu memikirkan hal-hal yang berlebihan.",
  ui_story_5053_50531401_12_dialog_content = "Maafkan saya, tetapi saya tidak dapat menaklukkan Lady lainnya Joshua.",
  ui_story_5053_50531401_13_dialog_content = "Seorang penjaga baru saja memberi tahu saya bahwa situasi di alun-alun sekarang terkendali.",
  ui_story_5053_50531401_14_dialog_content = "Namun, naga terus menjadi ancaman tanpa henti. Pasukan kita tidak akan bertahan lebih lama melawan musuh yang tidak terkalahkan seperti ini.",
  ui_story_5053_50531401_15_dialog_content = "Terima kasih atas bantuannya, Bu Rot. Anda dapat menyerahkan sisanya kepada kami.",
  ui_story_5053_50531401_16_dialog_content = "Aku takut aku harus menolak.",
  ui_story_5053_50531401_17_dialog_content = "Tugas saya adalah melindungi House Schwartz dan seluruh Lumopolis.",
  ui_story_5053_50531401_18_dialog_content = "Apakah aku hanya ilusi atau bukan tidak ada hubungannya dengan tugasku. Saya, dan akan selalu, Ms. Rot.",
  ui_story_5053_50531401_19_dialog_content = "Bahkan dalam menghadapi krisis eksistensial yang begitu menggelegar, ketenangan Anda tetap tak tergoyahkan.",
  ui_story_5053_50531401_20_dialog_content = "Heheh... Sejujurnya, realisasi ini membuatku lega.",
  ui_story_5053_50531401_21_dialog_content = "Sekarang saya tahu tidak ada masa depan untuk diri saya sendiri, saya tidak punya alasan untuk terus mengkhawatirkannya.",
  ui_story_5053_50531401_22_dialog_content = "Jika ada yang menderita karena kebenaran saat ini, itu adalah Tuan Caleb.",
  ui_story_5053_50531401_23_dialog_content = "Joshua... Tidak pernah ingin ada yang tahu kebenaran tentang masa lalunya.",
  ui_story_5053_50531401_24_dialog_content = "Di satu sisi, mengungkap masa lalunya hanya akan mengundang lebih banyak kritik.",
  ui_story_5053_50531401_25_dialog_content = "Namun, saya yakin alasan sebenarnya adalah dia tidak tega mengakuinya kepada adik laki-lakinya.",
  ui_story_5053_50531401_26_dialog_content = "Di satu sisi, kekuatan dan kebaikan yang dia temukan selama bertahun-tahun juga memunculkan kelemahan terbesarnya.",
  ui_story_5053_50531401_27_dialog_content = "Saya tahu apa yang ingin Anda katakan. Untuk Nyonya Joshua tumbuh dan mengalami begitu banyak emosi adalah hal yang positif.",
  ui_story_5053_50531401_28_dialog_content = "Namun terkadang, suatu masalah hanya dapat diselesaikan dengan berkomunikasi secara terbuka dan tulus, meskipun hal itu menakutkan.",
  ui_story_5053_50531401_29_dialog_content = "Ketika Nyonya Joshua akhirnya terbangun kembali di dunia nyata, saya harus meminta Anda berbagi pemikiran tulus ini dengannya juga.",
  ui_story_5053_50531401_30_dialog_content = "Kalau tidak, dia mungkin menjadi sangat marah sehingga dia kehilangan kesadaran sekali lagi.",
  ui_story_5053_50531401_31_dialog_content = "... Saya akan ingat untuk melakukannya.",
  ui_story_5053_50531401_32_dialog_content = "Eh, Tuhan Schwartz? Apakah Anda dan Ms. Rot sudah selesai berbicara? Kami masih perlu membicarakan langkah selanjutnya dari rencana kami.",
  ui_story_5053_50531401_33_dialog_content = "Tentu.",
  ui_story_5053_50531401_34_dialog_content = "... Tunggu, dimana Caleb? Apa dia sudah merasa lebih baik?",
  ui_story_5053_50531401_35_dialog_content = "Biarkan dia untuk saat ini.",
  ui_story_5053_50531401_36_dialog_content = "...",
  ui_story_5053_50531401_37_dialog_content = "Apakah kamu... benar-benar adikku...?",
  ui_story_5053_50531401_38_dialog_content = "—!",
  ui_story_5053_50531401_39_dialog_content = "Mengapa Anda bersembunyi dari saya?",
  ui_story_5053_50531401_40_dialog_content = "Apakah Iblis Putih mengatakan yang sebenarnya? Mungkinkah... Anda tidak pernah benar-benar melihat saya sebagai sebuah keluarga?",
  ui_story_5053_50531401_41_dialog_content = "... TIDAK...",
  ui_story_5053_50531401_42_dialog_content = "Caleb... Aku... Takut...",
  ui_story_5053_50531401_43_dialog_content = "Takut?",
  ui_story_5053_50531401_44_dialog_content = "Caleb... mencintaiku... mempercayaiku...",
  ui_story_5053_50531401_45_dialog_content = "Dadaku... sakit... tekanan... tidak bisa bernafas...",
  ui_story_5053_50531401_46_dialog_content = "Ayah.. lepaskan... mati... untuk melindungiku... Semua... salahku...",
  ui_story_5053_50531401_47_dialog_content = "Apa maksudmu...?",
  ui_story_5053_50531401_48_dialog_content = "Bagian lain dari dirimu mengatakan bahwa Ayah bunuh diri untuk melestarikan bara balas dendam.",
  ui_story_5053_50531401_49_dialog_content = "Namun, Anda mengatakan dia melepaskan semuanya ... Saya tidak tahu lagi apa yang sebenarnya.",
  ui_story_5053_50531401_50_dialog_content = "Anda menyamar sebagai saudara perempuan saya selama bertahun-tahun, hanya agar Anda dapat membunuh ayah Schwartz.",
  ui_story_5053_50531401_51_dialog_content = "Anda membesarkan saya dan merawat saya seperti saudara perempuan sejati... Tidak, seperti seorang ibu.",
  ui_story_5053_50531401_52_dialog_content = "Bertahun-tahun bertahan denganku... Stresnya pasti tak tertahankan.",
  ui_story_5053_50531401_53_dialog_content = "... Tapi itu tidak masalah sekarang, Joshua. Kebahagiaanmu akan selalu menjadi prioritasku, sekarang dan selamanya.",
  ui_story_5053_50531401_54_dialog_content = "Setelah kita kembali ke kenyataan, jika kamu benar-benar tidak melihatku sebagai saudaramu... maka aku tidak akan mengganggumu lagi. Saya ingin Anda hidup bebas dan tanpa penyesalan, seperti yang selalu Anda inginkan.",
  ui_story_5053_50531401_55_dialog_content = "Tidak... Kumohon... jangan tinggalkan aku... Caleb...",
  ui_story_5053_50531401_56_dialog_content = "Aku salah... berbohong... tapi... aku takut...",
  ui_story_5053_50531401_57_dialog_content = "Takut... kau... akan membenciku...",
  ui_story_5053_50531401_58_dialog_content = "...",
  ui_story_5053_50531401_59_dialog_content = "Aku tidak pernah bisa membencimu, Joshua.",
  ui_story_5053_50531401_60_dialog_content = "Anda adalah saudara perempuan yang paling cantik dan lembut yang pernah diminta siapa pun.",
  ui_story_5053_50531401_61_dialog_content = "Bagaimana mungkin aku bisa membencimu dengan cara apa pun?",
  ui_story_5053_50531401_62_dialog_content = "Baiklah, jadi izinkan saya membahas semuanya untuk terakhir kalinya.",
  ui_story_5053_50531401_63_dialog_content = "Seperti berdiri, kami telah menghentikan rencana Iblis Putih sebelumnya untuk membunuh kami.",
  ui_story_5053_50531401_64_dialog_content = "Dengan tidak ada tempat lain untuk pergi, ada peluang bagus dia akan menggunakan naga dan orang-orang yang dikendalikan pikiran itu untuk meluncurkan serangan terakhir yang putus asa.",
  ui_story_5053_50531401_65_dialog_content = "Meskipun kami memiliki keunggulan angka sekarang, dan muda Schwartz masih menangkis naga ...",
  ui_story_5053_50531401_66_dialog_content = "Dia dan pasukannya tidak akan bisa bertarung dengan kekuatan penuh, tidak dengan seberapa sedikit Lumina yang tersisa di Crystal of Eternal Memory.",
  ui_story_5053_50531401_67_dialog_content = "Tidak hanya itu, sisa hari tinggal beberapa jam saja.",
  ui_story_5053_50531401_68_dialog_content = "Kami membutuhkan metode sederhana dan efektif yang memungkinkan kami menangani semua pion Iblis Putih dalam waktu sesingkat mungkin.",
  ui_story_5053_50531401_69_dialog_content = "Itu satu-satunya cara kita bisa menangkapnya.",
  ui_story_5053_50531401_70_dialog_content = "Apakah Crystal of Eternal Memory itu memiliki fungsi lain yang bisa kita gunakan, Jakine? Bisakah kita menggunakannya untuk memanipulasi ilusi lain, seperti Iblis Putih?",
  ui_story_5053_50531401_71_dialog_content = "Hmm... Tidak! Dengan sedikit Lumina yang tersisa, Crystal of Eternal Memory tidak dapat digunakan untuk apa pun selain mempertahankan dunia di sekitar kita.",
  ui_story_5053_50531401_72_dialog_content = "Juga, Crystal of Eternal Memory ini hanyalah perangkat yang aman dari kegagalan.",
  ui_story_5053_50531401_73_dialog_content = "Itu seharusnya tidak pernah digunakan terlalu banyak sejak awal... Kita sudah cukup banyak melanggar peraturan sejak kita mendapatkannya.",
  ui_story_5053_50531401_74_dialog_content = "Tapi jika aku berhasil mengumpulkan mantra yang lebih baik dari sebelumnya...!",
  ui_story_5053_50531401_75_dialog_content = "TIDAK, Jakine. Situasi kami terlalu buruk bagi kami untuk menggunakan mantra improvisasi Anda yang lain.",
  ui_story_5053_50531401_76_dialog_content = "Ehehehe... Mengerti.",
  ui_story_5053_50531401_77_dialog_content = "Tidak usah.",
  ui_story_5053_50531401_78_dialog_content = "Yang perlu kita lakukan hanyalah membiarkan mereka menghancurkan diri mereka sendiri.",
  ui_story_5053_50531401_79_dialog_content = "Selamat datang kembali, Kaleb! Apakah kalian semua sudah selesai menangis sekarang?",
  ui_story_5053_50531401_80_dialog_content = "Aku tidak menangis! Beraninya kau memperlakukanku seperti anak kecil!",
  ui_story_5053_50531401_81_dialog_content = "Apa maksudmu dengan itu, Kaleb? Mengapa mereka menghancurkan diri mereka sendiri jika mereka semua berada di bawah kendali Iblis Putih?",
  ui_story_5053_50531401_82_dialog_content = "Ini sederhana, sungguh.",
  ui_story_5053_50531401_83_dialog_content = "Dengan mengganggu keseimbangan Lumina di tubuh mereka, mereka akan kehilangan kemampuan untuk mengendalikan diri. Menyakitkan, saya bisa menambahkan.",
  ui_story_5053_50531401_84_dialog_content = "\"Keseimbangan Lumina\"? Saya belum pernah mendengar hal seperti itu sebelumnya.",
  ui_story_5053_50531401_85_dialog_content = "Hmph, orang Aurorian biasa tidak akan pernah mengerti, tapi aku yakin teman Caelestite kita tahu persis apa yang kubicarakan. Bukankah itu benar?",
  ui_story_5053_50531401_86_dialog_content = "A-Aku? Uh... Yah, aku melihat sesuatu yang berbeda tentang jejak cahaya mereka...",
  ui_story_5053_50531401_87_dialog_content = "Tanggapan Anda yang meragukan adalah... Cukup mengecewakan.",
  ui_story_5053_50531401_88_dialog_content = "<size=30>PlayerName, Saya merasa Caleb semakin memusuhi kami sebelumnya. Mungkin dia sebenarnya orang yang busuk?</size>",
  ui_story_5053_50531401_89_dialog_content = "<size=30>Yah, tidak ada komentar ...</size>",
  ui_story_5053_50531401_90_dialog_content = "Kalian berdua! Tidak ada obrolan saat kelas sedang berlangsung!",
  ui_story_5053_50531401_91_dialog_content = "Cukup bermain-main, Caleb. Beri tahu kami rencana Anda.",
  ui_story_5053_50531401_92_dialog_content = "Saya bisa menyiapkan jenis obat tertentu, ramuan yang bisa mengacaukan Lumina pengguna. Anggap saja sebagai racun yang langsung menargetkan Lumina.",
  ui_story_5053_50531401_93_dialog_content = "Segala sesuatu di dalam Crystal of Eternal Memory diciptakan melalui kombinasi Lumina milik Joshua dan air Danau Cermin.",
  ui_story_5053_50531401_94_dialog_content = "Akibatnya, obat ini terbukti sangat efektif melawan musuh kita.",
  ui_story_5053_50531401_95_dialog_content = "Tapi dengan begitu sedikit bahan di tangan, saya mengusulkan agar kita menggunakannya untuk melawan naga.",
  ui_story_5053_50531401_96_dialog_content = "Boneka yang dikendalikan pikiran Iblis Putih tidak lebih dari semut perusak. Jika kita membawa naga ke atas mereka...",
  ui_story_5053_50531401_97_dialog_content = "Rasa sakit yang disebabkan oleh obat akan menyebabkannya terinjak-injak dan menggeliat di tanah, menghancurkan musuh kita dalam prosesnya.",
  ui_story_5053_50531401_98_dialog_content = "Aha! Jadi, dengan kata lain, jika kita berhasil memberi racun ke naga, itu akan jatuh menimpa kepala mereka yang tidak punya pikiran!",
  ui_story_5053_50531401_99_dialog_content = "... Dengan cara berbicara, ya.",
  ui_story_5053_50531401_100_dialog_content = "Saya harus mengatakan, rencana Anda cukup menunjukkan gaya Anda yang biasa. Anda selalu menyukai trik sederhana namun menyeramkan seperti ini.",
  ui_story_5053_50531401_101_dialog_content = "Aku heran kau masih ingat itu, my lord. Apakah secangkir teh saya benar-benar berkesan?",
  ui_story_5053_50531401_102_dialog_content = "(Tunggu... Apakah Caleb meracuni Lord Schwartz di masa lalu?!)",
  ui_story_5053_50531401_103_dialog_content = "<size=30>Kamu benar-benar bukan orang baik, Caleb!</size>",
  ui_story_5053_50531401_104_dialog_content = "Pfftt... Hehehe...",
  ui_story_5053_50531401_105_dialog_content = "Berhenti tertawa, Mia.",
  ui_story_5053_50531401_106_dialog_content = "Maafkan aku, aku tidak bisa menahannya... Tunggu, aku tidak bermaksud seperti itu...",
  ui_story_5053_50531401_107_dialog_content = "Saya hanya punya cukup bahan untuk membuat satu ramuan. Aku membutuhkan seseorang yang kuat untuk menaklukkan naga itu cukup lama agar aku bisa memberikan ramuannya. Seseorang sepertimu.",
  ui_story_5053_50531401_108_dialog_content = "H-Hah? Aku...?!",
  ui_story_5053_50531401_109_dialog_content = "Iya kamu. Sekarang ikuti saya.",
  ui_story_5053_50531401_110_dialog_content = "T-Tunggu, paman...!",
  ui_story_5053_50531401_111_dialog_content = "Itu dia, lari untuk melakukan urusannya sendiri lagi! Pikirkan kita harus mengikuti mereka?",
  ui_story_5053_50531401_112_dialog_content = "Serahkan naga itu pada Caleb. Saya percaya padanya, juga Mia.",
  ui_story_5053_50531401_113_dialog_content = "Lord Schwartz...",
  ui_story_5053_50531401_114_dialog_content = "Menurutmu, aku selalu berhasil selamat dari rencana Iblis Putih sampai akhir, tapi aku tidak pernah bisa mengubah hasilnya.",
  ui_story_5053_50531401_115_dialog_content = "Kalian para pahlawan muda, di sisi lain, jauh lebih mampu membentuk masa depan daripada aku.",
  ui_story_5053_50531401_116_dialog_content = "Aku selalu berpikir aku bisa melindungi semuanya dengan kedua tanganku sendiri... Tapi sepertinya sudah tiba waktunya untuk melepaskan harga diriku yang membandel.",
  ui_story_5053_50531401_117_dialog_content = "Jadi haruskah kita tinggal di sini untuk saat ini?",
  ui_story_5053_50531401_118_dialog_content = "Ya, Jakine. Kami akan tetap di sini untuk mengumpulkan akal dan kekuatan kami.",
  ui_story_5053_50531401_119_dialog_content = "Mengetahui Iblis Putih, dia akan muncul di hadapan kita untuk satu pertempuran terakhir setelah kartu trufnya dikalahkan.",
  ui_story_5053_50531401_120_dialog_content = "Itulah jenis lawan ulet yang kita hadapi.",
  ui_story_5053_50531401_121_dialog_content = "Lalu…",
  ui_story_5053_50531401_122_dialog_content = "...",
  ui_story_5053_50531401_123_dialog_content = "Aku masih perlu meyakinkan dia untuk pergi bersama kami.",
  ui_story_5053_50531401_125_dialog_content = "Jadi kita menemukan diri kita di sini sekali lagi. Anda dan saya, berdiri di meja ini di malam hari.",
  ui_story_5053_50531401_126_dialog_content = "...",
  ui_story_5053_50531401_127_dialog_content = "Terakhir kali ini terjadi, saya mencoba mengubah hasil dari perselisihan kami dengan berpura-pura menjadi diri saya yang lebih muda.",
  ui_story_5053_50531401_128_dialog_content = "Saya mengatakan bahwa saya tidak ingin menyakiti Anda lagi, tetapi di dunia ilusi ini, tindakan saya mengejar kepuasan diri dan tidak lebih.",
  ui_story_5053_50531401_129_dialog_content = "Ironisnya, Anda berdiri di hadapan saya sepanjang waktu, menyaksikan saya dalam keadaan terburuk saya. Tidak heran kau begitu marah padaku.",
  ui_story_5053_50531401_130_dialog_content = "D... Daniel...",
  ui_story_5053_50531401_131_dialog_content = "Kamu benar. Ini semua salahku, dan balas dendammu terhadapku sangat dibenarkan. Namun, Anda belum bisa membunuh saya dulu.",
  ui_story_5053_50531401_132_dialog_content = "Anak-anak ini tidak bersalah, dan tidak pantas mati di tempat ini.",
  ui_story_5053_50531401_133_dialog_content = "Jadi tolong, bantu kami menangkap separuh lainnya agar kami dapat melarikan diri. Apa yang kamu katakan?",
  ui_story_5053_50531401_134_dialog_content = "Anak-anak adalah... masa depan... Kita harus... melindungi masa depan...",
  ui_story_5053_50531401_135_dialog_content = "Lalu kita sepakat. Terima kasih, Joshua... Terima kasih telah mempercayai saya sekali lagi.",
  ui_story_5053_50531401_136_dialog_content = "...",
  ui_story_5053_50531401_137_dialog_content = "Kaleb dan Mia baru saja pergi. Kita harus mencoba mendapatkan kembali kekuatan kita untuk saat ini.",
  ui_story_5053_50531401_138_dialog_content = "Apakah Anda masih ingat lagu itu, Joshua?",
  ui_story_5053_50531401_139_dialog_content = "Ya... Lagu dari... Lumopolis Bawah... tentang... hidup bahagia...",
  ui_story_5053_50531401_140_dialog_content = "Ya, lagu itu. Sejujurnya, saya menyiapkan hadiah untuk Anda dua belas tahun yang lalu.",
  ui_story_5053_50531401_141_dialog_content = "Tapi di saat panas, aku lupa memberikannya padamu. Jika saya ingat dengan benar... Seharusnya ada di sini.",
  ui_story_5053_50531401_142_dialog_content = "Rekor?",
  ui_story_5053_50531401_143_dialog_content = "Itu benar. Saya meminta seseorang merekam versi tarian dari lagu yang sama. Apakah Anda ingin mendengarkannya? Lagi pula, ada pemutar rekaman di sini.",
  ui_story_5053_50531401_144_dialog_content = "<color=#e8d9bb>...♪</color>",
  ui_story_5053_50531401_145_dialog_content = "…!",
  ui_story_5053_50531401_146_dialog_content = "Aku senang melihatmu menikmatinya, Joshua.",
  ui_story_5053_50531401_147_dialog_content = "Tapi akan sia-sia untuk hanya mendengarkan lagu yang begitu indah.",
  ui_story_5053_50531401_148_dialog_content = "Nah, wanita cantik saya? May Saya memiliki tarian ini?",
  ui_story_5053_50531401_149_dialog_content = "...",
  ui_story_5053_50531401_150_dialog_content = "...",
  ui_story_5053_50531401_151_dialog_content = "Da... Daniel...",
  ui_story_5053_50531401_152_dialog_content = "Ya?",
  ui_story_5053_50531401_153_dialog_content = "Apakah semuanya... Baik-baik saja...?",
  ui_story_5053_50531401_154_dialog_content = "...Ya, cukup baik.",
  ui_story_5053_50531401_155_dialog_content = "Carleen sekarang menjadi Kapten Penjaga Lumopolis, dan memimpin tim bawahan yang patut dicontoh. Tidak hanya itu, dia juga memiliki banyak teman yang dapat dipercaya.",
  ui_story_5053_50531401_156_dialog_content = "Mia terus hidup di bawah asuhan dan bimbingan Istvan. Kondisinya telah meningkat pesat; Saya mendengar dia bahkan bisa pergi keluar dan bermain di siang hari sekarang.",
  ui_story_5053_50531401_157_dialog_content = "Adapun Caleb ... Dia tampaknya melakukannya dengan cukup baik untuk dirinya sendiri di Dawn Akademi. Saya berani bertaruh bahwa dia sangat merindukanmu daripada siapa pun di dunia ini.",
  ui_story_5053_50531401_158_dialog_content = "Bagaimana denganmu...?",
  ui_story_5053_50531401_159_dialog_content = "Aku?",
  ui_story_5053_50531401_160_dialog_content = "Waktuku sudah habis sekarang, Joshua.",
  ui_story_5053_50531401_161_dialog_content = "Saya sangat tidak berdaya di masa lalu, dan saya membuat lebih banyak kesalahan daripada yang dapat saya hitung, tetapi sekarang. Sekarang, anak-anak kami berdiri di atas bahu saya, mencapai ketinggian yang lebih tinggi daripada yang pernah saya ketahui.",
  ui_story_5053_50531401_162_dialog_content = "Yang harus saya lakukan hanyalah berdiri di tempat ini, mendukung mereka saat mereka berjuang untuk masa depan yang lebih cerah.",
  ui_story_5053_50531401_163_dialog_content = "Masa depan ideal yang selalu Anda dan saya impikan.",
  ui_story_5053_50531401_164_dialog_content = "Ketika kita kembali, saya dapat mengatur agar Anda pulih dengan aman dan privasi di rumah Caleb.",
  ui_story_5053_50531401_165_dialog_content = "Setelah itu, saya akan meminta Veronica kembali untuk menemani Anda, dan berbagi kabar baik Carleen. Sebentar lagi, keluarga kami akan utuh kembali.",
  ui_story_5053_50531401_166_dialog_content = "Hanya sekarang... Nah, seperti yang Anda lihat, saya sudah agak tua. Saya mungkin bahkan kurang layak untuk ditemani Anda sekarang, tetapi saya akan berterima kasih jika Anda mengizinkan saya untuk berkunjung dari waktu ke waktu. Apakah itu baik-baik saja?",
  ui_story_5053_50531401_167_dialog_content = "Ingin... Rumah...",
  ui_story_5053_50531401_168_dialog_content = "Yosua?",
  ui_story_5053_50531401_169_dialog_content = "Aku ingin pulang...",
  ui_story_5053_50531401_170_dialog_content = "Aku tahu. Aku berjanji kita akan pulang bersama.",
  ui_story_5053_50531401_171_dialog_content = "Joshua... Apakah Anda menyesali pernikahan kami?",
  ui_story_5053_50531401_172_dialog_content = "Menyimpan begitu banyak kemarahan dan rasa sakit yang tersembunyi di hatimu... Apa kau menyesal memilihku menjadi suamimu?",
  ui_story_5053_50531401_173_dialog_content = "Anda mengajari saya ... kebahagiaan dan cinta.",
  ui_story_5053_50531401_174_dialog_content = "Kebencian... adalah sisi lain... dari cinta.",
  ui_story_5053_50531401_175_dialog_content = "Kebencian itu... menyakitkan... tapi itu... lahir dari cinta... Jadi aku... tidak menyesal.",
  ui_story_5053_50531401_176_dialog_content = "...",
  ui_story_5053_50531401_177_dialog_content = "Benarkah?",
  ui_story_5053_50531401_178_dialog_content = "Oh, begitu…",
  ui_story_5053_50531401_179_dialog_content = "Poin lima dan enam sekarang dipersenjatai...",
  ui_story_5053_50531401_180_dialog_content = "Bagus. Sekarang satu-satunya yang hilang adalah detonator, dan bom kita akan siap untuk memancing naga.",
  ui_story_5053_50531401_181_dialog_content = "Bagaimana dengan bahan peledaknya, Tn. Caleb? Apakah Anda memerlukan bantuan saya?",
  ui_story_5053_50531401_182_dialog_content = "Sama sekali tidak. Saya sudah selesai merakitnya.",
  ui_story_5053_50531401_183_dialog_content = "Dalam waktu sesingkat itu, tidak kurang. Sangat mengesankan, Pak.",
  ui_story_5053_50531401_184_dialog_content = "Tidak perlu sanjungan di antara kerabat, Ms. Rot. Selain itu, jika ada yang pantas dipuji, itu kamu.",
  ui_story_5053_50531401_185_dialog_content = "Tanpa Anda, para penjaga ini tidak akan pernah mengizinkan kami melakukan persiapan yang begitu rumit.",
  ui_story_5053_50531401_186_dialog_content = "Saya hanya menjalankan tugas saya. Apakah Anda yakin tidak satu pun dari Anda membutuhkan bantuan saya?",
  ui_story_5053_50531401_187_dialog_content = "Sebagai ilusi yang diciptakan oleh Crystal of Eternal Memory, aku jauh lebih cocok untuk menahan musuh.",
  ui_story_5053_50531401_188_dialog_content = "Tolong jangan katakan itu, Ms. Rot...",
  ui_story_5053_50531401_189_dialog_content = "Namun, saya memiliki sesuatu yang penting yang ingin saya tanyakan kepada Anda.",
  ui_story_5053_50531401_190_dialog_content = "Saya atas perintah Anda, Yang Mulia.",
  ui_story_5053_50531401_191_dialog_content = "Bisakah Anda tetap di sisi Carleen di tempat saya? Dia sendirian sekarang, dan aku yakin itu akan menenangkan pikirannya.",
  ui_story_5053_50531401_192_dialog_content = "Mau mu. Tapi pertama-tama, saya harus bertanya ...",
  ui_story_5053_50531401_193_dialog_content = "Mengapa Anda begitu peduli dengan keselamatan kami, meskipun faktanya tidak satu pun dari kami yang nyata?",
  ui_story_5053_50531401_194_dialog_content = "Tidak, Nona Rot... Kalian semua masih sangat nyata bagiku. Anda masing-masing adalah cerminan dari seseorang yang sangat saya sayangi. Anda berbagi wajah mereka, kepribadian mereka... Bahkan ingatan mereka.",
  ui_story_5053_50531401_195_dialog_content = "Meskipun kamu hanya ada di dalam kristal ini, aku tetap peduli padamu dengan cara yang persis sama.",
  ui_story_5053_50531401_196_dialog_content = "Di mata saya, kepedulian kami satu sama lain itulah yang membuat interaksi kami nyata.",
  ui_story_5053_50531401_197_dialog_content = "Selain itu, saya menolak untuk melihat orang lain sebagai tidak penting, atau bahkan dibuang ...",
  ui_story_5053_50531401_198_dialog_content = "Saya khawatir jika saya melakukannya, saya akan kehilangan pandangan tentang diri saya sebagai pribadi.",
  ui_story_5053_50531401_199_dialog_content = "Kamu selalu mirip dengan ibumu, Putri Veronica, tapi sekarang... Aku hampir tidak bisa membedakanmu.",
  ui_story_5053_50531401_200_dialog_content = "I-Begitukah...?",
  ui_story_5053_50531401_201_dialog_content = "Persiapan akhirnya selesai! Sudah waktunya, Mia!",
  ui_story_5053_50531401_202_dialog_content = "Dipahami! Tolong jaga baik-baik Carleen, Nona Rot!",
  ui_story_5053_50531401_203_dialog_content = "Sepertinya doaku terkabul. Masa depan dari Schwartz keluarga seterang matahari itu sendiri.",
  ui_story_5053_50531401_204_dialog_content = "*tarik napas* wah...",
  ui_story_5053_50531401_205_dialog_content = "Segera setelah saya menekan tombol ini, bom akan meledak secara berurutan, yang akan menarik naga ke lokasi kami dalam waktu kurang dari dua puluh detik.",
  ui_story_5053_50531401_206_dialog_content = "Apakah kamu siap, Mia?",
  ui_story_5053_50531401_207_dialog_content = "K-kurasa begitu...",
  ui_story_5053_50531401_208_dialog_content = "Sigh... Setelah semua yang kita lalui, bagaimana kamu masih tidak percaya diri?",
  ui_story_5053_50531401_209_dialog_content = "Dapatkan bersama!",
  ui_story_5053_50531401_210_dialog_content = "M-Maaf! Um... May Aku bertanya sesuatu padamu, paman?",
  ui_story_5053_50531401_211_dialog_content = "Buatlah singkat.",
  ui_story_5053_50531401_212_dialog_content = "Mengapa Anda memilih saya untuk membantu Anda dengan bagian rencana ini?",
  ui_story_5053_50531401_213_dialog_content = "Jika Anda membutuhkan seseorang yang kuat, Ayah atau Ibu Rot akan menjadi pilihan yang lebih baik daripada saya.",
  ui_story_5053_50531401_214_dialog_content = "Oh? Dan apa yang membuatmu mengatakan itu?",
  ui_story_5053_50531401_215_dialog_content = "Petualangan kita sejauh ini telah memberiku pemahaman yang jelas tentang kekuatanmu, Mia. Selain itu, saya telah diberitahu bahwa Anda mampu memanggil familiar Lumina. Benarkah itu?",
  ui_story_5053_50531401_216_dialog_content = "Jika demikian, Anda memiliki mobilitas tertinggi di antara kami, yang menjadikan Anda kandidat yang sempurna untuk paket ini.",
  ui_story_5053_50531401_217_dialog_content = "MM-Familiarku?!",
  ui_story_5053_50531401_218_dialog_content = "Tapi aku baru memanggil Hippoca beberapa kali sampai sekarang! Aku masih belum pandai menungganginya...",
  ui_story_5053_50531401_219_dialog_content = "\"Beberapa kali,\" katamu? Mengapa Anda menyia-nyiakan hadiah yang langka dan berharga seperti itu ?!",
  ui_story_5053_50531401_220_dialog_content = "Y-Yah... Penampilan Hippoca bisa sedikit meresahkan. Ketika saya pertama kali memanggilnya, semua orang takut pada Hippoca dan mengatakan bahwa keberadaannya adalah pertanda buruk.",
  ui_story_5053_50531401_221_dialog_content = "T-Tapi aku tidak merasa seperti itu tentang dia lagi! Saya tidak akan meragukan diri saya sendiri karena apa yang orang lain katakan lagi!",
  ui_story_5053_50531401_222_dialog_content = "Tetap saja, sebenarnya Hippoca dan aku baru bertarung bersama beberapa kali... Karena itulah aku merasa tidak percaya diri...",
  ui_story_5053_50531401_223_dialog_content = "Jika kita gagal, maka hidup semua orang akan...",
  ui_story_5053_50531401_224_dialog_content = "Ah... aku mengerti. Itu perbuatan Schwartz, bukan?",
  ui_story_5053_50531401_225_dialog_content = "...",
  ui_story_5053_50531401_226_dialog_content = "Dia melarangmu memanggil familiarmu, semua karena para bangsawan yang suka bergosip itu.",
  ui_story_5053_50531401_227_dialog_content = "Apakah dia dengan jujur berpikir bahwa Anda akan diselamatkan dari kritik dengan mencegah Anda memanggil Hippoca?",
  ui_story_5053_50531401_228_dialog_content = "Hah? T-Tidak paman, ayah hanya berusaha melindungiku... Bukankah begitu?",
  ui_story_5053_50531401_229_dialog_content = "<size=45>Bodoh itu! Benar-benar bodoh!</size>",
  ui_story_5053_50531401_230_dialog_content = "Apa…?!",
  ui_story_5053_50531401_231_dialog_content = "Dengarkan aku, Mia! Para bangsawan bodoh itu hanya mengatakan itu karena mereka iri padamu! Semakin luar biasa Anda, semakin mereka mencoba menyeret Anda melewati kotoran!",
  ui_story_5053_50531401_232_dialog_content = "Itulah mengapa Anda tidak harus mendengarkan mereka atau ayah Anda! Jika mereka menyuruh Anda untuk tidak melakukan sesuatu, itulah alasan mengapa Anda harus melakukannya! Kehidupan seorang jenius penuh dengan rintangan!!",
  ui_story_5053_50531401_233_dialog_content = "\"Kehidupan seorang jenius\"?! T-Tapi aku masih berpikir kita harus mendengarkan orang lain, terutama keluarga kita...",
  ui_story_5053_50531401_234_dialog_content = "Tidak benar, Mia. Itulah yang mereka ingin Anda pikirkan, sehingga mereka dapat terus menahan Anda. Mari saya tunjukkan jalannya.",
  ui_story_5053_50531401_235_dialog_content = "Anda harus melepaskan setiap ons kekuatan Anda, di sini dan sekarang! Biarkan mengalir melalui setiap sel di tubuh Anda, dan lepaskan semuanya sekaligus!",
  ui_story_5053_50531401_236_dialog_content = "Hah...?!",
  ui_story_5053_50531401_237_dialog_content = "Hanya obat yang paling ampuh yang akan menyembuhkanmu dari ketundukan yang menyebalkan itu, Mia.",
  ui_story_5053_50531401_238_dialog_content = "Dan hanya dengan memahami sepenuhnya kekuatan Anda, Anda akan belajar mengendalikannya.",
  ui_story_5053_50531401_239_dialog_content = "Seluruh kekuatanku...",
  ui_story_5053_50531401_240_dialog_content = "(Orang cenderung takut pada apa yang tidak mereka pahami. Dalam hal itu, saya tidak berbeda dengan orang lain.)",
  ui_story_5053_50531401_241_dialog_content = "(Metode Paman mungkin tampak sedikit ekstrim... Tapi dia benar. Aku perlu mengetahui kedalaman sebenarnya dari kekuatanku sendiri.)",
  ui_story_5053_50531401_242_dialog_content = "Tenang, saya berjanji untuk membuat Anda tetap aman saat Anda melakukannya. Anda tidak mengira saya hanyalah sarjana lemah, bukan?",
  ui_story_5053_50531401_243_dialog_content = "I-Pikiran itu tidak pernah terlintas di benakku. Baiklah, paman... Aku akan melakukan yang terbaik!",
  ui_story_5053_50531401_244_dialog_content = "Bagus sekali!",
  ui_story_5053_50531401_245_dialog_content = "Sekarang bersiaplah untuk pertempuran!",
  ui_story_5053_50531501_1_dialog_content = "<color=#e8d9bb>Mengaum-</color>",
  ui_story_5053_50531501_2_dialog_content = "Raungan yang mengerikan! Kami bisa mendengarnya sampai ke sini!",
  ui_story_5053_50531501_3_dialog_content = "Sudah tiga menit sejak ledakan pertama. Dua api berwarna berbeda bertarung di langit sana.",
  ui_story_5053_50531501_4_dialog_content = "Yang biru adalah Mia, dan yang merah adalah naga...",
  ui_story_5053_50531501_5_dialog_content = "Lihat! Api merah akan turun! Mia dan Caleb melakukannya!",
  ui_story_5053_50531501_6_dialog_content = "Sepertinya kita datang di saat yang tepat.",
  ui_story_5053_50531501_7_dialog_content = "Yang mulia Schwartz! Aku baru saja akan datang dan memberitahumu!",
  ui_story_5053_50531501_8_dialog_content = "Jadi apakah kalian berdua siap untuk bernegosiasi?",
  ui_story_5053_50531501_9_dialog_content = "Ya, dan sekarang keadaan telah berubah...",
  ui_story_5053_50531501_10_dialog_content = "Yang tersisa hanyalah melihat di mana ratu musuh membuat langkah terakhirnya.",
  ui_story_5053_50531501_11_dialog_content = "... Di Sini...",
  ui_story_5053_50531501_12_dialog_content = "Hah? Apa maksudmu, \"di sini\"?",
  ui_story_5053_50531501_13_dialog_content = "Di sini... Dia di sini...!",
  ui_story_5053_50531501_14_dialog_content = "I-Tanah berguncang dan terbelah!! Apakah ini perbuatan Iblis Putih?!",
  ui_story_5053_50531501_15_dialog_content = "PlayerName!",
  ui_story_5053_50531501_16_dialog_content = "Ledakan! Apa yang sebenarnya terjadi?!",
  ui_story_5053_50531501_17_dialog_content = "Mia? Kaleb? Apa yang kalian berdua lakukan kembali begitu cepat? Bukankah kamu baru saja selesai membunuh naga?",
  ui_story_5053_50531501_18_dialog_content = "Tidak, dan kami juga tidak sepenuhnya yakin apa yang terjadi.",
  ui_story_5053_50531501_19_dialog_content = "Ketika naga jatuh dari langit, alun-alun pusat mulai melengkung dan pecah. Selain paman saya dan saya sendiri ...",
  ui_story_5053_50531501_20_dialog_content = "Semua orang di area itu berubah menjadi kilatan cahaya putih dan terbang ke langit.",
  ui_story_5053_50531501_21_dialog_content = "Ketika kami mencoba melarikan diri melalui pintu depan seseorang, kami tiba-tiba menemukan diri kami kembali ke mansion.",
  ui_story_5053_50531501_22_dialog_content = "Zzzzz...",
  ui_story_5053_50531501_23_dialog_content = "Bangun, Jakine! Sesuatu yang mengerikan sedang terjadi!",
  ui_story_5053_50531501_24_dialog_content = "Zzzzz... Hah? Siapa disana?! Jauhkan tanganmu dari kristalku!!!",
  ui_story_5053_50531501_25_dialog_content = "H-Hei... Apa yang terjadi dengan Crystal of Eternal Memory?!",
  ui_story_5053_50531501_26_dialog_content = "Ke... Kenapa...",
  ui_story_5053_50531501_27_dialog_content = "Mengapa Anda memilih untuk berpihak pada makhluk menjijikkan itu...?",
  ui_story_5053_50531501_28_dialog_content = "Ibu... Wajahmu...",
  ui_story_5053_50531501_29_dialog_content = "Lihatlah retakan muncul di wajahnya! Warnanya sama dengan Dark Angel!",
  ui_story_5053_50531501_30_dialog_content = "Kenapa kamu tidak memilihku...?",
  ui_story_5053_50531501_31_dialog_content = "Mengapa tidak ada yang mengerti pentingnya cita-cita saya...?",
  ui_story_5053_50531501_32_dialog_content = "<size=45>MENGAPA?!?</size>",
  ui_story_5053_50531501_33_dialog_content = "Di-Dia berubah menjadi Kegelapan Angel!!",
  ui_story_5053_50531501_34_dialog_content = "Jadi Mia itu benar! Dua2nya sama...",
  ui_story_5053_50531501_35_dialog_content = "Kira kita tidak punya waktu untuk membahas penyerahannya atas teh dan kue! Ayo tangkap dia!",
  ui_story_5053_50531501_36_dialog_content = "M-Ibu... Maafkan aku!",
  ui_story_5053_50531501_37_dialog_content = "Yosua...",
  ui_story_5053_50531501_38_dialog_content = "Apakah Anda ragu-ragu sekarang sepanjang waktu, Caleb?",
  ui_story_5053_50531501_39_dialog_content = "Bahkan putri sulung saya menunjukkan keberanian lebih dari Anda sekarang.",
  ui_story_5053_50531501_40_dialog_content = "Simpan, Schwartz! Ketika menyangkut masalah saudara perempuan saya, Anda sendiri tidak berhak menyalahkan siapa pun!",
  ui_story_5053_50531501_41_dialog_content = "Tunggu saja sampai kita kembali ke dunia nyata!",
  ui_story_5053_50531501_42_dialog_content = "(Bocah bodoh. Bahkan setelah bertahun-tahun, kamu masih tidak bisa mengendalikan amarahmu.)",
  ui_story_5053_50531501_43_dialog_content = "...",
  ui_story_5053_50531502_1_dialog_content = "Urgh...!!",
  ui_story_5053_50531502_2_dialog_content = "Jakine!",
  ui_story_5053_50531502_3_dialog_content = "Di depanmu!!",
  ui_story_5053_50531502_4_dialog_content = "M-mundur...",
  ui_story_5053_50531502_5_dialog_content = "Ini sudah berakhir, Joshua.",
  ui_story_5053_50531502_6_dialog_content = "Jangan mendekat...!",
  ui_story_5053_50531502_7_dialog_content = "Berjuang hanya akan membuatnya semakin menyakitkan.",
  ui_story_5053_50531502_8_dialog_content = "Tinggal jauh dari saya!!!",
  ui_story_5053_50531502_9_dialog_content = "Yang mulia Schwartz!",
  ui_story_5053_50531502_10_dialog_content = "<size=45>Pedang Penguasa—</size>",
  ui_story_5053_50531502_11_dialog_content = "Uwaaaaa!!",
  ui_story_5053_50531502_12_dialog_content = "Ini semua...salahmu...",
  ui_story_5053_50531502_13_dialog_content = "...",
  ui_story_5053_50531502_14_dialog_content = "Kamu... Membuatku lemah...",
  ui_story_5053_50531502_15_dialog_content = "Veronica dan Carleen... Caleb dan Blanc... Dan Schwartz.",
  ui_story_5053_50531502_16_dialog_content = "Mereka sampah pengkhianat, semuanya!!",
  ui_story_5053_50531502_17_dialog_content = "Bagaimana Anda bisa menyerahkan cita-cita Anda kepada mereka ?! Anda tidak berharga, rusak bodoh—",
  ui_story_5053_50531502_18_dialog_content = "Mia, bantu saya menyelesaikan ini. Kita tidak bisa membiarkan adikku terus menyakiti dirinya sendiri.",
  ui_story_5053_50531502_19_dialog_content = "Baiklah…",
  ui_story_5053_50531502_20_dialog_content = "Tunggu! Jangan mendekatinya!",
  ui_story_5053_50531502_21_dialog_content = "Jika harus berakhir seperti ini... Maka atas nama balas dendam...",
  ui_story_5053_50531502_22_dialog_content = "Aku bersumpah untuk memusnahkan kalian semua...",
  ui_story_5053_50531502_23_dialog_content = "...Hah? Ada apa dengan angin ini?",
  ui_story_5053_50531502_24_dialog_content = "Lihat! Dia mulai menyerap Lumina di dalam Crystal of Eternal Memory!",
  ui_story_5053_50531502_25_dialog_content = "Apa dia... Mencoba menjatuhkan kita bersamanya?!",
  ui_story_5053_50531502_26_dialog_content = "Jakine, bersiaplah untuk mengeluarkan kami dari sini! Kalian semua, bantu aku menaklukkannya!",
  ui_story_5053_50531502_27_dialog_content = "Apa? Maksudmu sekarang?!",
  ui_story_5053_50531502_28_dialog_content = "Anda berencana membawa saudara perempuan saya kembali ke negara bagian ini ?!",
  ui_story_5053_50531502_29_dialog_content = "Jika Joshua menyakiti salah satu dari kalian, itu hanya akan menghancurkan hatinya.",
  ui_story_5053_50531502_30_dialog_content = "Semua yang menentang cita-cita saya harus binasa! Mati kau pengkhianat kotor!!!",
  ui_story_5053_50531502_31_dialog_content = "Kenapa harus begini, Bunda? Bisakah Anda benar-benar memiliki banyak kebencian di hati Anda terhadap kami...?",
  ui_story_5053_50531502_32_dialog_content = "Vonnie... Jangan sedih...",
  ui_story_5053_50531502_33_dialog_content = "Tinggalkan ini... Untukku...",
  ui_story_5053_50531502_34_dialog_content = "Ibu...?",
  ui_story_5053_50531502_35_dialog_content = "Argh, serangan kita tidak berguna! Mia, berhenti berdiri dan fokus pada pertempuran!",
  ui_story_5053_50531502_36_dialog_content = "... Joshua? Tunggu, apa yang kamu lakukan?! Jangan mendekati separuh lainnya!!",
  ui_story_5053_50531502_37_dialog_content = "... Percayalah padanya, Caleb.",
  ui_story_5053_50531502_38_dialog_content = "Biarkan aku pergi, Schwartz! Jangan mencoba menghentikanku! Joshua!!!",
  ui_story_5053_50531502_39_dialog_content = "Angin terlalu kencang untuk membuka mata! Aku tidak bisa menggunakan Crystal of Eternal Memory seperti ini!",
  ui_story_5053_50531502_40_dialog_content = "H-Hah?! IIII aku terpesona! Tolong aku-",
  ui_story_5053_50531502_41_dialog_content = "Jakine!",
  ui_story_5053_50531502_42_dialog_content = "Wah, terima kasih PlayerName... Hah?",
  ui_story_5053_50531502_43_dialog_content = "Jangan takut... Semuanya sudah berakhir sekarang.",
  ui_story_5053_50531502_44_dialog_content = "Ingatlah untuk berpegangan erat satu sama lain kali ini, semuanya.",
  ui_story_5053_50531502_45_dialog_content = "J-Joshua...?",
  ui_story_5053_50531502_46_dialog_content = "Ibu... Itu kamu...",
  ui_story_5053_50531502_47_dialog_content = "TIDAK! Tetap kembali...",
  ui_story_5053_50531502_48_dialog_content = "Cukup. Sudah waktunya untuk membiarkan semua orang pulang sekarang.",
  ui_story_5053_50531502_49_dialog_content = "TIDAK! Jangan dekati aku... Noooo!!!",
  ui_story_5053_50531502_50_dialog_content = "<size=50>Joshua!!!</size>",
  ui_story_5053_50531601_1_dialog_content = "Akhirnya aku menemukanmu.",
  ui_story_5053_50531601_2_dialog_content = "Itu kamu...! TIDAK! Menjauh dari saya!",
  ui_story_5053_50531601_3_dialog_content = "Apakah Anda benar-benar merasa jijik dengan saya?",
  ui_story_5053_50531601_4_dialog_content = "Tentu saja! Pernahkah Anda melihat diri Anda di cermin akhir-akhir ini? Siapa yang tahan melihat seseorang yang begitu mengerikan, apalagi mencintai mereka ?!",
  ui_story_5053_50531601_5_dialog_content = "Begitu ya... Dulu aku juga merasa seperti itu.",
  ui_story_5053_50531601_6_dialog_content = "Tetapi ketika saya melihat betapa keluarga dan teman-teman saya sangat memperhatikan saya, saya mulai melupakan kebencian diri saya dan mencintai diri saya lagi.",
  ui_story_5053_50531601_7_dialog_content = "Betapa menjijikkan...",
  ui_story_5053_50531601_8_dialog_content = "Pernahkah Anda melihat diri Anda di cermin juga?",
  ui_story_5053_50531601_9_dialog_content = "Saya memiliki. Saya biasa berlatih mengendalikan ekspresi saya di depan cermin selama tiga jam setiap hari. Aku tidak punya alasan untuk menatap diriku sendiri lagi.",
  ui_story_5053_50531601_10_dialog_content = "Itu benar, kamu selalu menjadi pejuang yang pemberani dan tak kenal takut, seseorang yang akan melakukan apa saja untuk mewujudkan cita-citanya.",
  ui_story_5053_50531601_11_dialog_content = "Tetapi setiap orang memiliki sesuatu yang mereka takuti, dan Anda tidak terkecuali. Untukmu...",
  ui_story_5053_50531601_12_dialog_content = "Itu adalah ayahmu yang sekarat.",
  ui_story_5053_50531601_13_dialog_content = "?!",
  ui_story_5053_50531601_14_dialog_content = "Itu adalah anak-anak dan saudara laki-laki Anda yang mempelajari kebenaran.",
  ui_story_5053_50531601_15_dialog_content = "Hentikan...",
  ui_story_5053_50531601_16_dialog_content = "Itu adalah suamimu yang berpisah denganmu.",
  ui_story_5053_50531601_17_dialog_content = "Aku bilang hentikan!!!",
  ui_story_5053_50531601_18_dialog_content = "Kaulah yang takut akan hal itu... Bukan aku! Kaulah yang bersikeras memiliki emosi yang tidak berguna itu!",
  ui_story_5053_50531601_19_dialog_content = "Saya tidak membutuhkan mereka... Saya tidak membutuhkan keluarga atau perasaan untuk mewujudkan ambisi saya! Saya hanya perlu mengorbankan diri saya sendiri!",
  ui_story_5053_50531601_20_dialog_content = "Aku tahu. Anda hanya ingin menjalani kehidupan yang sederhana dan tidak rumit. Dengan begitu, Anda tidak akan pernah mengalami kebahagiaan atau rasa sakit karena kehilangan.",
  ui_story_5053_50531601_21_dialog_content = "Ketakutan mengetahui emosi itulah yang membuatmu memaksaku keluar dari tubuhmu.",
  ui_story_5053_50531601_22_dialog_content = "Diam... Sudah cukup...",
  ui_story_5053_50531601_23_dialog_content = "Saya tidak pernah bisa mempercayai mereka! Mereka tidak mendengarkan saya... Mereka hanya ingin mengkhianati saya...",
  ui_story_5053_50531601_24_dialog_content = "Manusia bukanlah mesin. Setiap orang memiliki pikiran dan perasaannya masing-masing.",
  ui_story_5053_50531601_25_dialog_content = "\"Sejak aku menghentikanmu hari itu, aku selalu memikirkannya.\"",
  ui_story_5053_50531601_26_dialog_content = "\"Apakah salah kita mempercayakan impian kita kepada orang lain?\"",
  ui_story_5053_50531601_27_dialog_content = "Daniel pernah mengatakan itu sebelumnya, ingat?",
  ui_story_5053_50531601_28_dialog_content = "Dia tidak lain adalah pembohong...",
  ui_story_5053_50531601_29_dialog_content = "Kami terlalu bergantung padanya. Kami memaksakan beban cita-cita kami di pundak satu orang.",
  ui_story_5053_50531601_30_dialog_content = "Anda tahu lebih baik dari saya bahwa keluarga penguasa kota tidak akan pernah bisa mengalami kegembiraan hidup biasa... Namun saya tidak pernah berhenti mengharapkannya.",
  ui_story_5053_50531601_31_dialog_content = "Seorang pembunuh yang kejam, seorang istri yang sempurna untuk seorang penguasa kota...",
  ui_story_5053_50531601_32_dialog_content = "Kami terus-menerus beralih di antara identitas yang diberikan kepada kami oleh orang lain, tetapi tidak satupun dari mereka mencerminkan diri kami yang sebenarnya.",
  ui_story_5053_50531601_33_dialog_content = "Aku masih belum tahu siapa kita sebenarnya...",
  ui_story_5053_50531601_34_dialog_content = "...",
  ui_story_5053_50531601_35_dialog_content = "Tapi satu hal yang saya tahu, adalah bahwa saya tidak ingin kehilangan orang yang saya cintai. Itu akan selalu lebih penting daripada kebenaran.",
  ui_story_5053_50531601_36_dialog_content = "Jadi ikutlah denganku. Saatnya berhenti berkelahi.",
  ui_story_5053_50531601_37_dialog_content = "Aduh! Tanganmu... Rasanya seperti ditusuk duri! Sentuhan sekecil apa pun sangat menyakitkan!",
  ui_story_5053_50531601_38_dialog_content = "Namun, rasanya begitu hangat... Perasaan apa ini?",
  ui_story_5053_50531601_39_dialog_content = "Jadi, begini caranya <color=#FFB400>Cinta</color> terasa.",
  ui_story_5053_50531601_40_dialog_content = "Ibu! Batuk, batuk... Ibu, kamu dimana?!",
  ui_story_5053_50531601_41_dialog_content = "Disini, Mia! Pegang tanganku!",
  ui_story_5053_50531601_42_dialog_content = "PlayerName... Semuanya... Kemana Ibu pergi?",
  ui_story_5053_50531601_43_dialog_content = "Dia... Setelah ledakan...",
  ui_story_5053_50531601_44_dialog_content = "Mantra, Jakine.",
  ui_story_5053_50531601_45_dialog_content = "Lepaskan saya! Saya menolak untuk pergi tanpa saudara perempuan saya!!",
  ui_story_5053_50531601_46_dialog_content = "Tanah runtuh di bawah kaki kita! Buru-buru!",
  ui_story_5053_50531601_47_dialog_content = "Ba-baik!",
  ui_story_5053_50531601_48_dialog_content = "Praesensi iklan!",
  ui_story_5053_50531601_49_dialog_content = "Mari kita kembali ke kenyataan!",
  ui_story_5053_50531601_50_dialog_content = "Omong kosong!",
  ui_story_5053_50531601_51_dialog_content = "Joshua! Aku tidak akan meninggalkanmu!! Joshua!!!",
  ui_story_5053_50531601_52_dialog_content = "Anak nakal yang keras kepala... Jakine, genggam Mia!",
  ui_story_5053_50531601_53_dialog_content = "A-Apa yang kamu katakan? Aku tidak bisa mendengarmu di atas angin!!",
  ui_story_5053_50531601_54_dialog_content = "Aku tidak tahan lagi! PlayerName!!",
  ui_story_5053_50531601_55_dialog_content = "Ahh!!!",
  ui_story_5053_50531601_56_dialog_content = "Lalu pegang aku.",
  ui_story_5053_50531601_57_dialog_content = "Itu kamu...?",
  ui_story_5053_50531601_58_dialog_content = "\"... Aku harap surat ini menemukanmu dengan baik.\"",
  ui_story_5053_50531601_59_dialog_content = "\"Bagaimana kabarmu akhir-akhir ini? Yang lain dan aku baik-baik saja.\"",
  ui_story_5053_50531601_60_dialog_content = "Menulis surat, ya? Untuk siapa ini?",
  ui_story_5053_50531601_61_dialog_content = "Bwaaa! J-Jakine! Kamu menakuti saya...",
  ui_story_5053_50531601_62_dialog_content = "Heehee, maaf soal itu!",
  ui_story_5053_50531601_63_dialog_content = "Selamat sore, PlayerName.",
  ui_story_5053_50531601_64_dialog_content = "Selamat siang! Kalian benar-benar datang lebih awal, pikirku Jakine akan terlambat lagi!",
  ui_story_5053_50531601_65_dialog_content = "Hei, bukan salahku semua orang ingin tahu tentang pekerjaanku! Sulit untuk menjaga jadwal ketika segerombolan orang terus-menerus membombardir Anda dengan pertanyaan...",
  ui_story_5053_50531601_66_dialog_content = "Oh ya, saya yakin menjadi selebriti di Dawn Akademi pasti sangat mengerikan Jakine, \"Sarjana Tamu\".",
  ui_story_5053_50531601_67_dialog_content = "Heehee, jangan panggil aku seperti itu! Kau akan membuatku tersipu...",
  ui_story_5053_50531601_68_dialog_content = "Bagaimanapun, apakah Anda sudah mengurus hal-hal di pihak Anda, Mia?",
  ui_story_5053_50531601_69_dialog_content = "Ya! Semuanya diambil!",
  ui_story_5053_50531601_70_dialog_content = "Sayangnya, kami sangat sibuk Carleen dan saya tidak memiliki kesempatan untuk mengucapkan selamat tinggal satu sama lain ...",
  ui_story_5053_50531601_71_dialog_content = "Jangan khawatir, Anda selalu bisa datang menemuinya di Colossus! Saya akan memberi tahu Anda saat berikutnya dia bergabung.",
  ui_story_5053_50531601_72_dialog_content = "Tidak apa-apa, kita akan bertemu lagi ketika waktunya tepat.",
  ui_story_5053_50531601_73_dialog_content = "B-baiklah...",
  ui_story_5053_50531601_74_dialog_content = "\"Sejak itu, banyak yang terjadi di sini, dengan banyak orang membuat keputusan tak terduga.\"",
  ui_story_5053_50531601_75_dialog_content = "\"Aku berjanji akan menyelesaikan seluruh cerita untukmu, jadi mari kita mulai dari awal.\"",
  ui_story_5053_50531601_76_dialog_content = "\"Pada saat itu, kami berhasil meninggalkan <color=#FFB400>Kristal Memori Abadi</color>\"",
  ui_story_5053_50531601_77_dialog_content = "\"Sebelum kami memiliki waktu untuk memastikan semua orang baik-baik saja, Caleb sudah keluar dari pintu dan berlari kembali ke rumahnya.\"",
  ui_story_5053_50531601_78_dialog_content = "\"Tidak lama kemudian kami mengejarnya... Hanya untuk menemukannya bersama Lady Joshua, yang dia sembunyikan di rumahnya selama bertahun-tahun.\"",
  ui_story_5053_50531601_79_dialog_content = "Mata ibu baru saja bergerak...!",
  ui_story_5053_50531601_80_dialog_content = "Berikan aku obat itu! Yang ada di rak sebelah kiri!",
  ui_story_5053_50531601_81_dialog_content = "T-Tunggu, aku masih mencari kain kasa!",
  ui_story_5053_50531601_82_dialog_content = "Saya memilikinya di sini.",
  ui_story_5053_50531601_83_dialog_content = "\"Setelah prosedur darurat yang menegangkan, Lady Joshua akhirnya keluar dari kondisi kritis. Beberapa hari kemudian, dia bangun.\"",
  ui_story_5053_50531601_84_dialog_content = "\"Sayangnya... Dia telah kehilangan semua ingatannya.\"",
  ui_story_5053_50531601_85_dialog_content = "Bagaimana... Bagaimana ini bisa terjadi? Apakah dia terbaring koma terlalu lama? Atau apakah itu ledakan dari sebelumnya?",
  ui_story_5053_50531601_86_dialog_content = "Apa pun masalahnya, tampaknya saudara perempuan saya tidak lagi menderita kepribadian ganda. Tapi bagaimana caranya...?",
  ui_story_5053_50531601_87_dialog_content = "Mungkinkah itu ada hubungannya dengan Crystal of Eternal Memory, Jakine?",
  ui_story_5053_50531601_88_dialog_content = "Hm... aku tidak akan terlalu yakin.",
  ui_story_5053_50531601_89_dialog_content = "Dan apa artinya itu? Ini serius, lho!",
  ui_story_5053_50531601_90_dialog_content = "\"Untuk memperbaiki Crystal of Eternal Memory, serta membantu pemulihan Lady Joshua...\"",
  ui_story_5053_50531601_91_dialog_content = "\"Jakine memutuskan untuk tinggal di Lumopolis lebih lama, dan mulai melakukan penelitian bersama Caleb.\"",
  ui_story_5053_50531601_92_dialog_content = "\"Dia bahkan memberinya gelar \"Sarjana Berkunjung ke Dawn Akademi,\" hanya untuk membuatnya bahagia.\"",
  ui_story_5053_50531601_93_dialog_content = "\"Saya tidak berpikir gelar itu membawa otoritas nyata, tapi selama Jakine tidak ketahuan...\"",
  ui_story_5053_50531601_94_dialog_content = "Saat ini, yang kita tahu hanyalah, untuk beberapa alasan, Iblis Putih dan Kegelapan Angel melakukan kontak satu sama lain pada akhirnya.",
  ui_story_5053_50531601_94X1_dialog_content = "Saat kedua kepribadian yang saling bertentangan itu menghilang, Lady Joshuakondisi mental kembali normal.",
  ui_story_5053_50531601_95_dialog_content = "Adapun Benih, kita masih harus mempelajarinya secara mendalam, tapi kita hanya bisa mengandalkan Kaleb untuk itu.",
  ui_story_5053_50531601_96_dialog_content = "Dilakukan dengan baik, Utusan Jakine dari Northland. Terima kasih telah tinggal di Lumopolis selama beberapa hari ini dan membantu Caleb dalam usahanya.",
  ui_story_5053_50531601_97_dialog_content = "Ini kehormatan saya! Aku tidak merasa seperti orang luar setelah semua yang kita lalui bersama!",
  ui_story_5053_50531601_98_dialog_content = "Selain itu, aku seharusnya mengisi Crystal of Eternal Memory dengan air dari Lake Mirror, bukan untuk memecahkannya...",
  ui_story_5053_50531601_99_dialog_content = "Oh, ngomong-ngomong, Crystal sudah diperbaiki! Dan sekarang Nyonya itu Joshua telah kembali, Anda dapat menggunakannya kapan saja!",
  ui_story_5053_50531601_100_dialog_content = "Terima kasih. Saya akan menyimpannya dengan aman untuk mencegah orang lain masuk secara tidak sengaja.",
  ui_story_5053_50531601_101_dialog_content = "Yeah... Tapi sebenarnya aku sedikit khawatir tentang Caleb. Sejak Nyonya Joshua bangun, dia ada di dekatnya sepanjang waktu!",
  ui_story_5053_50531601_102_dialog_content = "Saya juga mendengar dia ingin mengundurkan diri dari Dawn Akademi untuk tinggal di rumah dan merawat Lady Joshua penuh waktu... Bertanya-tanya apakah dia mengerti implikasinya sama sekali.",
  ui_story_5053_50531601_103_dialog_content = "Betapa tidak dewasanya dia... Kudengar kau mencari seorang kesatria bernama Sharona. Benarkah itu?",
  ui_story_5053_50531601_104_dialog_content = "Saya. Saya melihat jaringan Anda membuat hidung mereka ke tanah, Tuanku! Maukah Anda memperkenalkan saya padanya?",
  ui_story_5053_50531601_105_dialog_content = "Saya minta maaf, Jakine, Tetapi Sharona meninggalkan Lumopolis beberapa waktu lalu. Saya tidak dapat memenuhi permintaan Anda.",
  ui_story_5053_50531601_106_dialog_content = "Apa? Tapi bukankah mimpinya untuk menjadi ksatria terkuat...?",
  ui_story_5053_50531601_107_dialog_content = "Anda dapat mencarinya di Illumina, tetapi jangan pernah membawa Lumopolis kepada saya.",
  ui_story_5053_50531601_108_dialog_content = "Dan jangan lupa bahwa apa yang terjadi di Crystal itu tidak nyata, tidak peduli seberapa kuat ikatan yang terbentuk antara kalian berdua...",
  ui_story_5053_50531601_109_dialog_content = "Itu hanyalah sebuah aspirasi. Banyak yang telah berubah selama dua belas tahun.",
  ui_story_5053_50531601_110_dialog_content = "Begitu... Tidak apa-apa, selama kita tetap setia pada siapa kita, kita masih bisa menjadi sahabat!",
  ui_story_5053_50531601_111_dialog_content = "Tetap setia pada diri sendiri, katamu... Kamu benar.",
  ui_story_5053_50531601_112_dialog_content = "\"Saya pikir Bu Joshua kehilangan ingatannya akan menjerumuskan keluarganya ke dalam kesedihan lagi.\"",
  ui_story_5053_50531601_113_dialog_content = "\"Kecuali mereka tidak merasa kalah, tetapi dengan cepat bersukacita dalam reuni setelah kekecewaan singkat.\"",
  ui_story_5053_50531601_114_dialog_content = "\"Senang melihat keluarga bahagia dan utuh... Sungguh ikatan yang sederhana namun sempurna yang mereka semua bagikan.\"",
  ui_story_5053_50531601_115_dialog_content = "\"Tetapi <color=#FFB400>Tuan Kota dan keluarganya</color> terlalu banyak menjadi pusat perhatian bagi mereka untuk menikmati kebahagiaan keluarga normal.",
  ui_story_5053_50531601_116_dialog_content = "<color=#e8d9bb>Magnus Manor, Rumah Kaleb</color>",
  ui_story_5053_50531601_117_dialog_content = "Aku kembali, kak! Lihat ini. Ini teh buah terbaru dari Umbraton. Taruhan Anda akan menyukainya!",
  ui_story_5053_50531601_118_dialog_content = "Selamat datang di rumah, paman.",
  ui_story_5053_50531601_119_dialog_content = "Selamat Datang kembali. Eh, bukankah hari ini hari kerja? Apakah kamu tidak bekerja, Caleb?",
  ui_story_5053_50531601_120_dialog_content = "Tidak ada pekerjaan yang sama pentingnya dengan Anda. Saya menyerahkan pengunduran diri saya ke Dawn Akademi sudah. Aku akan bersamamu mulai sekarang.",
  ui_story_5053_50531601_121_dialog_content = "Apa, Anda mengundurkan diri? Apakah Anda akan meninggalkan karir dan aspirasi Anda atas saya?",
  ui_story_5053_50531601_122_dialog_content = "Jangan seperti itu, kak. Tidak ada yang sebesar hidup bahagia dengan keluarga Anda.",
  ui_story_5053_50531601_123_dialog_content = "Dan Mia juga ingin kembali ke keluarganya di Lumopolis. Bukankah itu benar, Mia?",
  ui_story_5053_50531601_124_dialog_content = "Yah... Sebenarnya, itulah yang ingin kubicarakan dengan Ibu. Saya ingin tinggal di Umbraton.",
  ui_story_5053_50531601_125_dialog_content = "Apa? Mengapa Anda berpikir begitu sekarang? Telah melakukan Schwartz menggertakmu lagi?",
  ui_story_5053_50531601_126_dialog_content = "Tidak, itu adalah keputusanku sendiri. Ayah juga ada di belakangnya.",
  ui_story_5053_50531601_127_dialog_content = "Saya lemah dan malang di masa lalu, terpaksa pergi dan menanggung kesulitan ...",
  ui_story_5053_50531601_128_dialog_content = "Tapi saya juga harus melihat kebenaran dunia di luar Lumopolis dan itu membuat saya seperti sekarang ini. Namun, saya merasa itu tidak cukup.",
  ui_story_5053_50531601_129_dialog_content = "Anda harus tahu sekarang bahwa dengan Anda mengambil banyak waktu istirahat dan saya datang dan pergi dalam kerudung, desas-desus mulai terbang di Lumopolis Gardens.",
  ui_story_5053_50531601_130_dialog_content = "Ayah bahkan tidak bisa datang ke sini untuk melihat Ibu karena itu... meskipun kami menyembunyikannya.",
  ui_story_5053_50531601_131_dialog_content = "Saya tahu! Dan saya sudah mencari solusinya. Lebih buruk menjadi lebih buruk, kita akan pindah dari Lumopolis!",
  ui_story_5053_50531601_132_dialog_content = "Jadi bagaimana jika istri Tuan Kota hidup kembali setelah bertahun-tahun...",
  ui_story_5053_50531601_133_dialog_content = "Anda membutuhkan kekuatan nyata untuk menantang Schwartz! Hanya mengandalkan muckraking politik tidak akan berhasil!",
  ui_story_5053_50531601_134_dialog_content = "Ya, saya tahu semua itu bukan kesalahan keluarga, tapi itu masih sesuatu yang harus kami tanggung.",
  ui_story_5053_50531601_135_dialog_content = "Aku akhirnya mengerti bagaimana perasaan Ayah sekarang... Karena itulah aku tidak lagi mengingini pelukan ibuku.",
  ui_story_5053_50531601_136_dialog_content = "Karena saya tidak bisa bertahan di bawah sorotan di Lumopolis, biarkan saya tetap dalam kegelapan sebagai bayangan.",
  ui_story_5053_50531601_137_dialog_content = "Saya akan belajar sebanyak-banyaknya dari Pak. Istvan di Umbraton sebanyak mungkin, tumbuh dari yang lemah yang membutuhkan perlindungan menjadi ksatria yang gagah berani.",
  ui_story_5053_50531601_138_dialog_content = "Maka giliranku untuk melindungi semua orang!",
  ui_story_5053_50531601_139_dialog_content = "Mengapa Anda merasa seperti itu? Apakah Anda tidak berpikir Anda bisa percaya dan bergantung pada saya? Ajak dia keluar, Kak!",
  ui_story_5053_50531601_140_dialog_content = "Caleb, aku <color=#FFB400>seseorang tanpa ingatan</color>. Saya tidak memiliki masa lalu, saya juga tidak berlama-lama memikirkannya.",
  ui_story_5053_50531601_141_dialog_content = "Saya sangat senang bahwa Anda menemukan impian Anda, Mia. Bekerja keras saja, sayang, dan aku yakin kamu akan memiliki masa depan yang menyenangkan di depanmu.",
  ui_story_5053_50531601_142_dialog_content = "Ibu... Terima kasih.",
  ui_story_5053_50531601_143_dialog_content = "Anda baru saja mengingatkan saya, Mia, ada dunia yang menarik di luar sana juga. Aku harus melihatnya sendiri.",
  ui_story_5053_50531601_144_dialog_content = "Tunggu sebentar, apa maksudmu dengan itu, kak?",
  ui_story_5053_50531601_145_dialog_content = "\"Ya, setelah semua yang dia lalui, Mia masih memilih untuk pergi.\"",
  ui_story_5053_50531601_146_dialog_content = "\"Dia membuat keputusan sendiri, dan saya dengan tulus merasa bahagia untuknya.\"",
  ui_story_5053_50531601_147_dialog_content = "\"Sementara itu, pengunduran diri Caleb ditolak.\"",
  ui_story_5053_50531601_148_dialog_content = "\"Sepertinya dia sering datang dengan segala macam alasan terburu-buru untuk mengundurkan diri, jadi Akademi menolaknya karena kebiasaan.\"",
  ui_story_5053_50531601_149_dialog_content = "\"Untuk Nyonya Joshua, dia tampak terinspirasi dan mulai memiliki idenya sendiri.\"",
  ui_story_5053_50531601_150_dialog_content = "\"Dia menyelinap keluar dari Lumopolis dalam perjalanan solo.\"",
  ui_story_5053_50531601_151_dialog_content = "Terima kasih, PlayerName, karena menyelundupkanku ke Colossus.",
  ui_story_5053_50531601_152_dialog_content = "Senang melakukan itu. Tapi kenapa Anda tidak mengucapkan selamat tinggal kepada mereka?",
  ui_story_5053_50531601_153_dialog_content = "Anda lebih pintar dari itu. Mereka tidak akan pernah membiarkan saya pergi jika mereka tahu saya akan pergi.",
  ui_story_5053_50531601_154_dialog_content = "Tapi aku harus pergi, bukan hanya untuk melindungi mereka, tapi sebagai pelajaran terakhir bagi mereka sebagai ibu dan adik.",
  ui_story_5053_50531601_155_dialog_content = "Apakah Anda benar-benar kehilangan ingatan Anda, Lady Joshua?",
  ui_story_5053_50531601_156_dialog_content = "Tentu saja. Apakah Anda tidak menggunakan kekuatan Caelestite Anda untuk mengintip rahasia seorang wanita sekarang!",
  ui_story_5053_50531601_157_dialog_content = "Baiklah, kalau begitu akan kuberitahu mereka kau pergi saat aku kembali... Itu tidak berbohong pada atasanmu, kan?",
  ui_story_5053_50531601_158_dialog_content = "Nah, itu untuk saya.",
  ui_story_5053_50531601_159_dialog_content = "Apa?!",
  ui_story_5053_50531601_160_dialog_content = "Cuma bercanda! Daniel mungkin sudah mengetahuinya. Kita tidak membutuhkan banyak kata untuk berkomunikasi.",
  ui_story_5053_50531601_161_dialog_content = "Adapun Carleen, dia sangat mirip dengan Daniel... Kudengar kau sangat dekat dengannya, jadi kau juga harus tahu itu.",
  ui_story_5053_50531601_162_dialog_content = "Dia tampak begitu kuat dan kompeten ketika dia sebenarnya hanya bertahan. Ini adalah rahasia umum yang semua orang tahu untuk tidak membicarakannya.",
  ui_story_5053_50531601_163_dialog_content = "Dia pasti cukup mampu untuk menemukan kebenaran yang ingin dia ungkapkan. Jika dia tidak...",
  ui_story_5053_50531601_164_dialog_content = "Itu berarti dia masih belum siap menerima kebenaran.",
  ui_story_5053_50531601_165_dialog_content = "Terlepas dari semua pidato itu, saya juga memiliki sisi tersembunyi pada diri saya.",
  ui_story_5053_50531601_166_dialog_content = "Jika saya tidak ditanamkan, saya mungkin tidak akan pernah menyadari bahwa saya telah menekan sisi gelap dalam diri saya.",
  ui_story_5053_50531601_167_dialog_content = "Wanita Joshua...",
  ui_story_5053_50531601_168_dialog_content = "Selain menerima orang lain dengan kebaikan, penting juga untuk mendorong mereka maju dengan tegas. Itu bentuk lain untuk menunjukkan bahwa Anda peduli, bukan?",
  ui_story_5053_50531601_169_dialog_content = "Benar, bahkan safe haven bisa menjadi penghambat pertumbuhan.",
  ui_story_5053_50531601_170_dialog_content = "Carleen sekarang membutuhkan teman yang dapat diandalkan dan berpikiran sama lebih dari sebelumnya.",
  ui_story_5053_50531601_171_dialog_content = "Jadi, apakah Anda akan terus maju bersama Carleen, PlayerName?",
  ui_story_5053_50531601_X171_option_content = "Tentu, bukan masalah!",
  ui_story_5053_50531601_X172_option_content = "Siapa, aku...?",
  ui_story_5053_50531601_X173_dialog_content = "Sebagai anggota ras yang sama sekali berbeda dari kami orang Aurorian, Last Caelestite, saya melihat masa depan yang cemerlang di depan Anda.",
  ui_story_5053_50531601_X174_dialog_content = "Yang juga tak ternilai harganya dan selalu terabaikan di lingkungan yang dekat seperti Lumopolis.",
  ui_story_5053_50531601_X175_dialog_content = "Saya sepenuhnya yakin Anda bisa membimbing Carleen... Tidak, bimbing lebih banyak orang ke hari esok yang lebih cerah.",
  ui_story_5053_50531601_X176_dialog_content = "Kehadiranmu dan keberanian Mia menunjukkan padaku potensi yang ada di dunia ini.",
  ui_story_5053_50531601_X177_dialog_content = "Mungkin saya akan menemukan apa yang sebenarnya saya cari setelah melihatnya.",
  ui_story_5053_50531601_X178_dialog_content = "Kemudian bawa pencerahan itu kembali ke orang yang saya cintai suatu hari nanti...",
  ui_story_5053_50531601_X179_dialog_content = "\"Jadi, saya mengucapkan selamat tinggal kepada Anda dan membawa berita keberangkatan Anda kembali ke Lumopolis.\"",
  ui_story_5053_50531601_X180_dialog_content = "\"Beberapa tersenyum dan memberi salam. Beberapa dengan senang hati menerimanya setelah pulih dari keterkejutan.\"",
  ui_story_5053_50531601_X181_dialog_content = "\"Beberapa tidak bisa memahaminya dan pergi dengan marah. Namun, beberapa tampaknya telah melihatnya datang.\"",
  ui_story_5053_50531601_X182_dialog_content = "\"Setelah beberapa keributan, semua orang menerimanya dan memilih untuk tidak mengganggu kehidupan baru si amnesia.\"",
  ui_story_5053_50531601_X183_dialog_content = "\"Adapun kamu menjaga korespondensi denganku secara rahasia, itu akan menjadi antara kita berdua.\"",
  ui_story_5053_50531601_X184_dialog_content = "\"Aku juga akan mengabarimu tentang keluargamu seperti yang dijanjikan.\"",
  ui_story_5053_50531601_172_dialog_content = "\"Lain kali kita bertemu, saya harap kita bisa berbagi petualangan satu sama lain sebagai sesama pelancong.\"",
  ui_story_5053_50531601_173_dialog_content = "PlayerName! Letakkan pulpennya sudah!!",
  ui_story_5053_50531601_174_dialog_content = "Bwaaa! K-Kau membuatku takut lagi, Jakine!!",
  ui_story_5053_50531601_175_dialog_content = "Oh tidak, kali ini kamu tidak bisa menyalahkanku, sobat! Aku akan kembali ke Northland hari ini, dan kau dan Mia berjanji untuk mengantarku! Sekarang berhenti mencurahkan isi hati Anda, dan ayolah!",
  ui_story_5053_50531601_176_dialog_content = "T-Tunggu sebentar, Jakine! Seorang Kurir seharusnya ada di sini sebentar lagi untuk mengantarkan suratku!",
  ui_story_5053_50531601_177_dialog_content = "Selain itu, Anda tidak pernah peduli tentang terlambat sebelumnya ...",
  ui_story_5053_50531601_178_dialog_content = "Hai! Saya mendengarnya!",
  ui_story_5053_50531601_179_dialog_content = "Heehee, sepertinya kita harus menunggu sedikit lebih lama.",
  ui_story_5053_50531601_180_dialog_content = "Omong-omong, PlayerName, apakah Anda mendapatkan kartu pos melalui pos baru-baru ini?",
  ui_story_5053_50531601_181_dialog_content = "Sebuah kartu pos?",
  ui_story_5053_50531601_182_dialog_content = "Oh, maksudmu kartu pos dari Lady Joshua, Kanan? Aku punya satu juga!",
  ui_story_5053_50531601_183_dialog_content = "Dia bilang dia tiba di sebuah kota kecil di antah berantah dan bahkan bertemu dengan burung yang bisa berbicara!",
  ui_story_5053_50531601_184_dialog_content = "Hmm... Dia pasti berbicara tentang seorang demi-human. Ibu berkata mereka menjadi teman dekat dalam waktu singkat... Aku sangat bahagia untuknya!",
  ui_story_5053_50531601_185_dialog_content = "Hah? Apakah saya satu-satunya yang tidak mendapatkan kartu pos...?",
  ui_story_5053_50531601_186_dialog_content = "Kurasa dia pasti menyukai kami lebih darimu, PlayerName! Apakah Anda melakukan sesuatu yang membuatnya kesal?",
  ui_story_5053_50531601_187_dialog_content = "T-Tentu saja tidak! Saya yakin kartu pos saya akan ada di sini kapan saja sekarang, Anda akan lihat!",
  ui_story_5053_50531601_188_dialog_content = "Ketuk, ketuk! Eho Kurir, siap melayani Anda!",
  ui_story_5053_50531601_189_dialog_content = "Wah, waktu yang tepat!",
  ui_story_5053_50531601_190_dialog_content = "Yang akan datang! Sekali lagi terima kasih telah mengirimkan surat saya, Eho.",
  ui_story_5053_50531601_191_dialog_content = "Jangan sebutkan itu! Aku ambil itu... Dan ini, amplop ini untukmu!",
  ui_story_5053_50531601_192_dialog_content = "Untuk saya? Hei, ini...!",
  ui_story_5053_50531601_193_dialog_content = "Hal menyenangkan apa yang kamu dapatkan di sana?",
  ui_story_5053_50531601_194_dialog_content = "Kenapa, PlayerName?",
  ui_story_5053_50531601_195_dialog_content = "Bisakah kita melihatnya juga, PlayerName?",
  ui_story_5053_50531601_196_dialog_content = "Maaf, tapi saya tidak bisa menunjukkannya kepada Anda!",
  ui_story_5053_50531601_197_dialog_content = "\"Sayang PlayerName, Saya harap Anda baik-baik saja?\"",
  ui_story_5053_50531601_198_dialog_content = "\"Saat ini saya sedang dalam perjalanan ke...\"",
  ui_story_5053_50531601_199_dialog_content = "Petik mawar, hanya untuk bayiku... ♪",
  ui_story_5053_50531601_200_dialog_content = "Angin sepoi-sepoi di wajahmu dan senyummu adalah semua yang aku butuhkan... ♪",
  ui_story_5053_50531601_201_dialog_content = "Petik juga sekuntum mawar untuk Mommy dan Daddy... ♪",
  ui_story_5053_50531601_202_dialog_content = "Meskipun dunia mungkin berubah, cinta kita akan selalu tetap sama... ♪"
}
return config
